export default "layer is a list of vertex IDs\\n        get_vertex_predecessors: Function to get the predecessor IDs of a vertex\\n\\n    Returns:\\n        Sorted layers with single chat input first\\n\\n    Raises:\\n        ValueError: If there are multiple chat inputs in the graph\\n    \\\"\\\"\\\"\\n    chat_input = None\\n    chat_input_layer_idx = None\\n\\n    # Find chat input and validate only one exists\\n    for layer_idx, layer in enumerate(vertices_layers):\\n        for vertex_id in layer:\\n            if \\\"ChatInput\\\" in vertex_id and get_vertex_predecessors(vertex_id):\\n                return vertices_layers\\n            if \\\"ChatInput\\\" in vertex_id:\\n                if chat_input is not None:\\n                    msg = \\\"Only one chat input is allowed in the graph\\\"\\n                    raise ValueError(msg)\\n                chat_input = vertex_id\\n                chat_input_layer_idx = layer_idx\\n\\n    if not chat_input:\\n        return vertices_layers\\n    # If chat input already in first layer, just move it to index 0\\n    if chat_input_layer_idx == 0:\\n        # If chat input is alone in first layer, keep as-is\\n        if len(vertices_layers[0]) == 1:\\n            return vertices_layers\\n\\n        # Otherwise move chat input to its own layer at the start\\n        vertices_layers[0].remove(chat_input)\\n        return [[chat_input], *vertices_layers]\\n\\n    # Otherwise create new layers with chat input first\\n    result_layers = []\\n    for layer in vertices_layers:\\n        layer_vertices = [v for v in layer if v != chat_input]\\n        if layer_vertices:\\n            result_layers.append(layer_vertices)\\n\\n    return [[chat_input], *result_layers]\\n\\n\\ndef get_sorted_vertices(\\n    vertices_ids: list[str],\\n    cycle_vertices: set[str],\\n    stop_component_id: str | None = None,\\n    start_component_id: str | None = None,\\n    graph_dict: dict[str, Any] | None = None,\\n    in_degree_map: dict[str, int] | None = None,\\n    successor_map: dict[str, list[str]] | None = None,\\n    predecessor_map: dict[str, list[str]] | None = None,\\n    is_input_vertex: Callable[[str], bool] | None = None,\\n    get_vertex_predecessors: Callable[[str], list[str]] | None = None,\\n    get_vertex_successors: Callable[[str], list[str]] | None = None,\\n    *,\\n    is_cyclic: bool = False,\\n) -> tuple[list[str], list[list[str]]]:\\n    \\\"\\\"\\\"Get sorted vertices in a graph.\\n\\n    Args:\\n        vertices_ids: List of vertex IDs to sort\\n        cycle_vertices: Set of vertices that form a cycle\\n        stop_component_id: ID of the stop component (if any)\\n        start_component_id: ID of the start component (if any)\\n        graph_dict: Dictionary containing graph information\\n        in_degree_map: Map of vertex IDs to their in-degree\\n        successor_map: Map of vertex IDs to their successors\\n        predecessor_map: Map of vertex IDs to their predecessors\\n        is_input_vertex: Function to check if a vertex is an input vertex\\n        get_vertex_predecessors: Function to get predecessors of a vertex\\n        get_vertex_successors: Function to get successors of a vertex\\n        is_cyclic: Whether the graph is cyclic\\n\\n    Returns:\\n        Tuple of (first layer vertices, remaining layer vertices)\\n    \\\"\\\"\\\"\\n    # Handle cycles by converting stop to start\\n    if stop_component_id in cycle_vertices:\\n        start_component_id = stop_component_id\\n        stop_component_id = None\\n\\n    # Build in_degree_map if not provided\\n    if in_degree_map is None:\\n        in_degree_map = {}\\n        for vertex_id in vertices_ids:\\n            if get_vertex_predecessors is not None:\\n                in_degree_map[vertex_id] = len(get_vertex_predecessors(vertex_id))\\n            else:\\n                in_degree_map[vertex_id] = 0\\n\\n    # Build successor_map if not provided\\n    if successor_map is None:\\n        successor_map = {}\\n        for vertex_id in vertices_ids:\\n            if get_vertex_successors is not None:\\n                successor_map[vertex_id] = get_vertex_successors(vertex_id)\\n            else:\\n                successor_map[vertex_id] = []\\n\\n    # Build predecessor_map if not provided\\n    if predecessor_map is None:\\n        predecessor_map = {}\\n        for vertex_id in vertices_ids:\\n            if get_vertex_predecessors is not None:\\n                predecessor_map[vertex_id] = get_vertex_predecessors(vertex_id)\\n            else:\\n                predecessor_map[vertex_id] = []\\n\\n    # If we have a stop component, we need to filter out all vertices\\n    # that are not predecessors of the stop component\\n    if stop_component_id is not None:\\n        filtered_vertices = filter_vertices_up_to_vertex(\\n            vertices_ids,\\n            stop_component_id,\\n            get_vertex_predecessors=get_vertex_predecessors,\\n            get_vertex_successors=get_vertex_successors,\\n            graph_dict=graph_dict,\\n        )\\n        vertices_ids = list(filtered_vertices)\\n\\n    # If we have a start component, we need to filter out unconnected vertices\\n    # but keep vertices that are connected to the graph even if not reachable from start\\n    if start_component_id is not None:\\n        # First get all vertices reachable from start\\n        reachable_vertices = filter_vertices_from_vertex(\\n            vertices_ids,\\n            start_component_id,\\n            get_vertex_predecessors=get_vertex_predecessors,\\n            get_vertex_successors=get_vertex_successors,\\n            graph_dict=graph_dict,\\n        )\\n        # Then get all vertices that can reach any reachable vertex\\n        connected_vertices = set()\\n        for vertex in reachable_vertices:\\n            connected_vertices.update(\\n                filter_vertices_up_to_vertex(\\n                    vertices_ids,\\n                    vertex,\\n                    get_vertex_predecessors=get_vertex_predecessors,\\n                    get_vertex_successors=get_vertex_successors,\\n                    graph_dict=graph_dict,\\n                )\\n            )\\n        vertices_ids = list(connected_vertices)\\n\\n    # Get the layers\\n    layers = layered_topological_sort(\\n        vertices_ids=set(vertices_ids),\\n        in_degree_map=in_degree_map,\\n        successor_map=successor_map,\\n        predecessor_map=predecessor_map,\\n        start_id=start_component_id,\\n        is_input_vertex=is_input_vertex,\\n        cycle_vertices=cycle_vertices,\\n        is_cyclic=is_cyclic,\\n    )\\n\\n    # Split into first layer and remaining layers\\n    if not layers:\\n        return [], []\\n\\n    first_layer = layers[0]\\n    remaining_layers = layers[1:]\\n\\n    # If we have a stop component, we need to filter out all vertices\\n    # that are not predecessors of the stop component\\n    if stop_component_id is not None and remaining_layers and stop_component_id not in remaining_layers[-1]:\\n        remaining_layers[-1].append(stop_component_id)\\n\\n    # Sort chat inputs first and sort each layer by dependencies\\n    all_layers = [first_layer, *remaining_layers]\\n    if get_vertex_predecessors is not None and start_component_id is None:\\n        all_layers = sort_chat_inputs_first(all_layers, get_vertex_predecessors)\\n    if get_vertex_successors is not None:\\n        all_layers = sort_layer_by_dependency(all_layers, get_vertex_successors)\\n\\n    if not all_layers:\\n        return [], []\\n\\n    return all_layers[0], all_layers[1:]\\n\\n\\ndef filter_vertices_up_to_vertex(\\n    vertices_ids: list[str],\\n    vertex_id: str,\\n    get_vertex_predecessors: Callable[[str], list[str]] | None = None,\\n    get_vertex_successors: Callable[[str], list[str]] | None = None,\\n    graph_dict: dict[str, Any] | None = None,\\n) -> set[str]:\\n    \\\"\\\"\\\"Filter vertices up to a given vertex.\\n\\n    Args:\\n        vertices_ids: List of vertex IDs to filter\\n        vertex_id: ID of the vertex to filter up to\\n        get_vertex_predecessors: Function to get predecessors of a vertex\\n        get_vertex_successors: Function to get successors of a vertex\\n        graph_dict: Dictionary containing graph information\\n        parent_node_map: Map of vertex IDs to their parent node IDs\\n\\n    Returns:\\n        Set of vertex IDs that are predecessors of the given vertex\\n    \\\"\\\"\\\"\\n    vertices_set = set(vertices_ids)\\n    if vertex_id not in vertices_set:\\n        return set()\\n\\n    # Build predecessor map if not provided\\n    if get_vertex_predecessors is None:\\n        if graph_dict is None:\\n            msg = \\\"Either get_vertex_predecessors or graph_dict must be provided\\\"\\n            raise ValueError(msg)\\n\\n        def get_vertex_predecessors(v):\\n            return graph_dict[v][\\\"predecessors\\\"]\\n\\n    # Build successor map if not provided\\n    if get_vertex_successors is None:\\n        if graph_dict is None:\\n            return set()\\n\\n        def get_vertex_successors(v):\\n            return graph_dict[v][\\\"successors\\\"]\\n\\n    # Start with the target vertex\\n    filtered_vertices = {vertex_id}\\n    queue = deque([vertex_id])\\n\\n    # Process vertices in breadth-first order\\n    while queue:\\n        current_vertex = queue.popleft()\\n        for predecessor in get_vertex_predecessors(current_vertex):\\n            if predecessor in vertices_set and predecessor not in filtered_vertices:\\n                filtered_vertices.add(predecessor)\\n                queue.append(predecessor)\\n\\n    return filtered_vertices\\n\\n\\ndef filter_vertices_from_vertex(\\n    vertices_ids: list[str],\\n    vertex_id: str,\\n    get_vertex_predecessors: Callable[[str], list[str]] | None = None,\\n    get_vertex_successors: Callable[[str], list[str]] | None = None,\\n    graph_dict: dict[str, Any] | None = None,\\n) -> set[str]:\\n    \\\"\\\"\\\"Filter vertices starting from a given vertex.\\n\\n    Args:\\n        vertices_ids: List of vertex IDs to filter\\n        vertex_id: ID of the vertex to start filtering from\\n        get_vertex_predecessors: Function to get predecessors of a vertex\\n        get_vertex_successors: Function to get successors of a vertex\\n        graph_dict: Dictionary containing graph information\\n\\n    Returns:\\n        Set of vertex IDs that are successors of the given vertex\\n    \\\"\\\"\\\"\\n    vertices_set = set(vertices_ids)\\n    if vertex_id not in vertices_set:\\n        return set()\\n\\n    # Build predecessor map if not provided\\n    if get_vertex_predecessors is None:\\n        if graph_dict is None:\\n            msg = \\\"Either get_vertex_predecessors or graph_dict must be provided\\\"\\n            raise ValueError(msg)\\n\\n        def get_vertex_predecessors(v):\\n            return graph_dict[v][\\\"predecessors\\\"]\\n\\n    # Build successor map if not provided\\n    if get_vertex_successors is None:\\n        if graph_dict is None:\\n            return set()\\n\\n        def get_vertex_successors(v):\\n            return graph_dict[v][\\\"successors\\\"]\\n\\n    # Start with the target vertex\\n    filtered_vertices = {vertex_id}\\n    queue = deque([vertex_id])\\n\\n    # Process vertices in breadth-first order\\n    while queue:\\n        current_vertex = queue.popleft()\\n        for successor in get_vertex_successors(current_vertex):\\n            if successor in vertices_set and successor not in filtered_vertices:\\n                filtered_vertices.add(successor)\\n                queue.append(successor)\\n\\n    return filtered_vertices\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/schema.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"fb23df28bb699bc65b4f31cef3f51bd64d0c3e56d0a75204b9f9376095d53e88\",\"content\":\"from enum import Enum\\nfrom typing import Any\\n\\nfrom pydantic import BaseModel, Field, field_serializer, model_validator\\n\\nfrom lfx.schema.properties import Usage\\nfrom lfx.schema.schema import OutputValue, StreamURL\\nfrom lfx.serialization.serialization import serialize\\nfrom lfx.utils.schemas import ChatOutputResponse, ContainsEnumMeta\\n\\n\\nclass ResultData(BaseModel):\\n    results: Any | None = Field(default_factory=dict)\\n    artifacts: Any | None = Field(default_factory=dict)\\n    outputs: dict | None = Field(default_factory=dict)\\n    logs: dict | None = Field(default_factory=dict)\\n    messages: list[ChatOutputResponse] | None = Field(default_factory=list)\\n    timedelta: float | None = None\\n    duration: str | None = None\\n    component_display_name: str | None = None\\n    component_id: str | None = None\\n    used_frozen_result: bool | None = False\\n    token_usage: Usage | None = None\\n\\n    @field_serializer(\\\"results\\\")\\n    def serialize_results(self, value):\\n        if isinstance(value, dict):\\n            return {key: serialize(val) for key, val in value.items()}\\n        return serialize(value)\\n\\n    @model_validator(mode=\\\"before\\\")\\n    @classmethod\\n    def validate_model(cls, values):\\n        if not values.get(\\\"outputs\\\") and values.get(\\\"artifacts\\\"):\\n            # Build the log from the artifacts\\n\\n            for key in values[\\\"artifacts\\\"]:\\n                message = values[\\\"artifacts\\\"][key]\\n\\n                # ! Temporary fix\\n                if message is None:\\n                    continue\\n\\n                if not isinstance(message, dict):\\n                    continue\\n\\n                if \\\"stream_url\\\" in message and \\\"type\\\" in message:\\n                    stream_url = StreamURL(location=message[\\\"stream_url\\\"])\\n                    values[\\\"outputs\\\"].update({key: OutputValue(message=stream_url, type=message[\\\"type\\\"])})\\n                elif \\\"type\\\" in message:\\n                    values[\\\"outputs\\\"].update({key: OutputValue(message=message, type=message[\\\"type\\\"])})\\n        return values\\n\\n\\nclass InterfaceComponentTypes(str, Enum, metaclass=ContainsEnumMeta):\\n    ChatInput = \\\"ChatInput\\\"\\n    ChatOutput = \\\"ChatOutput\\\"\\n    TextInput = \\\"TextInput\\\"\\n    TextOutput = \\\"TextOutput\\\"\\n    DataOutput = \\\"DataOutput\\\"\\n    WebhookInput = \\\"Webhook\\\"\\n\\n\\nCHAT_COMPONENTS = [InterfaceComponentTypes.ChatInput, InterfaceComponentTypes.ChatOutput]\\nRECORDS_COMPONENTS = [InterfaceComponentTypes.DataOutput]\\nINPUT_COMPONENTS = [\\n    InterfaceComponentTypes.ChatInput,\\n    InterfaceComponentTypes.WebhookInput,\\n    InterfaceComponentTypes.TextInput,\\n]\\nOUTPUT_COMPONENTS = [\\n    InterfaceComponentTypes.ChatOutput,\\n    InterfaceComponentTypes.DataOutput,\\n    InterfaceComponentTypes.TextOutput,\\n]\\n\\n\\nclass RunOutputs(BaseModel):\\n    inputs: dict = Field(default_factory=dict)\\n    outputs: list[ResultData | None] = Field(default_factory=list)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/state/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/state/model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"29cdb1c8442f25afac16af618ea08feed5d37859499946f92afc84705b21fd75\",\"content\":\"from collections.abc import Callable\\nfrom types import FunctionType, MethodType\\nfrom typing import Any\\n\\nfrom pydantic import BaseModel, ConfigDict, computed_field, create_model\\nfrom pydantic.fields import FieldInfo\\n\\nfrom lfx.custom.annotation_validation import resolve_method_return_annotation\\n\\n\\ndef __validate_method(method: Callable) -> None:\\n    \\\"\\\"\\\"Validates a method by checking if it has the required attributes.\\n\\n    This function ensures that the given method belongs to a class with the necessary\\n    structure for output handling. It checks for the presence of a __self__ attribute\\n    on the method and a get_output_by_method attribute on the method's class.\\n\\n    Args:\\n        method (Callable): The method to be validated.\\n\\n    Raises:\\n        ValueError: If the method does not have a __self__ attribute or if the method's\\n                    class does not have a get_output_by_method attribute.\\n\\n    Example:\\n        >>> class ValidClass:\\n        ...     def get_output_by_method(self):\\n        ...         pass\\n        ...     def valid_method(self):\\n        ...         pass\\n        >>> __validate_method(ValidClass().valid_method)  # This will pass\\n        >>> __validate_method(lambda x: x)  # This will raise a ValueError\\n    \\\"\\\"\\\"\\n    if not hasattr(method, \\\"__self__\\\"):\\n        msg = f\\\"Method {method} does not have a __self__ attribute.\\\"\\n        raise ValueError(msg)\\n    if not hasattr(method.__self__, \\\"get_output_by_method\\\"):\\n        msg = f\\\"Method's class {method.__self__} must have a get_output_by_method attribute.\\\"\\n        raise ValueError(msg)\\n\\n\\ndef build_output_getter(method: Callable, *, validate: bool = True) -> Callable:\\n    \\\"\\\"\\\"Builds an output getter function for a given method in a graph component.\\n\\n    This function creates a new callable that, when invoked, retrieves the output\\n    of the specified method using the get_output_by_method of the method's class.\\n    It's used in creating dynamic state models for graph components.\\n\\n    Args:\\n        method (Callable): The method for which to build the output getter.\\n        validate (bool, optional): Whether to validate the method before building\\n                                   the getter. Defaults to True.\\n\\n    Returns:\\n        Callable: The output getter function. When called, this function returns\\n                  the value of the output associated with the original method.\\n\\n    Raises:\\n        ValueError: If the method has no return type annotation or if validation fails.\\n\\n    Notes:\\n        - The getter function returns UNDEFINED if the output has not been set.\\n        - When validate is True, the method must belong to a class with a\\n          'get_output_by_method' attribute.\\n        - This function is typically used internally by create_state_model.\\n\\n    Example:\\n        >>> class ChatComponent:\\n        ...     def get_output_by_method(self, method):\\n        ...         return type('Output', (), {'value': \\\"Hello, World!\\\"})()\\n        ...     def get_message(self) -> str:\\n        ...         pass\\n        >>> component = ChatComponent()\\n        >>> getter = build_output_getter(component.get_message)\\n        >>> print(getter(None))  # This will print \\\"Hello, World!\\\"\\n    \\\"\\\"\\\"\\n\\n    def output_getter(_):\\n        if validate:\\n            __validate_method(method)\\n        methods_class = method.__self__\\n        output = methods_class.get_output_by_method(method)\\n        return output.value\\n\\n    return_type = resolve_method_return_annotation(method)\\n\\n    if return_type is None:\\n        function = object.__getattribute__(method, \\\"__func__\\\") if type(method) is MethodType else method\\n        annotations = object.__getattribute__(function, \\\"__annotations__\\\") if type(function) is FunctionType else {}\\n        has_return_annotation = isinstance(annotations, dict) and dict.__contains__(annotations, \\\"return\\\")\\n        if has_return_annotation:\\n            msg = f\\\"Method {method.__name__} return type annotation could not be resolved safely.\\\"\\n        else:\\n            msg = f\\\"Method {method.__name__} has no return type annotation.\\\"\\n        raise ValueError(msg)\\n    output_getter.__annotations__[\\\"return\\\"] = return_type\\n    return output_getter\\n\\n\\ndef build_output_setter(method: Callable, *, validate: bool = True) -> Callable:\\n    \\\"\\\"\\\"Build an output setter function for a given method in a graph component.\\n\\n    This function creates a new callable that, when invoked, sets the output\\n    of the specified method using the get_output_by_method of the method's class.\\n    It's used in creating dynamic state models for graph components, allowing\\n    for the modification of component states.\\n\\n    Args:\\n        method (Callable): The method for which the output setter is being built.\\n        validate (bool, optional): Flag indicating whether to validate the method\\n                                   before building the setter. Defaults to True.\\n\\n    Returns:\\n        Callable: The output setter function. When called with a value, this function\\n                  sets the output associated with the original method to that value.\\n\\n    Raises:\\n        ValueError: If validation fails when validate is True.\\n\\n    Notes:\\n        - When validate is True, the method must belong to a class with a\\n          'get_output_by_method' attribute.\\n        - This function is typically used internally by create_state_model.\\n        - The setter allows for dynamic updating of component states in a graph.\\n\\n    Example:\\n        >>> class ChatComponent:\\n        ...     def get_output_by_method(self, method):\\n        ...         return type('Output', (), {'value': None})()\\n        ...     def set_message(self):\\n        ...         pass\\n        >>> component = ChatComponent()\\n        >>> setter = build_output_setter(component.set_message)\\n        >>> setter(component, \\\"New message\\\")\\n        >>> print(component.get_output_by_method(component.set_message).value)  # Prints \\\"New message\\\"\\n    \\\"\\\"\\\"\\n\\n    def output_setter(self, value) -> None:  # noqa: ARG001\\n        if validate:\\n            __validate_method(method)\\n        methods_class = method.__self__  # type: ignore[attr-defined]\\n        output = methods_class.get_output_by_method(method)\\n        output.value = value\\n\\n    return output_setter\\n\\n\\ndef create_state_model(model_name: str = \\\"State\\\", *, validate: bool = True, **kwargs) -> type:\\n    \\\"\\\"\\\"Create a dynamic Pydantic state model based on the provided keyword arguments.\\n\\n    This function generates a Pydantic model class with fields corresponding to the\\n    provided keyword arguments. It can handle various types of field definitions,\\n    including callable methods (which are converted to properties), FieldInfo objects,\\n    and type-default value tuples.\\n\\n    Args:\\n        model_name (str, optional): The name of the model. Defaults to \\\"State\\\".\\n        validate (bool, optional): Whether to validate the methods when converting\\n                                   them to properties. Defaults to True.\\n        **kwargs: Keyword arguments representing the fields of the model. Each argument\\n                  can be a callable method, a FieldInfo object, or a tuple of (type, default).\\n\\n    Returns:\\n        type: The dynamically created Pydantic state model class.\\n\\n    Raises:\\n        ValueError: If the provided field value is invalid or cannot be processed.\\n\\n    Examples:\\n        >>> from lfx.components.io import ChatInput\\n        >>> from lfx.components.io.ChatOutput import ChatOutput\\n        >>> from pydantic import Field\\n        >>>\\n        >>> chat_input = ChatInput()\\n        >>> chat_output = ChatOutput()\\n        >>>\\n        >>> # Create a model with a method from a component\\n        >>> StateModel = create_state_model(method_one=chat_input.message_response)\\n        >>> state = StateModel()\\n        >>> assert state.method_one is UNDEFINED\\n        >>> chat_input.set_output_value(\\\"message\\\", \\\"test\\\")\\n        >>> assert state.method_one == \\\"test\\\"\\n        >>>\\n        >>> # Create a model with multiple components and a Pydantic Field\\n        >>> NewStateModel = create_state_model(\\n        ...     model_name=\\\"NewStateModel\\\",\\n        ...     first_method=chat_input.message_response,\\n        ...     second_method=chat_output.message_response,\\n        ...     my_attribute=Field(None)\\n        ... )\\n        >>> new_state = NewStateModel()\\n        >>> new_state.first_method = \\\"test\\\"\\n        >>> new_state.my_attribute = 123\\n        >>> assert new_state.first_method == \\\"test\\\"\\n        >>> assert new_state.my_attribute == 123\\n        >>>\\n        >>> # Create a model with tuple-based field definitions\\n        >>> TupleStateModel = create_state_model(field_one=(str, \\\"default\\\"), field_two=(int, 123))\\n        >>> tuple_state = TupleStateModel()\\n        >>> assert tuple_state.field_one == \\\"default\\\"\\n        >>> assert tuple_state.field_two == 123\\n\\n    Notes:\\n        - The function handles empty keyword arguments gracefully.\\n        - For tuple-based field definitions, the first element must be a valid Python type.\\n        - Unsupported value types in keyword arguments will raise a ValueError.\\n        - Callable methods must have proper return type annotations and belong to a class\\n          with a 'get_output_by_method' attribute when validate is True.\\n    \\\"\\\"\\\"\\n    fields = {}\\n    computed_fields_dict = {}\\n\\n    for name, value in kwargs.items():\\n        # Extract the return type from the method's type annotations\\n        if callable(value):\\n            # Define the field with the return type\\n            try:\\n                __validate_method(value)\\n                getter = build_output_getter(value, validate=validate)\\n                setter = build_output_setter(value, validate=validate)\\n                property_method = property(getter, setter)\\n            except ValueError as e:\\n                # If the method is not valid,assume it is already a getter\\n                if (\\\"get_output_by_method\\\" not in str(e) and \\\"__self__\\\" not in str(e)) or validate:\\n                    raise\\n                property_method = value\\n            # Store computed fields separately to add them to the base class\\n            computed_fields_dict[name] = computed_field(property_method)\\n        elif isinstance(value, FieldInfo):\\n            field_tuple = (value.annotation or Any, value)\\n            fields[name] = field_tuple\\n        elif isinstance(value, tuple) and len(value) == 2:  # noqa: PLR2004\\n            # Fields are defined by one of the following tuple forms:\\n\\n            # (<type>, <default value>)\\n            # (<type>, Field(...))\\n            # typing.Annotated[<type>, Field(...)]\\n            if not isinstance(value[0], type):\\n                msg = f\\\"Invalid type for field {name}: {type(value[0])}\\\"\\n                raise TypeError(msg)\\n            fields[name] = (value[0], value[1])\\n        else:\\n            msg = f\\\"Invalid value type {type(value)} for field {name}\\\"\\n            raise ValueError(msg)\\n\\n    # Create the model dynamically\\n    config_dict = ConfigDict(arbitrary_types_allowed=True, validate_assignment=True)\\n\\n    # If we have computed fields, create a base class with them first\\n    if computed_fields_dict:\\n        # Create a base class with computed fields\\n        base_class_attrs = computed_fields_dict.copy()\\n        base_class_attrs[\\\"model_config\\\"] = config_dict\\n        base_state_model = type(f\\\"{model_name}Base\\\", (BaseModel,), base_class_attrs)\\n\\n        # Then create the final model with the base class\\n        return create_model(model_name, __base__=base_state_model, __config__=config_dict, **fields)\\n    # No computed fields, just create the model directly\\n    return create_model(model_name, __config__=config_dict, **fields)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"de492c2721b2bd59565dde5217c62f0c36e8c86ab5dff852e0f1e907c3a98cf0\",\"content\":\"from __future__ import annotations\\n\\nfrom collections.abc import Generator\\nfrom enum import Enum\\nfrom typing import TYPE_CHECKING, Any\\nfrom uuid import UUID\\n\\nfrom lfx.interface.utils import extract_input_variables_from_prompt\\nfrom lfx.log.logger import logger\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.message import Message\\n\\n# Database imports removed - lfx should be lightweight\\nfrom lfx.services.database.service import NoopDatabaseService\\nfrom lfx.services.deps import get_db_service, get_settings_service\\n\\nif TYPE_CHECKING:\\n    from lfx.graph.vertex.base import Vertex\\n\\n\\nclass UnbuiltObject:\\n    pass\\n\\n\\nclass UnbuiltResult:\\n    pass\\n\\n\\nclass ArtifactType(str, Enum):\\n    TEXT = \\\"text\\\"\\n    RECORD = \\\"record\\\"\\n    OBJECT = \\\"object\\\"\\n    ARRAY = \\\"array\\\"\\n    STREAM = \\\"stream\\\"\\n    UNKNOWN = \\\"unknown\\\"\\n    MESSAGE = \\\"message\\\"\\n\\n\\ndef validate_prompt(prompt: str):\\n    \\\"\\\"\\\"Validate prompt.\\\"\\\"\\\"\\n    if extract_input_variables_from_prompt(prompt):\\n        return prompt\\n\\n    return fix_prompt(prompt)\\n\\n\\ndef fix_prompt(prompt: str):\\n    \\\"\\\"\\\"Fix prompt.\\\"\\\"\\\"\\n    return prompt + \\\" {input}\\\"\\n\\n\\ndef flatten_list(list_of_lists: list[list | Any]) -> list:\\n    \\\"\\\"\\\"Flatten list of lists.\\\"\\\"\\\"\\n    new_list = []\\n    for item in list_of_lists:\\n        if isinstance(item, list):\\n            new_list.extend(item)\\n        else:\\n            new_list.append(item)\\n    return new_list\\n\\n\\ndef get_artifact_type(value, build_result) -> str:\\n    result = ArtifactType.UNKNOWN\\n    match value:\\n        case Data():\\n            result = ArtifactType.RECORD\\n\\n        case str():\\n            result = ArtifactType.TEXT\\n\\n        case dict():\\n            result = ArtifactType.OBJECT\\n\\n        case list():\\n            result = ArtifactType.ARRAY\\n\\n        case Message():\\n            result = ArtifactType.MESSAGE\\n\\n    if result == ArtifactType.UNKNOWN and (\\n        isinstance(build_result, Generator) or (isinstance(value, Message) and isinstance(value.text, Generator))\\n    ):\\n        result = ArtifactType.STREAM\\n\\n    return result.value\\n\\n\\ndef post_process_raw(raw, artifact_type: str):\\n    if artifact_type == ArtifactType.STREAM.value:\\n        raw = \\\"\\\"\\n\\n    return raw\\n\\n\\ndef serialize_for_json(obj: Any) -> Any:\\n    \\\"\\\"\\\"Convert object to JSON-serializable format.\\n\\n    Args:\\n        obj: Any object to serialize\\n\\n    Returns:\\n        JSON-serializable representation of the object\\n    \\\"\\\"\\\"\\n    if obj is None:\\n        return None\\n    if isinstance(obj, (str, int, float, bool)):\\n        return obj\\n    if isinstance(obj, dict):\\n        return {k: serialize_for_json(v) for k, v in obj.items()}\\n    if isinstance(obj, (list, tuple)):\\n        return [serialize_for_json(item) for item in obj]\\n    if hasattr(obj, \\\"model_dump\\\"):\\n        return serialize_for_json(obj.model_dump())\\n    if hasattr(obj, \\\"dict\\\"):\\n        return serialize_for_json(obj.dict())\\n    try:\\n        return str(obj)\\n    except (TypeError, ValueError):\\n        return None\\n\\n\\nasync def emit_vertex_build_event(\\n    *,\\n    flow_id: str | UUID,\\n    vertex_id: str,\\n    valid: bool,\\n    params: Any,\\n    data_dict: dict | Any,\\n    artifacts_dict: dict | None = None,\\n    next_vertices_ids: list[str] | None = None,\\n    top_level_vertices: list[str] | None = None,\\n    inactivated_vertices: list[str] | None = None,\\n) -> None:\\n    \\\"\\\"\\\"Emit end_vertex event for webhook real-time feedback.\\n\\n    This is a helper function to emit SSE events when vertices are built.\\n    Errors are silently ignored as SSE emission is not critical.\\n\\n    Args:\\n        flow_id: The flow ID\\n        vertex_id: The vertex ID that was built\\n        valid: Whether the build was successful\\n        params: Build parameters or error message\\n        data_dict: Build result data\\n        artifacts_dict: Build artifacts\\n        next_vertices_ids: IDs of vertices to run next (for UI animation)\\n        top_level_vertices: Top level vertices\\n        inactivated_vertices: Vertices that were inactivated\\n    \\\"\\\"\\\"\\n    try:\\n        from datetime import datetime, timezone\\n\\n        from langflow.services.event_manager import webhook_event_manager\\n\\n        flow_id_str = str(flow_id)\\n        if not webhook_event_manager.has_listeners(flow_id_str):\\n            return\\n\\n        duration = webhook_event_manager.get_build_duration(flow_id_str, vertex_id)\\n\\n        # Convert Pydantic model to dict if necessary\\n        if hasattr(data_dict, \\\"model_dump\\\"):\\n            data_as_dict = data_dict.model_dump()\\n        elif isinstance(data_dict, dict):\\n            data_as_dict = data_dict\\n        else:\\n            data_as_dict = {}\\n\\n        results = serialize_for_json(data_as_dict.get(\\\"results\\\", {}))\\n        outputs = serialize_for_json(data_as_dict.get(\\\"outputs\\\", {}))\\n        logs = serialize_for_json(data_as_dict.get(\\\"logs\\\", {}))\\n        messages = serialize_for_json(data_as_dict.get(\\\"messages\\\", []))\\n\\n        vertex_data = {\\n            \\\"results\\\": results,\\n            \\\"outputs\\\": outputs,\\n            \\\"logs\\\": logs,\\n            \\\"messages\\\": messages,\\n            \\\"duration\\\": duration,\\n        }\\n\\n        serialized_artifacts = serialize_for_json(artifacts_dict) if artifacts_dict else {}\\n\\n        await webhook_event_manager.emit(\\n            flow_id_str,\\n            \\\"end_vertex\\\",\\n            {\\n                \\\"build_data\\\": {\\n                    \\\"id\\\": vertex_id,\\n                    \\\"valid\\\": valid,\\n                    \\\"params\\\": str(params) if params else None,\\n                    \\\"data\\\": vertex_data,\\n                    \\\"artifacts\\\": serialized_artifacts,\\n                    \\\"timestamp\\\": datetime.now(timezone.utc).isoformat(),\\n                    \\\"messages\\\": vertex_data.get(\\\"messages\\\", []),\\n                    \\\"inactivated_vertices\\\": inactivated_vertices or [],\\n                    \\\"next_vertices_ids\\\": next_vertices_ids or [],\\n                    \\\"top_level_vertices\\\": top_level_vertices or [],\\n                }\\n            },\\n        )\\n    except ImportError:\\n        pass  # langflow not available (standalone lfx usage)\\n    except Exception as exc:  # noqa: BLE001\\n        logger.debug(f\\\"SSE emission failed for vertex {vertex_id}\\\", exc_info=exc)\\n\\n\\nasync def emit_build_start_event(flow_id: str | UUID, vertex_id: str) -> None:\\n    \\\"\\\"\\\"Emit build_start event for webhook real-time feedback.\\n\\n    This is a helper function to emit SSE events when a vertex build starts.\\n    Errors are silently ignored as SSE emission is not critical.\\n    \\\"\\\"\\\"\\n    try:\\n        from langflow.services.event_manager import webhook_event_manager\\n\\n        flow_id_str = str(flow_id)\\n        if not webhook_event_manager.has_listeners(flow_id_str):\\n            return\\n\\n        webhook_event_manager.record_build_start(flow_id_str, vertex_id)\\n        await webhook_event_manager.emit(flow_id_str, \\\"build_start\\\", {\\\"id\\\": vertex_id})\\n    except ImportError:\\n        pass  # langflow not available (standalone lfx usage)\\n    except Exception as exc:  # noqa: BLE001\\n        logger.debug(f\\\"SSE build_start emission failed for vertex {vertex_id}\\\", exc_info=exc)\\n\\n\\ndef _vertex_to_primitive_dict(target: Vertex) -> dict:\\n    \\\"\\\"\\\"Cleans the parameters of the target vertex.\\\"\\\"\\\"\\n    # Removes all keys that the values aren't python types like str, int, bool, etc.\\n    params = {\\n        key: value for key, value in target.params.items() if isinstance(value, str | int | bool | float | list | dict)\\n    }\\n    # if it is a list we need to check if the contents are python types\\n    for key, value in params.items():\\n        if isinstance(value, list):\\n            params[key] = [item for item in value if isinstance(item, str | int | bool | float | list | dict)]\\n    return params\\n\\n\\nasync def log_transaction(\\n    flow_id: str | UUID,\\n    source: Vertex,\\n    status: str,\\n    target: Vertex | None = None,\\n    error: str | Exception | None = None,\\n    outputs: dict[str, Any] | None = None,\\n) -> None:\\n    \\\"\\\"\\\"Asynchronously logs a transaction record for a vertex in a flow if transaction storage is enabled.\\n\\n    Uses the pluggable TransactionService to log transactions. When running within langflow,\\n    the concrete TransactionService implementation persists to the database.\\n    When running standalone (lfx only), transactions are not persisted.\\n\\n    Args:\\n        flow_id: The flow ID\\n        source: The source vertex (component being executed)\\n        status: Transaction status (success/error)\\n        target: Optional target vertex (for data transfer logging)\\n        error: Optional error information\\n        outputs: Optional explicit outputs dict (component execution results)\\n    \\\"\\\"\\\"\\n    try:\\n        # Guard against null source\\n        if source is None:\\n            return\\n\\n        # Serving-plane ephemeral runs must not persist execution telemetry either:\\n        # transaction rows store component inputs/outputs verbatim, which would\\n        # retain the very conversation content the anonymous no-persist contract\\n        # excludes. Read the flag off the vertex's graph (deterministic here, where\\n        # the per-component ContextVar binding is already out of scope).\\n        if not getattr(getattr(source, \\\"graph\\\", None), \\\"persist_messages\\\", True):\\n            return\\n\\n        # Get the transaction service via dependency injection\\n        from lfx.services.deps import get_transaction_service\\n\\n        transaction_service = get_transaction_service()\\n\\n        # If no transaction service is available or it's disabled, skip logging\\n        if transaction_service is None or not transaction_service.is_enabled():\\n            return\\n\\n        # Resolve flow_id\\n        if not flow_id:\\n            if source.graph.flow_id:\\n                flow_id = source.graph.flow_id\\n            else:\\n                return\\n\\n        # Convert UUID to string for the service interface\\n        flow_id_str = str(flow_id) if isinstance(flow_id, UUID) else flow_id\\n\\n        # Prepare inputs and outputs\\n        inputs = _vertex_to_primitive_dict(source) if source else None\\n        target_outputs = _vertex_to_primitive_dict(target) if target else None\\n        transaction_outputs = outputs if outputs is not None else target_outputs\\n\\n        # Log transaction via the service\\n        await transaction_service.log_transaction(\\n            flow_id=flow_id_str,\\n            vertex_id=source.id,\\n            inputs=inputs,\\n            outputs=transaction_outputs,\\n            status=status,\\n            target_id=target.id if target else None,\\n            error=str(error) if error else None,\\n        )\\n\\n    except Exception as exc:  # noqa: BLE001\\n        logger.debug(\\\"Error logging transaction\\\", exc_info=exc)\\n\\n\\n# Latch so the \\\"writer enabled but not running\\\" fall-through log fires once\\n# per process. log_vertex_build is a module-level function so we can't keep\\n# state on an instance.\\n_legacy_vb_fallback_logged: bool = False\\n\\n\\ndef _try_enqueue_via_telemetry_writer(vertex_build) -> bool:\\n    \\\"\\\"\\\"Best-effort handoff to the langflow telemetry writer.\\n\\n    Returns ``True`` when the row was accepted by the writer (caller should\\n    skip the direct DB write). Returns ``False`` when langflow isn't installed,\\n    the writer isn't started, or the writer rejected the row.\\n    \\\"\\\"\\\"\\n    global _legacy_vb_fallback_logged  # noqa: PLW0603 \u2014 one-shot module-level latch\\n    try:\\n        from langflow.services.database.models.vertex_builds.model import VertexBuildTable\\n        from langflow.services.deps import get_telemetry_writer_service\\n    except ImportError:\\n        return False\\n    writer = get_telemetry_writer_service()\\n    if writer is None or not writer.is_running():\\n        if not _legacy_vb_fallback_logged:\\n            _legacy_vb_fallback_logged = True\\n            logger.warning(\\n                \\\"telemetry_writer_enabled=True but writer is not running; \\\"\\n                \\\"falling back to legacy direct-write path for vertex_builds\\\"\\n            )\\n        return False\\n    table = VertexBuildTable(**vertex_build.model_dump())\\n    return writer.enqueue_vertex_build(table.model_dump(mode=\\\"python\\\"))\\n\\n\\nasync def log_vertex_build(\\n    *,\\n    flow_id: str | UUID,\\n    vertex_id: str,\\n    valid: bool,\\n    params: Any,\\n    data: dict | Any,\\n    artifacts: dict | None = None,\\n    job_id: str | None = None,\\n) -> None:\\n    \\\"\\\"\\\"Asynchronously logs a vertex build record if vertex build storage is enabled.\\n\\n    This is a lightweight implementation that only logs if database service is available.\\n    When running within langflow, it will use langflow's database service to persist the build.\\n    When running standalone (lfx only), it will only log debug messages.\\n    \\\"\\\"\\\"\\n    try:\\n        # Try to use langflow's services if available (when running within langflow)\\n        try:\\n            settings_service = get_settings_service()\\n            if not settings_service:\\n                return\\n            if not getattr(settings_service.settings, \\\"vertex_builds_storage_enabled\\\", False):\\n                return\\n\\n            # Resolve only the database service already registered with the shared\\n            # LFX service manager. Calling langflow.services.deps.get_db_service()\\n            # here would install Langflow's default DatabaseService as a lookup\\n            # side effect, turning a DB-less `lfx serve` process into a partially\\n            # initialized DB runtime between two vertices in the same graph run.\\n            db_service = get_db_service()\\n            if isinstance(db_service, NoopDatabaseService):\\n                return\\n\\n            if isinstance(flow_id, str):\\n                flow_id = UUID(flow_id)\\n\\n            from langflow.services.database.models.vertex_builds.crud import (\\n                log_vertex_build as crud_log_vertex_build,\\n            )\\n            from langflow.services.database.models.vertex_builds.model import VertexBuildBase\\n\\n            # Convert data to dict if it's a pydantic model\\n            data_dict = data\\n            if hasattr(data, \\\"model_dump\\\"):\\n                data_dict = data.model_dump()\\n            elif hasattr(data, \\\"dict\\\"):\\n                data_dict = data.dict()\\n\\n            # Convert artifacts to dict if it's a pydantic model\\n            artifacts_dict = artifacts\\n            if artifacts is not None:\\n                if hasattr(artifacts, \\\"model_dump\\\"):\\n                    artifacts_dict = artifacts.model_dump()\\n                elif hasattr(artifacts, \\\"dict\\\"):\\n                    artifacts_dict = artifacts.dict()\\n\\n            vertex_build = VertexBuildBase(\\n                flow_id=flow_id,\\n                id=vertex_id,\\n                valid=valid,\\n                params=str(params) if params else None,\\n                data=data_dict,\\n                artifacts=artifacts_dict,\\n                job_id=job_id,\\n            )\\n\\n            # When the telemetry writer is enabled and started, route the row\\n            # through its disk-backed outbox so the write does not contend on\\n            # the request-handling DB pool. Falls through to a direct write\\n            # when the writer is not ready or disabled.\\n            if getattr(\\n                settings_service.settings, \\\"telemetry_writer_enabled\\\", False\\n            ) and _try_enqueue_via_telemetry_writer(vertex_build):\\n                return\\n\\n            async with db_service._with_session() as session:  # noqa: SLF001\\n                await crud_log_vertex_build(session, vertex_build)\\n\\n            # Note: emit_vertex_build_event is NOT called here because it needs\\n            # next_vertices_ids which are only available after graph.get_next_runnable_vertices()\\n            # The event is emitted separately in graph._execute_tasks() with complete data.\\n\\n        except ImportError:\\n            # Fallback for standalone lfx usage (without langflow)\\n            settings_service = get_settings_service()\\n            if not settings_service or not getattr(settings_service.settings, \\\"vertex_builds_storage_enabled\\\", False):\\n                return\\n\\n            if isinstance(flow_id, str):\\n                flow_id = UUID(flow_id)\\n\\n            # Log basic vertex build info - concrete implementation is in langflow\\n            logger.debug(f\\\"Vertex build logged: vertex={vertex_id}, flow={flow_id}, valid={valid}\\\")\\n\\n    except Exception as exc:  # noqa: BLE001\\n        logger.warning(\\\"Error logging vertex build\\\", exc_info=exc)\\n\\n\\ndef rewrite_file_path(file_path: str):\\n    file_path = file_path.replace(\\\"\\\\\\\\\\\", \\\"/\\\")\\n\\n    if \\\":\\\" in file_path:\\n        file_path = file_path.split(\\\":\\\", 1)[-1]\\n\\n    file_path_split = [part for part in file_path.split(\\\"/\\\") if part]\\n\\n    if len(file_path_split) > 1:\\n        consistent_file_path = f\\\"{file_path_split[-2]}/{file_path_split[-1]}\\\"\\n    else:\\n        consistent_file_path = \\\"/\\\".join(file_path_split)\\n\\n    return [consistent_file_path]\\n\\n\\ndef has_output_vertex(vertices: dict[Vertex, int]):\\n    return any(vertex.is_output for vertex in vertices)\\n\\n\\ndef has_chat_output(vertices: dict[Vertex, int]):\\n    from lfx.graph.schema import InterfaceComponentTypes\\n\\n    return any(vertex.base_name == InterfaceComponentTypes.ChatOutput.value for vertex in vertices)\\n\\n\\ndef has_chat_input(vertices: dict[Vertex, int]):\\n    from lfx.graph.schema import InterfaceComponentTypes\\n\\n    return any(vertex.base_name == InterfaceComponentTypes.ChatInput.value for vertex in vertices)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/vertex/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/vertex/base.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e7c2b954491af354d9f5b3f253c90928a93e44905e7c6bd41233f7910820394c\",\"content\":\"from __future__ import annotations\\n\\nimport asyncio\\nimport inspect\\nimport traceback\\nimport types\\nfrom collections.abc import AsyncIterator, Callable, Iterator, Mapping\\nfrom enum import Enum\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom ag_ui.core import StepFinishedEvent, StepStartedEvent\\n\\nfrom lfx.exceptions.component import ComponentBuildError\\nfrom lfx.graph.schema import INPUT_COMPONENTS, OUTPUT_COMPONENTS, InterfaceComponentTypes, ResultData\\nfrom lfx.graph.utils import UnbuiltObject, UnbuiltResult, emit_build_start_event, log_transaction\\nfrom lfx.graph.vertex.param_handler import ParameterHandler\\nfrom lfx.interface import initialize\\nfrom lfx.interface.listing import lazy_load_dict\\nfrom lfx.log.logger import logger\\nfrom lfx.schema.artifact import ArtifactType\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.message import Message\\nfrom lfx.schema.properties import Usage\\nfrom lfx.schema.schema import INPUT_FIELD_NAME, OutputValue, build_output_logs\\nfrom lfx.utils.flow_validation import explain_restricted_component_mismatch\\nfrom lfx.utils.schemas import ChatOutputResponse\\nfrom lfx.utils.util import sync_to_async\\n\\nif TYPE_CHECKING:\\n    from uuid import UUID\\n\\n    from lfx.custom.custom_component.component import Component\\n    from lfx.events.event_manager import EventManager\\n    from lfx.graph.edge.base import CycleEdge, Edge\\n    from lfx.graph.graph.base import Graph\\n    from lfx.graph.vertex.schema import NodeData\\n\\n    # Simple log type for tracing\\n    Log = dict\\n\\n\\nclass VertexStates(str, Enum):\\n    \\\"\\\"\\\"Vertex are related to it being active, inactive, or in an error state.\\\"\\\"\\\"\\n\\n    ACTIVE = \\\"ACTIVE\\\"\\n    INACTIVE = \\\"INACTIVE\\\"\\n    ERROR = \\\"ERROR\\\"\\n\\n\\nclass Vertex:\\n    def __init__(\\n        self,\\n        data: NodeData,\\n        graph: Graph,\\n        *,\\n        base_type: str | None = None,\\n        is_task: bool = False,\\n        params: dict | None = None,\\n    ) -> None:\\n        # is_external means that the Vertex send or receives data from\\n        # an external source (e.g the chat)\\n        self._lock: asyncio.Lock | None = None\\n        self.will_stream = False\\n        self.updated_raw_params = False\\n        self.id: str = data[\\\"id\\\"]\\n        self.base_name = self.id.split(\\\"-\\\")[0]\\n        self.is_state = False\\n        # TODO: This won't be enough in the long term\\n        # we need to have a better way to determine if a vertex is an input or an output\\n        type_strings = [self.id.split(\\\"-\\\")[0], data[\\\"data\\\"][\\\"type\\\"]]\\n        self.is_input = any(input_component_name in type_strings for input_component_name in INPUT_COMPONENTS)\\n        self.is_output = any(output_component_name in type_strings for output_component_name in OUTPUT_COMPONENTS)\\n        self._is_loop = None\\n        self.has_session_id = None\\n        self.custom_component = None\\n        # Runtime-only metadata used to mask downstream display results without changing edge values.\\n        self._upstream_secret_values: set[str] = set()\\n        self.has_external_input = False\\n        self.has_external_output = False\\n        self.graph = graph\\n        self.full_data = data.copy()\\n        self.base_type: str | None = base_type\\n        self.outputs: list[dict] = []\\n        self.parse_data()\\n        self.built_object: Any = UnbuiltObject()\\n        self.built_result: Any = None\\n        self.built = False\\n        self._successors_ids: list[str] | None = None\\n        self.artifacts: dict[str, Any] = {}\\n        self.artifacts_raw: dict[str, Any] | None = {}\\n        self.artifacts_type: dict[str, str] = {}\\n        self.steps: list[Callable] = [self._build]\\n        self.steps_ran: list[Callable] = []\\n        self.task_id: str | None = None\\n        self.is_task = is_task\\n        self.params = params or {}\\n        self.parent_node_id: str | None = self.full_data.get(\\\"parent_node_id\\\")\\n        self.load_from_db_fields: list[str] = []\\n        self.parent_is_top_level = False\\n        self.layer = None\\n        self.result: ResultData | None = None\\n        self.results: dict[str, Any] = {}\\n        self.outputs_logs: dict[str, OutputValue] = {}\\n        self.logs: dict[str, list[Log]] = {}\\n        self.has_cycle_edges = False\\n        try:\\n            self.is_interface_component = self.vertex_type in InterfaceComponentTypes\\n        except ValueError:\\n            self.is_interface_component = False\\n\\n        self.use_result = False\\n        self.build_times: list[float] = []\\n        self.state = VertexStates.ACTIVE\\n        self.output_names: list[str] = [\\n            output[\\\"name\\\"] for output in self.outputs if isinstance(output, dict) and \\\"name\\\" in output\\n        ]\\n        self._incoming_edges: list[CycleEdge] | None = None\\n        self._outgoing_edges: list[CycleEdge] | None = None\\n\\n    @property\\n    def lock(self):\\n        \\\"\\\"\\\"Lazy initialization of asyncio.Lock.\\\"\\\"\\\"\\n        if self._lock is None:\\n            self._lock = asyncio.Lock()\\n        return self._lock\\n\\n    @property\\n    def is_loop(self) -> bool:\\n        \\\"\\\"\\\"Check if any output allows looping.\\\"\\\"\\\"\\n        if self._is_loop is None:\\n            self._is_loop = any(output.get(\\\"allows_loop\\\", False) for output in self.outputs)\\n        return self._is_loop\\n\\n    def set_input_value(self, name: str, value: Any) -> None:\\n        if self.custom_component is None:\\n            msg = f\\\"Vertex {self.id} does not have a component instance.\\\"\\n            raise ValueError(msg)\\n        self.custom_component.set_input_value(name, value)\\n\\n    def to_data(self):\\n        return self.full_data\\n\\n    def add_component_instance(self, component_instance: Component) -> None:\\n        component_instance.set_vertex(self)\\n        self.custom_component = component_instance\\n\\n    def add_result(self, name: str, result: Any) -> None:\\n        self.results[name] = result\\n\\n    def set_state(self, state: str) -> None:\\n        self.state = VertexStates[state]\\n        if self.state == VertexStates.INACTIVE and self.graph.in_degree_map[self.id] <= 1:\\n            # If the vertex is inactive and has only one in degree\\n            # it means that it is not a merge point in the graph\\n            self.graph.inactivated_vertices.add(self.id)\\n        elif self.state == VertexStates.ACTIVE and self.id in self.graph.inactivated_vertices:\\n            self.graph.inactivated_vertices.remove(self.id)\\n\\n    def is_active(self):\\n        return self.state == VertexStates.ACTIVE\\n\\n    @property\\n    def avg_build_time(self):\\n        return sum(self.build_times) / len(self.build_times) if self.build_times else 0\\n\\n    def add_build_time(self, time) -> None:\\n        self.build_times.append(time)\\n\\n    def set_result(self, result: ResultData) -> None:\\n        self.result = result\\n\\n    def get_built_result(self):\\n        # If the Vertex.type is a power component\\n        # then we need to return the built object\\n        # instead of the result dict\\n        if self.is_interface_component and not isinstance(self.built_object, UnbuiltObject):\\n            result = self.built_object\\n            # if it is not a dict or a string and hasattr model_dump then\\n            # return the model_dump\\n            if not isinstance(result, dict | str) and hasattr(result, \\\"content\\\"):\\n                return result.content\\n            return result\\n        if isinstance(self.built_object, str):\\n            self.built_result = self.built_object\\n\\n        if isinstance(self.built_result, UnbuiltResult):\\n            return {}\\n\\n        return self.built_result if isinstance(self.built_result, dict) else {\\\"result\\\": self.built_result}\\n\\n    def set_artifacts(self) -> None:\\n        pass\\n\\n    @property\\n    def edges(self) -> list[CycleEdge]:\\n        return self.graph.get_vertex_edges(self.id)\\n\\n    @property\\n    def outgoing_edges(self) -> list[CycleEdge]:\\n        if self._outgoing_edges is None:\\n            self._outgoing_edges = [edge for edge in self.edges if edge.source_id == self.id]\\n        return self._outgoing_edges\\n\\n    @property\\n    def incoming_edges(self) -> list[CycleEdge]:\\n        if self._incoming_edges is None:\\n            self._incoming_edges = [edge for edge in self.edges if edge.target_id == self.id]\\n        return self._incoming_edges\\n\\n    # Get edge connected to an output of a certain name\\n    def get_incoming_edge_by_target_param(self, target_param: str) -> str | None:\\n        return next((edge.source_id for edge in self.incoming_edges if edge.target_param == target_param), None)\\n\\n    @property\\n    def edges_source_names(self) -> set[str | None]:\\n        return {edge.source_handle.name for edge in self.edges}\\n\\n    @property\\n    def predecessors(self) -> list[Vertex]:\\n        return self.graph.get_predecessors(self)\\n\\n    @property\\n    def successors(self) -> list[Vertex]:\\n        return self.graph.get_successors(self)\\n\\n    @property\\n    def successors_ids(self) -> list[str]:\\n        return self.graph.successor_map.get(self.id, [])\\n\\n    def __getstate__(self):\\n        state = self.__dict__.copy()\\n        state[\\\"_lock\\\"] = None  # Locks are not serializable\\n        state[\\\"custom_component\\\"] = None  # Component instances are rebuilt and may hold non-serializable runtime state\\n        state[\\\"_upstream_secret_values\\\"] = set()  # Never persist raw secrets carried between components\\n        state[\\\"built_object\\\"] = None if isinstance(self.built_object, UnbuiltObject) else self.built_object\\n        state[\\\"built_result\\\"] = None if isinstance(self.built_result, UnbuiltResult) else self.built_result\\n        return state\\n\\n    def __setstate__(self, state):\\n        self.__dict__.update(state)\\n        self._lock = asyncio.Lock()  # Reinitialize the lock\\n        self._upstream_secret_values = state.get(\\\"_upstream_secret_values\\\", set())\\n        self.built_object = state.get(\\\"built_object\\\") or UnbuiltObject()\\n        self.built_result = state.get(\\\"built_result\\\") or UnbuiltResult()\\n\\n    def set_top_level(self, top_level_vertices: list[str]) -> None:\\n        self.parent_is_top_level = self.parent_node_id in top_level_vertices\\n\\n    def parse_data(self) -> None:\\n        self.data = self.full_data[\\\"data\\\"]\\n        if self.data[\\\"node\\\"][\\\"template\\\"][\\\"_type\\\"] == \\\"Component\\\":\\n            if \\\"outputs\\\" not in self.data[\\\"node\\\"]:\\n                msg = f\\\"Outputs not found for {self.display_name}\\\"\\n                raise ValueError(msg)\\n            self.outputs = self.data[\\\"node\\\"][\\\"outputs\\\"]\\n        else:\\n            self.outputs = self.data[\\\"node\\\"].get(\\\"outputs\\\", [])\\n            self.output = self.data[\\\"node\\\"][\\\"base_classes\\\"]\\n\\n        self.display_name: str = self.data[\\\"node\\\"].get(\\\"display_name\\\", self.id.split(\\\"-\\\")[0])\\n        self.icon: str = self.data[\\\"node\\\"].get(\\\"icon\\\", self.id.split(\\\"-\\\")[0])\\n\\n        self.description: str = self.data[\\\"node\\\"].get(\\\"description\\\", \\\"\\\")\\n        self.frozen: bool = self.data[\\\"node\\\"].get(\\\"frozen\\\", False)\\n\\n        self.is_input = self.data[\\\"node\\\"].get(\\\"is_input\\\") or self.is_input\\n        self.is_output = self.data[\\\"node\\\"].get(\\\"is_output\\\") or self.is_output\\n        template_dicts = {key: value for key, value in self.data[\\\"node\\\"][\\\"template\\\"].items() if isinstance(value, dict)}\\n\\n        self.has_session_id = \\\"session_id\\\" in template_dicts\\n\\n        self.required_inputs: list[str] = []\\n        self.optional_inputs: list[str] = []\\n        for value_dict in template_dicts.values():\\n            list_to_append = self.required_inputs if value_dict.get(\\\"required\\\") else self.optional_inputs\\n\\n            if \\\"type\\\" in value_dict:\\n                list_to_append.append(value_dict[\\\"type\\\"])\\n            if \\\"input_types\\\" in value_dict:\\n                list_to_append.extend(value_dict[\\\"input_types\\\"])\\n\\n        template_dict = self.data[\\\"node\\\"][\\\"template\\\"]\\n        self.vertex_type = (\\n            self.data[\\\"type\\\"]\\n            if \\\"Tool\\\" not in [type_ for out in self.outputs for type_ in out[\\\"types\\\"]]\\n            or template_dict[\\\"_type\\\"].islower()\\n            else template_dict[\\\"_type\\\"]\\n        )\\n\\n        if self.base_type is None:\\n            for base_type, value in lazy_load_dict.all_types_dict.items():\\n                if self.vertex_type in value:\\n                    self.base_type = base_type\\n                    break\\n\\n    def get_value_from_output_names(self, key: str):\\n        if key in self.output_names:\\n            return self.graph.get_vertex(key)\\n        return None\\n\\n    def get_value_from_template_dict(self, key: str):\\n        template_dict = self.data.get(\\\"node\\\", {}).get(\\\"template\\\", {})\\n\\n        if key not in template_dict:\\n            msg = f\\\"Key {key} not found in template dict\\\"\\n            raise ValueError(msg)\\n        return template_dict.get(key, {}).get(\\\"value\\\")\\n\\n    def _set_params_from_normal_edge(self, params: dict, edge: Edge, template_dict: dict):\\n        param_key = edge.target_param\\n\\n        # If the param_key is in the template_dict and the edge.target_id is the current node\\n        # We check this to make sure params with the same name but different target_id\\n        # don't get overwritten\\n        if param_key in template_dict and edge.target_id == self.id:\\n            if template_dict[param_key].get(\\\"list\\\"):\\n                if param_key not in params:\\n                    params[param_key] = []\\n                params[param_key].append(self.graph.get_vertex(edge.source_id))\\n            elif edge.target_id == self.id:\\n                if isinstance(template_dict[param_key].get(\\\"value\\\"), dict):\\n                    # we don't know the key of the dict but we need to set the value\\n                    # to the vertex that is the source of the edge\\n                    param_dict = template_dict[param_key][\\\"value\\\"]\\n                    if not param_dict or len(param_dict) != 1:\\n                        params[param_key] = self.graph.get_vertex(edge.source_id)\\n                    else:\\n                        params[param_key] = {key: self.graph.get_vertex(edge.source_id) for key in param_dict}\\n\\n                else:\\n                    params[param_key] = self.graph.get_vertex(edge.source_id)\\n        elif param_key in self.output_names:\\n            #  if the loop is run the param_key item will be set over here\\n            # validate the edge\\n            params[param_key] = self.graph.get_vertex(edge.source_id)\\n        return params\\n\\n    def build_params(self) -> None:\\n        \\\"\\\"\\\"Build parameters for the vertex using the ParameterHandler.\\\"\\\"\\\"\\n        if self.graph is None:\\n            msg = \\\"Graph not found\\\"\\n            raise ValueError(msg)\\n\\n        if self.updated_raw_params:\\n            # Don't reset the flag - keep it True to protect against multiple build_params() calls\\n            # The flag will be reset when _build_each_vertex_in_params_dict() processes the params\\n            return\\n\\n        # Create parameter handler with lazy storage service initialization\\n        param_handler = ParameterHandler(self, storage_service=None)\\n\\n        # Process edge parameters\\n        edge_params = param_handler.process_edge_parameters(self.edges)\\n\\n        # Process field parameters\\n        field_params, load_from_db_fields = param_handler.process_field_parameters()\\n\\n        # Combine parameters, edge_params take precedence\\n        self.params = {**field_params, **edge_params}\\n        self.load_from_db_fields = load_from_db_fields\\n        self.raw_params = self.params.copy()\\n\\n    def update_raw_params(self, new_params: Mapping[str, Any], *, overwrite: bool = False) -> None:\\n        \\\"\\\"\\\"Update the raw parameters of the vertex with the given new parameters.\\n\\n        Args:\\n            new_params (Dict[str, Any]): The new parameters to update.\\n            overwrite (bool, optional): Whether to overwrite the existing parameters.\\n                Defaults to False.\\n\\n        Raises:\\n            ValueError: If any key in new_params is not found in self.raw_params.\\n        \\\"\\\"\\\"\\n        # First check if the input_value in raw_params is not a vertex\\n        if not new_params:\\n            return\\n        if any(isinstance(self.raw_params.get(key), Vertex) for key in new_params):\\n            return\\n        params_to_update = dict(new_params)\\n        if not overwrite:\\n            for key in params_to_update.copy():\\n                if key not in self.raw_params:\\n                    params_to_update.pop(key)\\n        params_to_update = ParameterHandler(self, storage_service=None).process_runtime_params(params_to_update)\\n        self.raw_params.update(params_to_update)\\n        self.params = self.raw_params.copy()\\n        self.updated_raw_params = True\\n\\n    def instantiate_component(self, user_id=None, event_manager: EventManager | None = None) -> None:\\n        if not self.custom_component:\\n            self.custom_component, _ = initialize.loading.instantiate_class(\\n                user_id=user_id,\\n                vertex=self,\\n                event_manager=event_manager,\\n            )\\n\\n    def _bind_restored_component_user(self, user_id=None) -> None:\\n        \\\"\\\"\\\"Restore the runtime user dropped from checkpointed component state.\\\"\\\"\\\"\\n        if (\\n            user_id is not None\\n            and self.custom_component is not None\\n            and getattr(self.custom_component, \\\"_user_id\\\", None) is None\\n        ):\\n            self.custom_component._user_id = user_id  # noqa: SLF001\\n\\n    def require_model_provider_policy(self, user_id=None) -> None:\\n        \\\"\\\"\\\"Synchronously authorize a model vertex for compatibility-only callers.\\\"\\\"\\\"\\n        if not self.custom_component:\\n            self.instantiate_component(user_id=user_id)\\n        self._bind_restored_component_user(user_id)\\n        if self.custom_component:\\n            from lfx.services.model_provider_policy import ModelProviderPolicyPurpose\\n\\n            self.custom_component.require_model_provider_policy(ModelProviderPolicyPurpose.USE)\\n\\n    async def arequire_model_provider_policy(self, user_id=None, event_manager: EventManager | None = None) -> None:\\n        \\\"\\\"\\\"Authorize runtime use through the hierarchy-refreshing async policy hook.\\\"\\\"\\\"\\n        if not self.custom_component:\\n            self.instantiate_component(user_id=user_id, event_manager=event_manager)\\n        self._bind_restored_component_user(user_id)\\n        if self.custom_component:\\n            from lfx.services.model_provider_policy import ModelProviderPolicyPurpose\\n\\n            await self.custom_component.arequire_model_provider_policy(\\n                ModelProviderPolicyPurpose.USE,\\n                user_id=user_id,\\n                parameters=self.params,\\n            )\\n\\n    async def _build(\\n        self,\\n        fallback_to_env_vars,\\n        user_id=None,\\n        event_manager: EventManager | None = None,\\n    ) -> None:\\n        \\\"\\\"\\\"Initiate the build process.\\\"\\\"\\\"\\n        await logger.adebug(f\\\"Building {self.display_name}\\\")\\n        # Upstream parameters may themselves hydrate load_from_db credentials.\\n        # Preflight the target model before building any input vertex so a\\n        # scoped denial cannot observe either upstream or local secrets.\\n        await self.arequire_model_provider_policy(user_id=user_id, event_manager=event_manager)\\n        await self._build_each_vertex_in_params_dict()\\n        if self.base_type is None:\\n            msg = f\\\"Base type for vertex {self.display_name} not found\\\"\\n            raise ValueError(msg)\\n\\n        if not self.custom_component:\\n            custom_component, custom_params = initialize.loading.instantiate_class(\\n                user_id=user_id, vertex=self, event_manager=event_manager\\n            )\\n        else:\\n            custom_component = self.custom_component\\n            # A checkpoint-restored component (HITL resume) loses _user_id, which\\n            # load_from_db fields (API keys) need; re-apply without overriding.\\n            self._bind_restored_component_user(user_id)\\n            if hasattr(self.custom_component, \\\"set_event_manager\\\"):\\n                self.custom_component.set_event_manager(event_manager)\\n            custom_params = initialize.loading.get_params(self.params)\\n            custom_params.pop(\\\"code\\\", None)\\n\\n        if hasattr(custom_component, \\\"_secret_values\\\"):\\n            custom_component._secret_values.update(self._upstream_secret_values)  # noqa: SLF001\\n\\n        await self._build_results(\\n            custom_component=custom_component,\\n            custom_params=custom_params,\\n            fallback_to_env_vars=fallback_to_env_vars,\\n            base_type=self.base_type,\\n        )\\n\\n        self._validate_built_object()\\n\\n        self.built = True\\n\\n    def extract_messages_from_artifacts(self, artifacts: dict[str, Any]) -> list[dict]:\\n        \\\"\\\"\\\"Extracts messages from the artifacts.\\n\\n        Args:\\n            artifacts (Dict[str, Any]): The artifacts to extract messages from.\\n\\n        Returns:\\n            List[str]: The extracted messages.\\n        \\\"\\\"\\\"\\n        try:\\n            text = artifacts[\\\"text\\\"]\\n            sender = artifacts.get(\\\"sender\\\")\\n            sender_name = artifacts.get(\\\"sender_name\\\")\\n            session_id = artifacts.get(\\\"session_id\\\")\\n            stream_url = artifacts.get(\\\"stream_url\\\")\\n            files = [{\\\"path\\\": file} if isinstance(file, str) else file for file in artifacts.get(\\\"files\\\", [])]\\n            component_id = self.id\\n            type_ = self.artifacts_type\\n\\n            if isinstance(sender_name, Data | Message):\\n                sender_name = sender_name.get_text()\\n\\n            messages = [\\n                ChatOutputResponse(\\n                    message=text,\\n                    sender=sender,\\n                    sender_name=sender_name,\\n                    session_id=session_id,\\n                    stream_url=stream_url,\\n                    files=files,\\n                    component_id=component_id,\\n                    type=type_,\\n                ).model_dump(exclude_none=True)\\n            ]\\n        except KeyError:\\n            messages = []\\n\\n        return messages\\n\\n    def _get_all_upstream_vertices(self) -> list[Vertex]:\\n        \\\"\\\"\\\"Walk all upstream vertices using edges, deduplicating by ID.\\\"\\\"\\\"\\n        visited: set[str] = set()\\n        result: list[Vertex] = []\\n        stack = [edge.source_id for edge in self.graph.edges if edge.target_id == self.id]\\n\\n        while stack:\\n            vid = stack.pop()\\n            if vid in visited:\\n                continue\\n            visited.add(vid)\\n            vertex = self.graph.get_vertex(vid)\\n            result.append(vertex)\\n            stack.extend(edge.source_id for edge in self.graph.edges if edge.target_id == vid)\\n\\n        return result\\n\\n    def _accumulate_upstream_token_usage(self) -> Usage | None:\\n        \\\"\\\"\\\"Accumulate token usage from all upstream vertices.\\n\\n        Walks all recursive predecessors via edges, deduplicates by vertex ID,\\n        and sums their token usage into a single total.\\n        \\\"\\\"\\\"\\n        predecessors = self._get_all_upstream_vertices()\\n        total_input = 0\\n        total_output = 0\\n        has_data = False\\n\\n        for predecessor in predecessors:\\n            if predecessor.result and predecessor.result.token_usage:\\n                usage = predecessor.result.token_usage\\n                total_input += usage.input_tokens or 0\\n                total_output += usage.output_tokens or 0\\n                has_data = True\\n\\n        # Include own token usage if present\\n        if self.custom_component:\\n            own_usage = self.custom_component._token_usage  # noqa: SLF001\\n            if own_usage:\\n                total_input += own_usage.input_tokens or 0\\n                total_output += own_usage.output_tokens or 0\\n                has_data = True\\n\\n        if not has_data:\\n            return None\\n\\n        return Usage(\\n            input_tokens=total_input,\\n            output_tokens=total_output,\\n            total_tokens=total_input + total_output,\\n        )\\n\\n    def _extract_token_usage(self) -> Usage | None:\\n        \\\"\\\"\\\"Extract token usage from the custom component if available.\\n\\n        Output vertices don't show token usage on the node badge because\\n        the accumulated total is displayed on the chat message instead.\\n        \\\"\\\"\\\"\\n        if self.is_output:\\n            return None\\n        if self.custom_component and self.custom_component._token_usage:  # noqa: SLF001\\n            return self.custom_component._token_usage  # noqa: SLF001\\n        return None\\n\\n    def finalize_build(self) -> None:\\n        result_dict = self.get_built_result()\\n        # We need to set the artifacts to pass information\\n        # to the frontend\\n        self.set_artifacts()\\n        artifacts = self.artifacts_raw\\n        messages = self.extract_messages_from_artifacts(artifacts) if isinstance(artifacts, dict) else []\\n        token_usage = self._extract_token_usage()\\n        result_dict = ResultData(\\n            results=result_dict,\\n            artifacts=artifacts,\\n            outputs=self.outputs_logs,\\n            logs=self.logs,\\n            messages=messages,\\n            component_display_name=self.display_name,\\n            component_id=self.id,\\n            token_usage=token_usage,\\n        )\\n        self.set_result(result_dict)\\n\\n    async def _build_each_vertex_in_params_dict(self) -> None:\\n        \\\"\\\"\\\"Iterates over each vertex in the params dictionary and builds it.\\\"\\\"\\\"\\n        for key, value in self.raw_params.items():\\n            if self._is_vertex(value):\\n                if value == self:\\n                    del self.params[key]\\n                    continue\\n                await self._build_vertex_and_update_params(\\n                    key,\\n                    value,\\n                )\\n            elif isinstance(value, list) and self._is_list_of_vertices(value):\\n                await self._build_list_of_vertices_and_update_params(key, value)\\n            elif isinstance(value, dict):\\n                await self._build_dict_and_update_params(\\n                    key,\\n                    value,\\n                )\\n            elif key not in self.params or self.updated_raw_params:\\n                self.params[key] = value\\n\\n        # Reset the flag after processing raw_params\\n        if self.updated_raw_params:\\n            self.updated_raw_params = False\\n\\n    async def _build_dict_and_update_params(\\n        self,\\n        key,\\n        vertices_dict: dict[str, Vertex],\\n    ) -> None:\\n        \\\"\\\"\\\"Iterates over a dictionary of vertices, builds each and updates the params dictionary.\\\"\\\"\\\"\\n        for sub_key, value in vertices_dict.items():\\n            if not self._is_vertex(value):\\n                self.params[key][sub_key] = value\\n            else:\\n                result = await value.get_result(self, target_handle_name=key)\\n                self.params[key][sub_key] = result\\n\\n    @staticmethod\\n    def _is_vertex(value):\\n        \\\"\\\"\\\"Checks if the provided value is an instance of Vertex.\\\"\\\"\\\"\\n        return isinstance(value, Vertex)\\n\\n    def _is_list_of_vertices(self, value):\\n        \\\"\\\"\\\"Checks if the provided value is a list of Vertex instances.\\\"\\\"\\\"\\n        return all(self._is_vertex(vertex) for vertex in value)\\n\\n    async def get_result(self, requester: Vertex, target_handle_name: str | None = None) -> Any:\\n        \\\"\\\"\\\"Retrieves the result of the vertex.\\n\\n        This is a read-only method so it raises an error if the vertex has not been built yet.\\n\\n        Returns:\\n            The result of the vertex.\\n        \\\"\\\"\\\"\\n        async with self.lock:\\n            result = await self._get_result(requester, target_handle_name)\\n            requester._inherit_secret_values(self)\\n            return result\\n\\n    def _inherit_secret_values(self, source_vertex: Vertex) -> None:\\n        \\\"\\\"\\\"Track secrets carried by an upstream component so displayed results stay masked.\\\"\\\"\\\"\\n        source_component = source_vertex.custom_component\\n        if source_component is not None:\\n            self._upstream_secret_values.update(getattr(source_component, \\\"_secret_values\\\", set()))\\n\\n    async def _log_transaction_async(\\n        self,\\n        flow_id: str | UUID,\\n        source: Vertex,\\n        status: str,\\n        target: Vertex | None = None,\\n        error: str | Exception | None = None,\\n        outputs: dict[str, Any] | None = None,\\n    ) -> None:\\n        \\\"\\\"\\\"Log a transaction asynchronously.\\n\\n        Args:\\n            flow_id: The ID of the flow\\n            source: Source vertex\\n            status: Transaction status\\n            target: Optional target vertex\\n            error: Optional error information\\n            outputs: Optional explicit outputs dict (component execution results)\\n        \\\"\\\"\\\"\\n        try:\\n            await log_transaction(flow_id, source, status, target, error, outputs)\\n        except Exception as exc:  # noqa: BLE001\\n            logger.debug(\\\"Error logging transaction\\\", exc_info=exc)\\n\\n    async def _get_result(\\n        self,\\n        requester: Vertex,  # noqa: ARG002\\n        target_handle_name: str | None = None,  # noqa: ARG002\\n    ) -> Any:\\n        \\\"\\\"\\\"Retrieves the result of the built component.\\n\\n        If the component has not been built yet, a ValueError is raised.\\n\\n        Returns:\\n            The built result if use_result is True, else the built object.\\n        \\\"\\\"\\\"\\n        if not self.built:\\n            msg = f\\\"Component {self.display_name} has not been built yet\\\"\\n            raise ValueError(msg)\\n\\n        return self.built_result if self.use_result else self.built_object\\n\\n    async def _build_vertex_and_update_params(self, key, vertex: Vertex) -> None:\\n        \\\"\\\"\\\"Builds a given vertex and updates the params dictionary accordingly.\\\"\\\"\\\"\\n        result = await vertex.get_result(self, target_handle_name=key)\\n        self._handle_func(key, result)\\n        if isinstance(result, list):\\n            self._extend_params_list_with_result(key, result)\\n        self.params[key] = result\\n\\n    async def _build_list_of_vertices_and_update_params(\\n        self,\\n        key,\\n        vertices: list[Vertex],\\n    ) -> None:\\n        \\\"\\\"\\\"Iterates over a list of vertices, builds each and updates the params dictionary.\\\"\\\"\\\"\\n        self.params[key] = []\\n        for vertex in vertices:\\n            # A conditionally-excluded predecessor that never built contributes nothing to a\\n            # list input. Pulling a result for it would return this input's template default\\n            # (e.g. an empty Message) and inject a stray element next to the real branch's\\n            # value -- ``ComponentVertex._get_result`` returns that default for the\\n            # single-value case, which is wrong for a merged list.\\n            if not vertex.built and vertex.id in self.graph.conditionally_excluded_vertices:\\n                continue\\n            result = await vertex.get_result(self, target_handle_name=key)\\n            # Weird check to see if the params[key] is a list\\n            # because sometimes it is a Data and breaks the code\\n            if not isinstance(self.params[key], list):\\n                self.params[key] = [self.params[key]]\\n\\n            if isinstance(result, list):\\n                self.params[key].extend(result)\\n            else:\\n                try:\\n                    if self.params[key] == result:\\n                        continue\\n\\n                    self.params[key].append(result)\\n                except AttributeError as e:\\n                    await logger.aexception(\\\"Failed to append a result to a list parameter\\\")\\n                    msg = (\\n                        f\\\"Params {key} ({self.params[key]}) is not a list and cannot be extended with {result}\\\"\\n                        f\\\"Error building Component {self.display_name}: \\\\n\\\\n{e}\\\"\\n                    )\\n                    raise ValueError(msg) from e\\n\\n    def _handle_func(self, key, result) -> None:\\n        \\\"\\\"\\\"Handles 'func' key by checking if the result is a function and setting it as coroutine.\\\"\\\"\\\"\\n        if key == \\\"func\\\":\\n            if not isinstance(result, types.FunctionType):\\n                if hasattr(result, \\\"run\\\"):\\n                    result = result.run\\n                elif hasattr(result, \\\"get_function\\\"):\\n                    result = result.get_function()\\n            elif inspect.iscoroutinefunction(result):\\n                self.params[\\\"coroutine\\\"] = result\\n            else:\\n                self.params[\\\"coroutine\\\"] = sync_to_async(result)\\n\\n    def _extend_params_list_with_result(self, key, result) -> None:\\n        \\\"\\\"\\\"Extends a list in the params dictionary with the given result if it exists.\\\"\\\"\\\"\\n        if isinstance(self.params[key], list):\\n            self.params[key].extend(result)\\n\\n    async def _build_results(\\n        self,\\n        custom_component,\\n        custom_params,\\n        base_type: str,\\n        *,\\n        fallback_to_env_vars=False,\\n    ) -> None:\\n        try:\\n            result = await initialize.loading.get_instance_results(\\n                custom_component=custom_component,\\n                custom_params=custom_params,\\n                vertex=self,\\n                fallback_to_env_vars=fallback_to_env_vars,\\n                base_type=base_type,\\n            )\\n\\n            self.outputs_logs = build_output_logs(self, result)\\n\\n            self._update_built_object_and_artifacts(result)\\n        except Exception as exc:\\n            tb = traceback.format_exc()\\n            await logger.aexception(\\\"Vertex build failed\\\")\\n            # Log transaction error\\n            flow_id = self.graph.flow_id\\n            if flow_id:\\n                await self._log_transaction_async(\\n                    str(flow_id), source=self, target=None, status=\\\"error\\\", error=str(exc)\\n                )\\n            msg = f\\\"Error building Component {self.display_name}: \\\\n\\\\n{exc}\\\"\\n            # In restricted mode this vertex may have been rebuilt with this server's component\\n            # code rather than the code saved in the flow. When the saved component does not\\n            # match the one that actually ran, say so: otherwise the policy that discarded it is\\n            # invisible and only the substituted component's own complaint reaches the user.\\n            mismatch = explain_restricted_component_mismatch(self.data.get(\\\"type\\\"), self.data.get(\\\"node\\\"))\\n            if mismatch:\\n                msg = f\\\"{msg}\\\\n\\\\n{mismatch}\\\"\\n            raise ComponentBuildError(msg, tb) from exc\\n\\n    def _update_built_object_and_artifacts(self, result: Any | tuple[Any, dict] | tuple[Component, Any, dict]) -> None:\\n        \\\"\\\"\\\"Updates the built object and its artifacts.\\\"\\\"\\\"\\n        if isinstance(result, tuple):\\n            if len(result) == 2:  # noqa: PLR2004\\n                self.built_object, self.artifacts = result\\n            elif len(result) == 3:  # noqa: PLR2004\\n                self.custom_component, self.built_object, self.artifacts = result\\n                self.logs = self.custom_component.get_output_logs()\\n                self.artifacts_raw = self.artifacts.get(\\\"raw\\\", None)\\n                self.artifacts_type = {\\n                    self.outputs[0][\\\"name\\\"]: self.artifacts.get(\\\"type\\\", None) or ArtifactType.UNKNOWN.value\\n                }\\n                self.artifacts = {self.outputs[0][\\\"name\\\"]: self.artifacts}\\n        else:\\n            self.built_object = result\\n\\n    def _validate_built_object(self) -> None:\\n        \\\"\\\"\\\"Checks if the built object is None and raises a ValueError if so.\\\"\\\"\\\"\\n        if isinstance(self.built_object, UnbuiltObject):\\n            msg = f\\\"{self.display_name}: {self.built_object_repr()}\\\"\\n            raise TypeError(msg)\\n        if self.built_object is None:\\n            message = f\\\"{self.display_name} returned None.\\\"\\n            if self.base_type == \\\"custom_components\\\":\\n                message += \\\" Make sure your build method returns a component.\\\"\\n\\n            logger.warning(message)\\n        elif isinstance(self.built_object, Iterator | AsyncIterator):\\n            if self.display_name == \\\"Text Output\\\":\\n                msg = f\\\"You are trying to stream to a {self.display_name}. Try using a Chat Output instead.\\\"\\n                raise ValueError(msg)\\n\\n    def _reset(self) -> None:\\n        self.built = False\\n        self.built_object = UnbuiltObject()\\n        self.built_result = UnbuiltResult()\\n        self.artifacts = {}\\n        self.steps_ran = []\\n        self.build_params()\\n\\n    def _is_chat_input(self) -> bool:\\n        return False\\n\\n    def build_inactive(self) -> None:\\n        # Just set the results to None\\n        self.built = True\\n        self.built_object = None\\n        self.built_result = None\\n\\n    async def build(\\n        self,\\n        user_id=None,\\n        inputs: dict[str, Any] | None = None,\\n        files: list[str] | None = None,\\n        requester: Vertex | None = None,\\n        event_manager: EventManager | None = None,\\n        **kwargs,\\n    ) -> Any:\\n        # Add lazy loading check at the beginning\\n        # Check if we need to fully load this component first\\n        from lfx.interface.components import ensure_component_loaded\\n        from lfx.services.deps import get_settings_service\\n\\n        settings_service = get_settings_service()\\n        if settings_service and settings_service.settings.lazy_load_components:\\n            component_name = self.id.split(\\\"-\\\")[0]\\n            await ensure_component_loaded(self.vertex_type, component_name, settings_service)\\n\\n        # Continue with the original implementation\\n        async with self.lock:\\n            if self.state == VertexStates.INACTIVE:\\n                # If the vertex is inactive, return None\\n                self.build_inactive()\\n                return None\\n\\n            # Loop components should always run, even when frozen,\\n            # because they need to iterate through their data\\n            is_loop_component = self.display_name == \\\"Loop\\\" or self.is_loop\\n            if self.frozen and self.built and not is_loop_component:\\n                await self.arequire_model_provider_policy(user_id, event_manager=event_manager)\\n                return await self.get_requester_result(requester)\\n            if self.built and requester is not None:\\n                # This means that the vertex has already been built\\n                # and we are just getting the result for the requester\\n                await self.arequire_model_provider_policy(user_id, event_manager=event_manager)\\n                return await self.get_requester_result(requester)\\n            self._reset()\\n\\n            # Emit build_start event for webhook real-time feedback\\n            if self.graph and self.graph.flow_id:\\n                await emit_build_start_event(self.graph.flow_id, self.id)\\n\\n            # inject session_id if it is not None\\n            if inputs is not None and \\\"session\\\" in inputs and inputs[\\\"session\\\"] is not None and self.has_session_id:\\n                session_id_value = self.get_value_from_template_dict(\\\"session_id\\\")\\n                if session_id_value == \\\"\\\":\\n                    self.update_raw_params({\\\"session_id\\\": inputs[\\\"session\\\"]}, overwrite=True)\\n            if self._is_chat_input() and (inputs or files):\\n                chat_input = {}\\n                if (\\n                    inputs\\n                    and isinstance(inputs, dict)\\n                    and \\\"input_value\\\" in inputs\\n                    and inputs.get(\\\"input_value\\\") is not None\\n                ):\\n                    chat_input.update({\\\"input_value\\\": inputs.get(INPUT_FIELD_NAME, \\\"\\\")})\\n                if files:\\n                    chat_input.update({\\\"files\\\": files})\\n\\n                self.update_raw_params(chat_input, overwrite=True)\\n\\n            # Run steps\\n            for step in self.steps:\\n                if step not in self.steps_ran:\\n                    await step(user_id=user_id, event_manager=event_manager, **kwargs)\\n                    self.steps_ran.append(step)\\n\\n            self.finalize_build()\\n\\n            # Log transaction after successful build\\n            flow_id = self.graph.flow_id\\n            if flow_id:\\n                # Extract outputs from outputs_logs for transaction logging\\n                outputs_dict = None\\n                if self.outputs_logs:\\n                    outputs_dict = {\\n                        k: v.model_dump() if hasattr(v, \\\"model_dump\\\") else v for k, v in self.outputs_logs.items()\\n                    }\\n                await self._log_transaction_async(\\n                    str(flow_id), source=self, target=None, status=\\\"success\\\", outputs=outputs_dict\\n                )\\n\\n        return await self.get_requester_result(requester)\\n\\n    async def get_requester_result(self, requester: Vertex | None):\\n        # If the requester is None, this means that\\n        # the Vertex is the root of the graph\\n        if requester is None:\\n            return self.built_object\\n\\n        # Get the requester edge\\n        requester_edge = next((edge for edge in self.edges if edge.target_id == requester.id), None)\\n        # Return the result of the requester edge\\n        return (\\n            None\\n            if requester_edge is None\\n            else await requester_edge.get_result_from_source(source=self, target=requester)\\n        )\\n\\n    def add_edge(self, edge: CycleEdge) -> None:\\n        if edge not in self.edges:\\n            self.edges.append(edge)\\n\\n    def __repr__(self) -> str:\\n        return f\\\"Vertex(display_name={self.display_name}, id={self.id}, data={self.data})\\\"\\n\\n    def __eq__(self, /, other: object) -> bool:\\n        try:\\n            if not isinstance(other, Vertex):\\n                return False\\n            # We should create a more robust comparison\\n            # for the Vertex class\\n            ids_are_equal = self.id == other.id\\n            # self.data is a dict and we need to compare them\\n            # to check if they are equal\\n            data_are_equal = self.data == other.data\\n        except AttributeError:\\n            return False\\n        else:\\n            return ids_are_equal and data_are_equal\\n\\n    def __hash__(self) -> int:\\n        return id(self)\\n\\n    def built_object_repr(self) -> str:\\n        # Add a message with an emoji, stars for success,\\n        return \\\"Built successfully \u2728\\\" if self.built_object is not None else \\\"Failed to build \ud83d\ude35\u200d\ud83d\udcab\\\"\\n\\n    def apply_on_outputs(self, func: Callable[[Any], Any]) -> None:\\n        \\\"\\\"\\\"Applies a function to the outputs of the vertex.\\\"\\\"\\\"\\n        if not self.custom_component or not self.custom_component.outputs:\\n            return\\n        # Apply the function to each output\\n        [func(output) for output in self.custom_component.get_outputs_map().values()]\\n\\n    # AGUI/AG UI Event Streaming Callbacks/Methods - (Optional, see Observable decorator)\\n    def raw_event_metrics(self, optional_fields: dict | None) -> dict:\\n        \\\"\\\"\\\"This method is used to get the metrics of the vertex by the Observable decorator.\\n\\n        If the vertex has a get_metrics method, it will be called, and the metrics will be captured\\n        to stream back to the user in an AGUI compliant format.\\n        Additional fields/metrics to be captured can be modified in this method, or in the callback methods,\\n        which are before_callback_event and after_callback_event before returning the AGUI event.\\n        \\\"\\\"\\\"\\n        if optional_fields is None:\\n            optional_fields = {}\\n        import time\\n\\n        return {\\\"timestamp\\\": time.time(), **optional_fields}\\n\\n    def before_callback_event(self, *args, **kwargs) -> StepStartedEvent:  # noqa: ARG002\\n        \\\"\\\"\\\"Should be a AGUI compatible event.\\n\\n        VERTEX class generates a StepStartedEvent event.\\n        \\\"\\\"\\\"\\n        metrics = {}\\n        if hasattr(self, \\\"raw_event_metrics\\\"):\\n            metrics = self.raw_event_metrics({\\\"component_id\\\": self.id})\\n\\n        return StepStartedEvent(step_name=self.display_name, raw_event={\\\"langflow\\\": metrics})\\n\\n    def after_callback_event(self, result, *args, **kwargs) -> StepFinishedEvent:  # noqa: ARG002\\n        \\\"\\\"\\\"Should be a AGUI compatible event.\\n\\n        VERTEX class generates a StepFinishedEvent event.\\n        \\\"\\\"\\\"\\n        metrics = {}\\n        if hasattr(self, \\\"raw_event_metrics\\\"):\\n            metrics = self.raw_event_metrics({\\\"component_id\\\": self.id})\\n        return StepFinishedEvent(step_name=self.display_name, raw_event={\\\"langflow\\\": metrics})\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/vertex/constants.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/vertex/exceptions.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4137beed34422344d7b30459875921d19dcac928d0b09818e734d4ea8d236e84\",\"content\":\"class NoComponentInstanceError(Exception):\\n    def __init__(self, vertex_id: str):\\n        message = f\\\"Vertex {vertex_id} does not have a component instance.\\\"\\n        super().__init__(message)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/vertex/param_handler.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"faf45287a46ad754b4cdf590b0ff8893779777a1afbaf02df8ad2b3faf4fdfdf\",\"content\":\"\\\"\\\"\\\"Base module for vertex-related functionality.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport ast\\nfrom collections.abc import Mapping\\nfrom pathlib import PurePosixPath, PureWindowsPath\\nfrom typing import TYPE_CHECKING, Any\\n\\nimport pandas as pd\\n\\nfrom lfx.log.logger import logger\\nfrom lfx.schema.data import Data\\nfrom lfx.services.deps import get_storage_service\\nfrom lfx.utils.constants import DIRECT_TYPES\\nfrom lfx.utils.file_path_security import (\\n    LocalFileAccessError,\\n    StorageNamespaceError,\\n    enforce_local_file_access,\\n    enforce_storage_key_scope,\\n    is_local_file_access_restricted,\\n)\\nfrom lfx.utils.util import unescape_string\\n\\nif TYPE_CHECKING:\\n    from lfx.graph.edge.base import CycleEdge\\n    from lfx.graph.vertex.base import Vertex\\n\\n\\ndef _coerce_str_value(v: Any) -> str:\\n    \\\"\\\"\\\"Coerce a value to string for str-typed fields, handling Message/Data/dict objects.\\\"\\\"\\\"\\n    if isinstance(v, str):\\n        return unescape_string(v)\\n    if isinstance(v, Data):\\n        return unescape_string(v.get_text())\\n    if isinstance(v, dict):\\n        # Serialized Message or Data -- extract text from nested structure\\n        data = v.get(\\\"data\\\")\\n        nested_text = data.get(\\\"text\\\", \\\"\\\") if isinstance(data, dict) else \\\"\\\"\\n        text = v.get(\\\"text\\\", nested_text)\\n        return unescape_string(text) if isinstance(text, str) else str(v)\\n    return str(v)\\n\\n\\nclass ParameterHandler:\\n    \\\"\\\"\\\"Handles parameter processing for vertices.\\\"\\\"\\\"\\n\\n    def __init__(self, vertex: Vertex, storage_service) -> None:\\n        \\\"\\\"\\\"Initialize the parameter handler.\\n\\n        Args:\\n            vertex: The vertex to handle parameters for.\\n            storage_service: The storage service to use.\\n        \\\"\\\"\\\"\\n        self.vertex = vertex\\n        self.template_dict: dict[str, dict] = {\\n            key: value for key, value in vertex.data[\\\"node\\\"][\\\"template\\\"].items() if isinstance(value, dict)\\n        }\\n        self.params: dict[str, Any] = {}\\n        self.load_from_db_fields: list[str] = []\\n        # Lazy initialization of storage service\\n        self._storage_service = storage_service\\n        self._storage_service_initialized = False\\n        self._canonical_file_fields_cache: dict[str, dict[str, Any]] | None = None\\n\\n    @property\\n    def storage_service(self):\\n        \\\"\\\"\\\"Lazily initialize storage service only when accessed.\\\"\\\"\\\"\\n        if not self._storage_service_initialized:\\n            if self._storage_service is None:\\n                self._storage_service = get_storage_service()\\n            self._storage_service_initialized = True\\n        return self._storage_service\\n\\n    @staticmethod\\n    def _file_input_names_from_code(code: str) -> set[str]:\\n        \\\"\\\"\\\"Extract literal FileInput names from trusted component source.\\\"\\\"\\\"\\n        try:\\n            tree = ast.parse(code)\\n        except SyntaxError:\\n            return set()\\n\\n        aliases = {\\\"FileInput\\\"}\\n        for node in ast.walk(tree):\\n            if isinstance(node, ast.ImportFrom):\\n                aliases.update(alias.asname or alias.name for alias in node.names if alias.name == \\\"FileInput\\\")\\n\\n        names: set[str] = set()\\n        for node in ast.walk(tree):\\n            if not isinstance(node, ast.Call):\\n                continue\\n            is_file_input = (isinstance(node.func, ast.Name) and node.func.id in aliases) or (\\n                isinstance(node.func, ast.Attribute) and node.func.attr == \\\"FileInput\\\"\\n            )\\n            if not is_file_input:\\n                continue\\n            for keyword in node.keywords:\\n                if keyword.arg == \\\"name\\\" and isinstance(keyword.value, ast.Constant):\\n                    if isinstance(keyword.value.value, str) and keyword.value.value:\\n                        names.add(keyword.value.value)\\n                    break\\n        return names\\n\\n    def _canonical_file_fields(self) -> dict[str, dict[str, Any]]:\\n        \\\"\\\"\\\"Return FileInput metadata derived from server-trusted component source.\\\"\\\"\\\"\\n        if self._canonical_file_fields_cache is not None:\\n            return self._canonical_file_fields_cache\\n\\n        canonical_fields: dict[str, dict[str, Any]] = {}\\n        code_field = self.template_dict.get(\\\"code\\\")\\n        submitted_code = code_field.get(\\\"value\\\") if isinstance(code_field, dict) else None\\n        if not isinstance(submitted_code, str) or not submitted_code:\\n            self._canonical_file_fields_cache = canonical_fields\\n            return canonical_fields\\n\\n        # The flow policy may substitute a server-owned source for a matching\\n        # submitted hash. Use that same trusted source for input classification;\\n        # an exact source comparison below prevents request metadata from\\n        # declaring what is or is not a FileInput.\\n        from lfx.interface.components import component_cache\\n        from lfx.utils.flow_validation import get_trusted_code_for_validation\\n\\n        trusted_code = get_trusted_code_for_validation(submitted_code) or submitted_code\\n        all_types_dict = component_cache.all_types_dict\\n        if isinstance(all_types_dict, Mapping):\\n            for category_components in all_types_dict.values():\\n                if not isinstance(category_components, Mapping):\\n                    continue\\n                for component_data in category_components.values():\\n                    if not isinstance(component_data, Mapping):\\n                        continue\\n                    template = component_data.get(\\\"template\\\")\\n                    if not isinstance(template, Mapping):\\n                        continue\\n                    server_code_field = template.get(\\\"code\\\")\\n                    server_code = server_code_field.get(\\\"value\\\") if isinstance(server_code_field, Mapping) else None\\n                    if server_code != trusted_code:\\n                        continue\\n                    for field_name, field in template.items():\\n                        if not isinstance(field_name, str) or not isinstance(field, Mapping):\\n                            continue\\n                        if field.get(\\\"type\\\") == \\\"file\\\" or field.get(\\\"_input_type\\\") == \\\"FileInput\\\":\\n                            canonical_fields.setdefault(field_name, dict(field))\\n\\n        # Direct declarations remain detectable while the component registry is\\n        # warming, and cover older trusted component versions absent from the\\n        # current registry. Registry metadata above still supplies list/required\\n        # semantics for inherited or dynamically assembled inputs.\\n        for field_name in self._file_input_names_from_code(trusted_code):\\n            canonical_fields.setdefault(\\n                field_name,\\n                {\\\"type\\\": \\\"file\\\", \\\"_input_type\\\": \\\"FileInput\\\", \\\"list\\\": False, \\\"required\\\": False},\\n            )\\n\\n        self._canonical_file_fields_cache = canonical_fields\\n        return canonical_fields\\n\\n    def _effective_file_field(self, field_name: str, field: dict[str, Any]) -> dict[str, Any]:\\n        \\\"\\\"\\\"Overlay server-owned FileInput semantics on request-supplied values.\\\"\\\"\\\"\\n        canonical = self._canonical_file_fields().get(field_name)\\n        if canonical is None:\\n            return field\\n\\n        effective = dict(field)\\n        for key in (\\\"type\\\", \\\"_input_type\\\", \\\"list\\\", \\\"required\\\", \\\"display_name\\\"):\\n            if key in canonical:\\n                effective[key] = canonical[key]\\n        effective[\\\"type\\\"] = \\\"file\\\"\\n        effective[\\\"_canonical_file_input\\\"] = True\\n        effective.setdefault(\\\"list\\\", False)\\n        return effective\\n\\n    @staticmethod\\n    def _is_file_field(field: Mapping[str, Any]) -> bool:\\n        return field.get(\\\"type\\\") == \\\"file\\\" or field.get(\\\"_input_type\\\") == \\\"FileInput\\\"\\n\\n    def process_edge_parameters(self, edges: list[CycleEdge]) -> dict[str, Any]:\\n        \\\"\\\"\\\"Process parameters from edges.\\n\\n        Some params are required, some are optional, and some params are Python base classes\\n        (like str) while others are LangChain objects (like LLMChain, BasePromptTemplate).\\n        This method distinguishes between them and sets the appropriate parameters.\\n\\n        Args:\\n            edges: A list of edges connected to the vertex.\\n\\n        Returns:\\n            A dictionary of processed parameters.\\n        \\\"\\\"\\\"\\n        params: dict[str, Any] = {}\\n        for edge in edges:\\n            if not hasattr(edge, \\\"target_param\\\"):\\n                continue\\n            params = self._set_params_from_normal_edge(params, edge)\\n        return params\\n\\n    def _set_params_from_normal_edge(self, params: dict[str, Any], edge: CycleEdge) -> dict[str, Any]:\\n        param_key = edge.target_param\\n\\n        if param_key in self.template_dict and edge.target_id == self.vertex.id:\\n            field = self.template_dict[param_key]\\n            if field.get(\\\"list\\\"):\\n                if param_key not in params:\\n                    params[param_key] = []\\n                params[param_key].append(self.vertex.graph.get_vertex(edge.source_id))\\n            else:\\n                params[param_key] = self.process_non_list_edge_param(field, edge)\\n        elif param_key in self.vertex.output_names:\\n            # If the param_key is in the output_names, it means that the loop is run\\n            #  if the loop is run the param_key item will be set over here\\n            # validate the edge\\n            params[param_key] = self.vertex.graph.get_vertex(edge.source_id)\\n        return params\\n\\n    def process_non_list_edge_param(self, field: dict, edge: CycleEdge) -> Any:\\n        \\\"\\\"\\\"Process non-list edge parameters.\\\"\\\"\\\"\\n        param_dict = field.get(\\\"value\\\")\\n        if isinstance(param_dict, dict) and len(param_dict) == 1:\\n            return {key: self.vertex.graph.get_vertex(edge.source_id) for key in param_dict}\\n        return self.vertex.graph.get_vertex(edge.source_id)\\n\\n    def process_field_parameters(self) -> tuple[dict[str, Any], list[str]]:\\n        \\\"\\\"\\\"Process parameters from template fields.\\n\\n        For each key in the template dictionary:\\n            - If the field type is 'file', process file-related parameters.\\n            - If the field type is in DIRECT_TYPES, handle direct type parameters.\\n            - Handle optional fields by setting default values or removing them.\\n\\n        Returns:\\n            A tuple containing:\\n                - A dictionary of processed field parameters.\\n                - A list of fields that need to be loaded from the database.\\n        \\\"\\\"\\\"\\n        params: dict[str, Any] = {}\\n        load_from_db_fields: list[str] = []\\n\\n        restricted = is_local_file_access_restricted()\\n        for field_name, request_field in self.template_dict.items():\\n            field = self._effective_file_field(field_name, request_field) if restricted else request_field\\n            if self.should_skip_field(field_name, field, params):\\n                continue\\n\\n            if self._is_file_field(field):\\n                params = self.process_file_field(field_name, field, params)\\n            elif field.get(\\\"type\\\") in DIRECT_TYPES and params.get(field_name) is None:\\n                params, load_from_db_fields = self._process_direct_type_field(\\n                    field_name, field, params, load_from_db_fields\\n                )\\n            else:\\n                msg = f\\\"Field {field_name} in {self.vertex.display_name} is not a valid field type: {field.get('type')}\\\"\\n                raise ValueError(msg)\\n\\n            self.handle_optional_field(field_name, field, params)\\n\\n        return params, load_from_db_fields\\n\\n    def should_skip_field(self, field_name: str, field: dict, params: dict[str, Any]) -> bool:\\n        \\\"\\\"\\\"Determine if field should be skipped.\\\"\\\"\\\"\\n        if field.get(\\\"override_skip\\\"):\\n            return False\\n        return (\\n            field.get(\\\"type\\\") == \\\"other\\\"\\n            or field_name in params\\n            or field_name == \\\"_type\\\"\\n            or (not field.get(\\\"show\\\") and field_name != \\\"code\\\")\\n        )\\n\\n    def process_file_field(self, field_name: str, field: dict, params: dict[str, Any]) -> dict[str, Any]:\\n        \\\"\\\"\\\"Process file type fields.\\n\\n        Converts logical paths (flow_id/filename) to component-ready paths.\\n        \\\"\\\"\\\"\\n        file_path = field.get(\\\"file_path\\\")\\n        if not file_path and field.get(\\\"_canonical_file_input\\\"):\\n            file_path = field.get(\\\"value\\\")\\n        if file_path:\\n            params[field_name] = self.process_file_value(file_path, is_list=bool(field.get(\\\"list\\\")))\\n        elif field.get(\\\"required\\\"):\\n            field_display_name = field.get(\\\"display_name\\\")\\n            logger.warning(\\n                \\\"File path not found for %s in component %s. Setting to None.\\\",\\n                field_display_name,\\n                self.vertex.display_name,\\n            )\\n            params[field_name] = None\\n        elif field.get(\\\"list\\\"):\\n            params[field_name] = []\\n        else:\\n            params[field_name] = None\\n        return params\\n\\n    def process_runtime_params(self, params: dict[str, Any]) -> dict[str, Any]:\\n        \\\"\\\"\\\"Resolve and contain FileInput values supplied as runtime tweaks.\\\"\\\"\\\"\\n        processed = params.copy()\\n        restricted = is_local_file_access_restricted()\\n\\n        for field_name, value in processed.items():\\n            request_field = self.template_dict.get(field_name, {})\\n            field = self._effective_file_field(field_name, request_field)\\n            empty_value = value is None or (isinstance(value, str | list) and not value)\\n            if not self._is_file_field(field) or empty_value:\\n                continue\\n            file_value = value\\n            if isinstance(value, dict):\\n                if \\\"file_path\\\" in value:\\n                    file_value = value[\\\"file_path\\\"]\\n                elif set(value) == {\\\"value\\\"}:\\n                    file_value = value[\\\"value\\\"]\\n                else:\\n                    msg = \\\"Runtime FileInput tweaks must provide a file path.\\\"\\n                    raise LocalFileAccessError(msg)\\n            if file_value is None or (isinstance(file_value, str | list) and not file_value):\\n                continue\\n\\n            is_list = bool(field.get(\\\"list\\\")) or isinstance(file_value, list)\\n            if restricted:\\n                processed[field_name] = self.process_file_value(file_value, is_list=is_list)\\n            else:\\n                # Unrestricted local paths are a documented single-tenant feature. Inspect\\n                # their storage-key shape without resolving or rewriting the caller's value.\\n                self._validate_unrestricted_file_value(file_value, is_list=is_list)\\n        return processed\\n\\n    def _validate_unrestricted_file_value(self, file_path: Any, *, is_list: bool) -> None:\\n        \\\"\\\"\\\"Validate an unrestricted FileInput value without changing its representation.\\\"\\\"\\\"\\n        if is_list:\\n            paths = [file_path] if isinstance(file_path, str) else file_path\\n            if not isinstance(paths, list) or not all(isinstance(path, str) for path in paths):\\n                msg = \\\"FileInput values must be file path strings.\\\"\\n                raise LocalFileAccessError(msg)\\n        else:\\n            if not isinstance(file_path, str):\\n                msg = \\\"FileInput values must be file path strings.\\\"\\n                raise LocalFileAccessError(msg)\\n            paths = [file_path]\\n\\n        for path in paths:\\n            self._validate_unrestricted_file_path(path)\\n\\n    def _scoped_storage_key(self, file_path: str) -> str:\\n        \\\"\\\"\\\"Reject a logical storage key whose namespace is outside the executing graph.\\n\\n        ``StorageService.resolve_component_path`` turns a relative ``\\\"<namespace>/<file_name>\\\"``\\n        value into ``<storage root>/<namespace>/<file_name>``, so the namespace segment selects a\\n        per-principal storage location. The value comes from the saved template or a runtime\\n        tweak, so it has to be checked *before* it is resolved \u2014 afterwards the component only\\n        sees an already-resolved path and the shape of the input has decided access on its own.\\n\\n        These cases are deliberately left alone:\\n\\n        * Absolute paths are not storage keys. Reading a local server file by absolute path is\\n          the documented single-tenant behavior that\\n          ``LANGFLOW_RESTRICT_LOCAL_FILE_ACCESS`` governs, so they stay with\\n          ``_enforce_file_paths``. Absoluteness is tested against both flavours: a Windows\\n          drive-letter path written with forward slashes (\\\"C:/data/report.csv\\\") is not\\n          POSIX-absolute, so testing only ``PurePosixPath`` would split it into namespace\\n          \\\"C:\\\" and reject a legitimate local path -- while the backslash spelling of the\\n          same path must remain legitimate too.\\n        * Separatorless relative values are local file names, not storage keys.\\n        * Restricted mode, where ``_enforce_file_paths`` already pins the resolved local path and\\n          the S3 logical key to the graph's own scopes. This check exists to close the\\n          unrestricted default, and skipping it keeps restricted behavior byte-identical.\\n        \\\"\\\"\\\"\\n        if is_local_file_access_restricted():\\n            return file_path\\n        return self._validate_unrestricted_file_path(file_path)\\n\\n    def _validate_unrestricted_file_path(self, file_path: str) -> str:\\n        \\\"\\\"\\\"Validate a path's storage-key shape without resolving or rewriting it.\\\"\\\"\\\"\\n        if PurePosixPath(file_path).is_absolute() or PureWindowsPath(file_path).is_absolute():\\n            return file_path\\n        if \\\"\\\\\\\\\\\" in file_path:\\n            msg = \\\"Relative FileInput paths must not contain backslash separators or traversal sequences.\\\"\\n            raise StorageNamespaceError(msg)\\n        if \\\"/\\\" not in file_path:\\n            return file_path\\n        enforce_storage_key_scope(file_path, self._file_access_scopes())\\n        return file_path\\n\\n    def process_file_value(self, file_path: str | list[str], *, is_list: bool) -> str | list[str]:\\n        \\\"\\\"\\\"Resolve a FileInput value and enforce the configured storage boundary.\\\"\\\"\\\"\\n        try:\\n            if is_list:\\n                paths = [file_path] if isinstance(file_path, str) else file_path\\n                if not isinstance(paths, list) or not all(isinstance(path, str) for path in paths):\\n                    msg = \\\"FileInput values must be file path strings.\\\"\\n                    raise LocalFileAccessError(msg)\\n                full_path: str | list[str] = [\\n                    self.storage_service.resolve_component_path(self._scoped_storage_key(path)) for path in paths\\n                ]\\n            else:\\n                if not isinstance(file_path, str):\\n                    msg = \\\"FileInput values must be file path strings.\\\"\\n                    raise LocalFileAccessError(msg)\\n                full_path = self.storage_service.resolve_component_path(self._scoped_storage_key(file_path))\\n        except StorageNamespaceError:\\n            # A namespace denial must never be downgraded. It is a ValueError subclass, so the\\n            # broad handler below would otherwise decide its fate by substring-matching an\\n            # unrelated message -- correct today, but one added branch away from silently\\n            # turning a cross-tenant denial back into a read.\\n            raise\\n        except ValueError as e:\\n            if \\\"too many values to unpack\\\" in str(e):\\n                full_path = file_path\\n            else:\\n                raise\\n        return self._enforce_file_paths(full_path)\\n\\n    def _file_access_scopes(self) -> list[str]:\\n        \\\"\\\"\\\"Return server-established storage namespaces for the executing graph.\\\"\\\"\\\"\\n        graph = getattr(self.vertex, \\\"graph\\\", None)\\n        scopes: list[str] = []\\n        for candidate in (\\n            getattr(graph, \\\"user_id\\\", None),\\n            getattr(graph, \\\"flow_id\\\", None),\\n            getattr(graph, \\\"source_flow_id\\\", None),\\n        ):\\n            if candidate is not None:\\n                scope = str(candidate).strip()\\n                if scope and scope not in scopes:\\n                    scopes.append(scope)\\n        return scopes\\n\\n    def _enforce_file_paths(self, file_paths: str | list[str]) -> str | list[str]:\\n        \\\"\\\"\\\"Apply storage-specific containment before FileInput values reach components.\\\"\\\"\\\"\\n        storage_settings = getattr(getattr(self.storage_service, \\\"settings_service\\\", None), \\\"settings\\\", None)\\n        storage_type = str(getattr(storage_settings, \\\"storage_type\\\", \\\"local\\\")).lower()\\n        if not is_local_file_access_restricted():\\n            return file_paths\\n\\n        scopes = self._file_access_scopes()\\n        if storage_type == \\\"s3\\\":\\n            if isinstance(file_paths, list):\\n                return [self._enforce_s3_logical_key(path, scopes) for path in file_paths]\\n            return self._enforce_s3_logical_key(file_paths, scopes)\\n\\n        if isinstance(file_paths, list):\\n            return [str(enforce_local_file_access(path, scope_ids=scopes)) for path in file_paths]\\n        return str(enforce_local_file_access(file_paths, scope_ids=scopes))\\n\\n    @staticmethod\\n    def _enforce_s3_logical_key(file_path: str, scopes: list[str]) -> str:\\n        \\\"\\\"\\\"Reject S3 logical keys that could be interpreted as foreign local paths.\\\"\\\"\\\"\\n        path = str(file_path)\\n        segments = path.split(\\\"/\\\")\\n        logical_path = PurePosixPath(path)\\n        if (\\n            not path\\n            or \\\"\\\\x00\\\" in path\\n            or \\\"\\\\\\\\\\\" in path\\n            or logical_path.is_absolute()\\n            or any(segment in {\\\"\\\", \\\".\\\", \\\"..\\\"} for segment in segments)\\n            or not logical_path.parts\\n            or logical_path.parts[0] not in scopes\\n        ):\\n            msg = \\\"S3 file references must stay within the authenticated user's or executing flow's namespace.\\\"\\n            raise LocalFileAccessError(msg)\\n        return path\\n\\n    def _process_direct_type_field(\\n        self, field_name: str, field: dict, params: dict[str, Any], load_from_db_fields: list[str]\\n    ) -> tuple[dict[str, Any], list[str]]:\\n        \\\"\\\"\\\"Process direct type fields.\\\"\\\"\\\"\\n        val = field.get(\\\"value\\\")\\n\\n        if field.get(\\\"type\\\") == \\\"code\\\":\\n            params = self._handle_code_field(field_name, val, params)\\n        elif field.get(\\\"type\\\") in {\\\"dict\\\", \\\"NestedDict\\\"}:\\n            params = self._handle_dict_field(field_name, val, params)\\n        elif field.get(\\\"type\\\") == \\\"table\\\":\\n            params = self._handle_table_field(field_name, val, params, load_from_db_fields)\\n        else:\\n            params = self._handle_other_direct_types(field_name, field, val, params)\\n\\n        if field.get(\\\"load_from_db\\\"):\\n            # Skip load_from_db if the field itself has an incoming edge\\n            has_incoming_edge = self.vertex.get_incoming_edge_by_target_param(field_name) is not None\\n            # Skip credential fields when the model field has an incoming edge,\\n            # because the connected model component provides its own credentials\\n            is_secret = field.get(\\\"_input_type\\\") == \\\"SecretStrInput\\\" or field.get(\\\"password\\\")\\n            model_has_edge = (\\n                is_secret\\n                and \\\"model\\\" in self.template_dict\\n                and self.vertex.get_incoming_edge_by_target_param(\\\"model\\\") is not None\\n            )\\n            # Skip credential fields when the node is in \\\"Connect other models\\\" mode\\n            # (user chose to wire an external model instead of the built-in provider)\\n            model_field = self.template_dict.get(\\\"model\\\", {})\\n            in_connection_mode = is_secret and model_field.get(\\\"_connection_mode\\\", False)\\n            if not has_incoming_edge and not model_has_edge and not in_connection_mode:\\n                load_from_db_fields.append(field_name)\\n\\n        return params, load_from_db_fields\\n\\n    def _handle_table_field(\\n        self,\\n        field_name: str,\\n        val: Any,\\n        params: dict[str, Any],\\n        load_from_db_fields: list[str] | None = None,\\n    ) -> dict[str, Any]:\\n        \\\"\\\"\\\"Handle table field type with load_from_db column support.\\\"\\\"\\\"\\n        if load_from_db_fields is None:\\n            load_from_db_fields = []\\n        if val is None:\\n            params[field_name] = []\\n            return params\\n\\n        # Store the table data as-is for now\\n        # The actual column processing will happen in the loading phase\\n        if isinstance(val, list) and all(isinstance(item, dict) for item in val):\\n            params[field_name] = val\\n        else:\\n            msg = f\\\"Invalid value type {type(val)} for table field {field_name}\\\"\\n            raise ValueError(msg)\\n\\n        # Get table schema from the field to identify load_from_db columns\\n        field_template = self.template_dict.get(field_name, {})\\n        table_schema = field_template.get(\\\"table_schema\\\", [])\\n\\n        # Track which columns need database loading\\n        load_from_db_columns = []\\n        for column_schema in table_schema:\\n            if isinstance(column_schema, dict) and column_schema.get(\\\"load_from_db\\\"):\\n                load_from_db_columns.append(column_schema[\\\"name\\\"])\\n            elif hasattr(column_schema, \\\"load_from_db\\\") and column_schema.load_from_db:\\n                load_from_db_columns.append(column_schema.name)\\n\\n        # Store metadata for later processing\\n        if load_from_db_columns:\\n            # Store table column metadata for the loading phase\\n            table_load_metadata_key = f\\\"{field_name}_load_from_db_columns\\\"\\n            params[table_load_metadata_key] = load_from_db_columns\\n\\n            # Add to load_from_db_fields so it gets processed\\n            # We'll use a special naming convention to identify table fields\\n            load_from_db_fields.append(f\\\"table:{field_name}\\\")\\n            self.load_from_db_fields.append(f\\\"table:{field_name}\\\")\\n\\n        return params\\n\\n    def handle_optional_field(self, field_name: str, field: dict, params: dict[str, Any]) -> None:\\n        \\\"\\\"\\\"Handle optional fields.\\\"\\\"\\\"\\n        if not field.get(\\\"required\\\") and params.get(field_name) is None:\\n            if field.get(\\\"default\\\"):\\n                params[field_name] = field.get(\\\"default\\\")\\n            else:\\n                params.pop(field_name, None)\\n\\n    def _handle_code_field(self, field_name: str, val: Any, params: dict[str, Any]) -> dict[str, Any]:\\n        \\\"\\\"\\\"Handle code field type.\\\"\\\"\\\"\\n        try:\\n            if field_name == \\\"code\\\":\\n                params[field_name] = val\\n            else:\\n                params[field_name] = ast.literal_eval(val) if val else None\\n        except Exception:  # noqa: BLE001\\n            logger.debug(\\\"Error evaluating code for %s\\\", field_name)\\n            params[field_name] = val\\n        return params\\n\\n    def _handle_dict_field(self, field_name: str, val: Any, params: dict[str, Any]) -> dict[str, Any]:\\n        \\\"\\\"\\\"Handle dictionary field type.\\\"\\\"\\\"\\n        match val:\\n            case list():\\n                # Convert list of {\\\"key\\\": k, \\\"value\\\": v} pairs to a flat dict.\\n                # e.g. [{\\\"key\\\": \\\"h1\\\", \\\"value\\\": \\\"v1\\\"}, {\\\"key\\\": \\\"h2\\\", \\\"value\\\": \\\"v2\\\"}] -> {\\\"h1\\\": \\\"v1\\\", \\\"h2\\\": \\\"v2\\\"}\\n                if val and all(isinstance(item, dict) and \\\"key\\\" in item and \\\"value\\\" in item for item in val):\\n                    params[field_name] = {item[\\\"key\\\"]: item[\\\"value\\\"] for item in val}\\n                else:\\n                    # Merge generic list of dicts into a single dict.\\n                    # e.g. [{\\\"a\\\": 1}, {\\\"b\\\": 2}] -> {\\\"a\\\": 1, \\\"b\\\": 2}\\n                    params[field_name] = {k: v for item in val for k, v in item.items()}\\n            case dict():\\n                params[field_name] = val\\n            case _:\\n                logger.warning(\\n                    \\\"Unexpected type %s for dict field '%s'; expected list or dict, got %r\\\",\\n                    type(val).__name__,\\n                    field_name,\\n                    val,\\n                )\\n                params[field_name] = val\\n        return params\\n\\n    def _handle_other_direct_types(\\n        self, field_name: str, field: dict, val: Any, params: dict[str, Any]\\n    ) -> dict[str, Any]:\\n        \\\"\\\"\\\"Handle other direct type fields.\\\"\\\"\\\"\\n        if val is None:\\n            return params\\n\\n        match field.get(\\\"type\\\"):\\n            case \\\"int\\\":\\n                try:\\n                    params[field_name] = int(val)\\n                except ValueError:\\n                    params[field_name] = val\\n            case \\\"float\\\" | \\\"slider\\\":\\n                try:\\n                    params[field_name] = float(val)\\n                except ValueError:\\n                    params[field_name] = val\\n            case \\\"str\\\":\\n                match val:\\n                    case list():\\n                        params[field_name] = [_coerce_str_value(v) for v in val]\\n                    case str():\\n                        params[field_name] = unescape_string(val)\\n                    case Data():\\n                        params[field_name] = unescape_string(val.get_text())\\n            case \\\"bool\\\":\\n                match val:\\n                    case bool():\\n                        params[field_name] = val\\n                    case str():\\n                        params[field_name] = bool(val)\\n            case \\\"table\\\" | \\\"tools\\\":\\n                if isinstance(val, list) and all(isinstance(item, dict) for item in val):\\n                    params[field_name] = pd.DataFrame(val)\\n                else:\\n                    msg = f\\\"Invalid value type {type(val)} for field {field_name}\\\"\\n                    raise ValueError(msg)\\n            case _:\\n                if val:\\n                    params[field_name] = val\\n\\n        return params\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/vertex/schema.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"de1e9ced34dd648d66cdf01e6e10fee8208244bbb5990f140e68098a3c79cd68\",\"content\":\"from enum import Enum\\n\\nfrom typing_extensions import NotRequired, TypedDict\\n\\n\\nclass NodeTypeEnum(str, Enum):\\n    NoteNode = \\\"noteNode\\\"\\n    GenericNode = \\\"genericNode\\\"\\n\\n\\nclass Position(TypedDict):\\n    x: float\\n    y: float\\n\\n\\nclass NodeData(TypedDict):\\n    id: str\\n    data: dict\\n    dragging: NotRequired[bool]\\n    height: NotRequired[int]\\n    width: NotRequired[int]\\n    position: NotRequired[Position]\\n    positionAbsolute: NotRequired[Position]\\n    selected: NotRequired[bool]\\n    parent_node_id: NotRequired[str]\\n    type: NotRequired[NodeTypeEnum]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/vertex/utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"889998e0f5ed6b97585935f648c11ba5f30aaf3c242554268bcaacb52bfc0fb2\",\"content\":\"from __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\n\\nif TYPE_CHECKING:\\n    from lfx.graph.vertex.base import Vertex\\n\\n\\ndef build_clean_params(target: Vertex) -> dict:\\n    \\\"\\\"\\\"Cleans the parameters of the target vertex.\\\"\\\"\\\"\\n    # Removes all keys that the values aren't python types like str, int, bool, etc.\\n    params = {\\n        key: value for key, value in target.params.items() if isinstance(value, str | int | bool | float | list | dict)\\n    }\\n    # if it is a list we need to check if the contents are python types\\n    for key, value in params.items():\\n        if isinstance(value, list):\\n            params[key] = [item for item in value if isinstance(item, str | int | bool | float | list | dict)]\\n    return params\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/graph/vertex/vertex_types.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cba1facb1dd653b938dcc2a079d33d2b7b95b5068a8d1217d83cb008c66d4c2a\",\"content\":\"from __future__ import annotations\\n\\nimport contextlib\\nimport json\\nfrom collections.abc import AsyncIterator, Generator, Iterator\\nfrom typing import TYPE_CHECKING, Any, cast\\n\\nimport yaml\\nfrom langchain_core.messages import AIMessage, AIMessageChunk\\n\\nfrom lfx.graph.schema import CHAT_COMPONENTS, RECORDS_COMPONENTS, InterfaceComponentTypes, ResultData\\nfrom lfx.graph.utils import UnbuiltObject, log_vertex_build, rewrite_file_path\\nfrom lfx.graph.vertex.base import Vertex\\nfrom lfx.graph.vertex.exceptions import NoComponentInstanceError\\nfrom lfx.log.logger import logger\\nfrom lfx.schema.artifact import ArtifactType\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.message import Message\\nfrom lfx.schema.schema import INPUT_FIELD_NAME\\nfrom lfx.serialization.serialization import serialize\\nfrom lfx.template.field.base import UNDEFINED, Output\\nfrom lfx.utils.schemas import ChatOutputResponse, DataOutputResponse\\nfrom lfx.utils.util import unescape_string\\n\\nif TYPE_CHECKING:\\n    from lfx.graph.edge.base import CycleEdge\\n    from lfx.graph.vertex.schema import NodeData\\n    from lfx.inputs.inputs import InputTypes\\n\\n\\nclass CustomComponentVertex(Vertex):\\n    def __init__(self, data: NodeData, graph):\\n        super().__init__(data, graph=graph, base_type=\\\"custom_components\\\")\\n\\n    def built_object_repr(self):\\n        if self.artifacts and \\\"repr\\\" in self.artifacts:\\n            return self.artifacts[\\\"repr\\\"] or super().built_object_repr()\\n        return None\\n\\n\\nclass ComponentVertex(Vertex):\\n    def __init__(self, data: NodeData, graph):\\n        super().__init__(data, graph=graph, base_type=\\\"component\\\")\\n\\n    def get_input(self, name: str) -> InputTypes:\\n        if self.custom_component is None:\\n            msg = f\\\"Vertex {self.id} does not have a component instance.\\\"\\n            raise ValueError(msg)\\n        return self.custom_component.get_input(name)\\n\\n    def get_output(self, name: str) -> Output:\\n        if self.custom_component is None:\\n            raise NoComponentInstanceError(self.id)\\n        return self.custom_component.get_output(name)\\n\\n    def built_object_repr(self):\\n        if self.artifacts and \\\"repr\\\" in self.artifacts:\\n            return self.artifacts[\\\"repr\\\"] or super().built_object_repr()\\n        return None\\n\\n    def _update_built_object_and_artifacts(self, result) -> None:\\n        \\\"\\\"\\\"Updates the built object and its artifacts.\\\"\\\"\\\"\\n        if isinstance(result, tuple):\\n            if len(result) == 2:  # noqa: PLR2004\\n                self.built_object, self.artifacts = result\\n            elif len(result) == 3:  # noqa: PLR2004\\n                self.custom_component, self.built_object, self.artifacts = result\\n                self.logs = self.custom_component.get_output_logs()\\n                for key in self.artifacts:\\n                    if self.artifacts_raw is None:\\n                        self.artifacts_raw = {}\\n                    self.artifacts_raw[key] = self.artifacts[key].get(\\\"raw\\\", None)\\n                    self.artifacts_type[key] = self.artifacts[key].get(\\\"type\\\", None) or ArtifactType.UNKNOWN.value\\n        else:\\n            self.built_object = result\\n\\n        for key, value in self.built_object.items():\\n            self.add_result(key, value)\\n\\n    def get_edge_with_target(self, target_id: str) -> Generator[CycleEdge]:\\n        \\\"\\\"\\\"Get the edge with the target id.\\n\\n        Args:\\n            target_id: The target id of the edge.\\n\\n        Returns:\\n            The edge with the target id.\\n        \\\"\\\"\\\"\\n        for edge in self.edges:\\n            if edge.target_id == target_id:\\n                yield edge\\n\\n    async def _get_result(self, requester: Vertex, target_handle_name: str | None = None) -> Any:\\n        \\\"\\\"\\\"Retrieves the result of the built component.\\n\\n        If the component has not been built yet, a ValueError is raised.\\n\\n        Returns:\\n            The built result if use_result is True, else the built object.\\n        \\\"\\\"\\\"\\n        if not self.built:\\n            # A downstream node pulling from a conditionally-excluded predecessor receives\\n            # that input's template default instead of triggering a build of the excluded\\n            # branch. ``target_handle_name`` is always set on this pull path (the requester\\n            # reads a named input handle); the ``None`` case falls through to the cycle-edge\\n            # default resolution below. Either way the excluded vertex is never built here --\\n            # ``is_vertex_runnable`` already returns False for it.\\n            if self.id in self.graph.conditionally_excluded_vertices and target_handle_name:\\n                return requester.get_value_from_template_dict(target_handle_name)\\n\\n            default_value: Any = UNDEFINED\\n            for edge in self.get_edge_with_target(requester.id):\\n                # We need to check if the edge is a normal edge\\n                if edge.is_cycle and edge.target_param:\\n                    if edge.target_param in requester.output_names:\\n                        default_value = None\\n                    else:\\n                        default_value = requester.get_value_from_template_dict(edge.target_param)\\n\\n            if default_value is not UNDEFINED:\\n                return default_value\\n            msg = f\\\"Component {self.display_name} has not been built yet\\\"\\n            raise ValueError(msg)\\n\\n        if requester is None:\\n            msg = \\\"Requester Vertex is None\\\"\\n            raise ValueError(msg)\\n\\n        edges = self.get_edge_with_target(requester.id)\\n        result = UNDEFINED\\n        for edge in edges:\\n            if (\\n                edge is not None\\n                and edge.source_handle.name in self.results\\n                and edge.target_handle.field_name == target_handle_name\\n            ):\\n                # Get the result from the output instead of the results dict\\n                try:\\n                    output = self.get_output(edge.source_handle.name)\\n\\n                    if output.value is UNDEFINED:\\n                        result = self.results[edge.source_handle.name]\\n                    else:\\n                        result = cast(\\\"Any\\\", output.value)\\n                except NoComponentInstanceError:\\n                    result = self.results[edge.source_handle.name]\\n                break\\n        if result is UNDEFINED:\\n            if edge is None:\\n                msg = f\\\"Edge not found between {self.display_name} and {requester.display_name}\\\"\\n                raise ValueError(msg)\\n            if edge.source_handle.name not in self.results:\\n                msg = f\\\"Result not found for {edge.source_handle.name}. Results: {self.results}\\\"\\n                raise ValueError(msg)\\n            msg = f\\\"Result not found for {edge.source_handle.name} in {edge}\\\"\\n            raise ValueError(msg)\\n        return result\\n\\n    def extract_messages_from_artifacts(self, artifacts: dict[str, Any]) -> list[dict]:\\n        \\\"\\\"\\\"Extracts messages from the artifacts.\\n\\n        Args:\\n            artifacts (Dict[str, Any]): The artifacts to extract messages from.\\n\\n        Returns:\\n            List[str]: The extracted messages.\\n        \\\"\\\"\\\"\\n        messages = []\\n        for key, artifact in artifacts.items():\\n            if any(\\n                k not in artifact for k in [\\\"text\\\", \\\"sender\\\", \\\"sender_name\\\", \\\"session_id\\\", \\\"stream_url\\\"]\\n            ) and not isinstance(artifact, Message):\\n                continue\\n            message_dict = artifact if isinstance(artifact, dict) else artifact.model_dump()\\n            if not message_dict.get(\\\"text\\\"):\\n                continue\\n            with contextlib.suppress(KeyError):\\n                messages.append(\\n                    ChatOutputResponse(\\n                        message=message_dict[\\\"text\\\"],\\n                        sender=message_dict.get(\\\"sender\\\"),\\n                        sender_name=message_dict.get(\\\"sender_name\\\"),\\n                        session_id=message_dict.get(\\\"session_id\\\"),\\n                        stream_url=message_dict.get(\\\"stream_url\\\"),\\n                        files=[\\n                            {\\\"path\\\": file} if isinstance(file, str) else file for file in message_dict.get(\\\"files\\\", [])\\n                        ],\\n                        component_id=self.id,\\n                        type=self.artifacts_type[key],\\n                    ).model_dump(exclude_none=True)\\n                )\\n        return messages\\n\\n    def finalize_build(self) -> None:\\n        result_dict = self.get_built_result()\\n        # We need to set the artifacts to pass information\\n        # to the frontend\\n        messages = self.extract_messages_from_artifacts(result_dict)\\n        token_usage = self._extract_token_usage()\\n        result_dict = ResultData(\\n            results=result_dict,\\n            artifacts=self.artifacts,\\n            outputs=self.outputs_logs,\\n            logs=self.logs,\\n            messages=messages,\\n            component_display_name=self.display_name,\\n            component_id=self.id,\\n            token_usage=token_usage,\\n        )\\n        self.set_result(result_dict)\\n\\n\\nclass InterfaceVertex(ComponentVertex):\\n    def __init__(self, data: NodeData, graph):\\n        super().__init__(data, graph=graph)\\n        self.added_message = None\\n        self.steps = [self._build, self._run]\\n        self.is_interface_component = True\\n\\n    def build_stream_url(self) -> str:\\n        return f\\\"/api/v1/build/{self.graph.flow_id}/{self.id}/stream\\\"\\n\\n    def built_object_repr(self):\\n        if self.task_id and self.is_task:\\n            if task := self.get_task():\\n                return str(task.info)\\n            return f\\\"Task {self.task_id} is not running\\\"\\n        if self.artifacts:\\n            # dump as a yaml string\\n            if isinstance(self.artifacts, dict):\\n                artifacts_ = [self.artifacts]\\n            elif hasattr(self.artifacts, \\\"data\\\"):\\n                artifacts_ = self.artifacts.data\\n            else:\\n                artifacts_ = self.artifacts\\n            artifacts = []\\n            for artifact in artifacts_:\\n                # artifacts = {k.title().replace(\\\"_\\\", \\\" \\\"): v for k, v in self.artifacts.items() if v is not None}\\n                artifact_ = {k.title().replace(\\\"_\\\", \\\" \\\"): v for k, v in artifact.items() if v is not None}\\n                artifacts.append(artifact_)\\n            return yaml.dump(artifacts, default_flow_style=False, allow_unicode=True)\\n        return super().built_object_repr()\\n\\n    def _process_chat_component(self):\\n        \\\"\\\"\\\"Process the chat component and return the message.\\n\\n        This method processes the chat component by extracting the necessary parameters\\n        such as sender, sender_name, and message from the `params` dictionary. It then\\n        performs additional operations based on the type of the `built_object` attribute.\\n        If `built_object` is an instance of `AIMessage`, it creates a `ChatOutputResponse`\\n        object using the `from_message` method. If `built_object` is not an instance of\\n        `UnbuiltObject`, it checks the type of `built_object` and performs specific\\n        operations accordingly. If `built_object` is a dictionary, it converts it into a\\n        code block. If `built_object` is an instance of `Data`, it assigns the `text`\\n        attribute to the `message` variable. If `message` is an instance of `AsyncIterator`\\n        or `Iterator`, it builds a stream URL and sets `message` to an empty string. If\\n        `built_object` is not a string, it converts it to a string. If `message` is a\\n        generator or iterator, it assigns it to the `message` variable. Finally, it creates\\n        a `ChatOutputResponse` object using the extracted parameters and assigns it to the\\n        `artifacts` attribute. If `artifacts` is not None, it calls the `model_dump` method\\n        on it and assigns the result to the `artifacts` attribute. It then returns the\\n        `message` variable.\\n\\n        Returns:\\n            str: The processed message.\\n        \\\"\\\"\\\"\\n        artifacts = None\\n        sender = self.params.get(\\\"sender\\\", None)\\n        sender_name = self.params.get(\\\"sender_name\\\", None)\\n        message = self.params.get(INPUT_FIELD_NAME, None)\\n        files = self.params.get(\\\"files\\\", [])\\n        treat_file_path = files is not None and not isinstance(files, list) and isinstance(files, str)\\n        if treat_file_path:\\n            self.params[\\\"files\\\"] = rewrite_file_path(files)\\n        files = [{\\\"path\\\": file} if isinstance(file, str) else file for file in self.params.get(\\\"files\\\", [])]\\n        if isinstance(message, str):\\n            message = unescape_string(message)\\n        stream_url = None\\n        if \\\"text\\\" in self.results:\\n            text_output = self.results[\\\"text\\\"]\\n        elif \\\"message\\\" in self.results:\\n            text_output = self.results[\\\"message\\\"].text\\n        else:\\n            text_output = message\\n        if isinstance(text_output, AIMessage | AIMessageChunk):\\n            artifacts = ChatOutputResponse.from_message(\\n                text_output,\\n                sender=sender,\\n                sender_name=sender_name,\\n            )\\n        elif not isinstance(text_output, UnbuiltObject):\\n            if isinstance(text_output, dict):\\n                # Turn the dict into a pleasing to\\n                # read JSON inside a code block\\n                message = dict_to_codeblock(text_output)\\n            elif isinstance(text_output, Data):\\n                message = text_output.text\\n            elif isinstance(message, AsyncIterator | Iterator):\\n                stream_url = self.build_stream_url()\\n                message = \\\"\\\"\\n                self.results[\\\"text\\\"] = message\\n                self.results[\\\"message\\\"].text = message\\n                self.built_object = self.results\\n            elif not isinstance(text_output, str):\\n                message = str(text_output)\\n            # if the message is a generator or iterator\\n            # it means that it is a stream of messages\\n\\n            else:\\n                message = text_output\\n\\n            if hasattr(sender_name, \\\"get_text\\\"):\\n                sender_name = sender_name.get_text()\\n\\n            artifact_type = ArtifactType.STREAM if stream_url is not None else ArtifactType.OBJECT\\n            artifacts = ChatOutputResponse(\\n                message=message,\\n                sender=sender,\\n                sender_name=sender_name,\\n                stream_url=stream_url,\\n                files=files,\\n                type=artifact_type,\\n            )\\n\\n            self.will_stream = stream_url is not None\\n        if artifacts:\\n            self.artifacts = artifacts.model_dump(exclude_none=True)\\n\\n        return message\\n\\n    def _process_data_component(self):\\n        \\\"\\\"\\\"Process the record component of the vertex.\\n\\n        If the built object is an instance of `Data`, it calls the `model_dump` method\\n        and assigns the result to the `artifacts` attribute.\\n\\n        If the built object is a list, it iterates over each element and checks if it is\\n        an instance of `Data`. If it is, it calls the `model_dump` method and appends\\n        the result to the `artifacts` list. If it is not, it raises a `ValueError` if the\\n        `ignore_errors` parameter is set to `False`, or logs an error message if it is set\\n        to `True`.\\n\\n        Returns:\\n            The built object.\\n\\n        Raises:\\n            ValueError: If an element in the list is not an instance of `Data` and\\n                `ignore_errors` is set to `False`.\\n        \\\"\\\"\\\"\\n        if isinstance(self.built_object, Data):\\n            artifacts = [self.built_object.data]\\n        elif isinstance(self.built_object, list):\\n            artifacts = []\\n            ignore_errors = self.params.get(\\\"ignore_errors\\\", False)\\n            for value in self.built_object:\\n                if isinstance(value, Data):\\n                    artifacts.append(value.data)\\n                elif ignore_errors:\\n                    logger.error(f\\\"Data expected, but got {value} of type {type(value)}\\\")\\n                else:\\n                    msg = f\\\"Data expected, but got {value} of type {type(value)}\\\"\\n                    raise ValueError(msg)\\n        self.artifacts = DataOutputResponse(data=artifacts)\\n        return self.built_object\\n\\n    async def _run(self, *args, **kwargs) -> None:  # noqa: ARG002\\n        if self.vertex_type in CHAT_COMPONENTS:\\n            message = self._process_chat_component()\\n        elif self.vertex_type in RECORDS_COMPONENTS:\\n            message = self._process_data_component()\\n        if isinstance(self.built_object, AsyncIterator | Iterator):\\n            if self.params.get(\\\"return_data\\\", False):\\n                self.built_object = Data(text=message, data=self.artifacts)\\n            else:\\n                self.built_object = message\\n        self.built_result = self.built_object\\n\\n    async def stream(self):\\n        iterator = self.params.get(INPUT_FIELD_NAME, None)\\n        if not isinstance(iterator, AsyncIterator | Iterator):\\n            msg = \\\"The message must be an iterator or an async iterator.\\\"\\n            raise TypeError(msg)\\n        is_async = isinstance(iterator, AsyncIterator)\\n        complete_message = \\\"\\\"\\n        if is_async:\\n            async for message in iterator:\\n                message_ = message.content if hasattr(message, \\\"content\\\") else message\\n                message_ = message_.text if hasattr(message_, \\\"text\\\") else message_\\n                yield message_\\n                complete_message += message_\\n        else:\\n            for message in iterator:\\n                message_ = message.content if hasattr(message, \\\"content\\\") else message\\n                message_ = message_.text if hasattr(message_, \\\"text\\\") else message_\\n                yield message_\\n                complete_message += message_\\n\\n        files = self.params.get(\\\"files\\\", [])\\n\\n        treat_file_path = files is not None and not isinstance(files, list) and isinstance(files, str)\\n        if treat_file_path:\\n            self.params[\\\"files\\\"] = rewrite_file_path(files)\\n\\n        if hasattr(self.params.get(\\\"sender_name\\\"), \\\"get_text\\\"):\\n            sender_name = self.params.get(\\\"sender_name\\\").get_text()\\n        else:\\n            sender_name = self.params.get(\\\"sender_name\\\")\\n        self.artifacts = ChatOutputResponse(\\n            message=complete_message,\\n            sender=self.params.get(\\\"sender\\\", \\\"\\\"),\\n            sender_name=sender_name,\\n            files=[{\\\"path\\\": file} if isinstance(file, str) else file for file in self.params.get(\\\"files\\\", [])],\\n            type=ArtifactType.OBJECT.value,\\n        ).model_dump()\\n\\n        message = await Message.create(\\n            text=complete_message,\\n            sender=self.params.get(\\\"sender\\\", \\\"\\\"),\\n            sender_name=self.params.get(\\\"sender_name\\\", \\\"\\\"),\\n            files=self.params.get(\\\"files\\\", []),\\n            flow_id=self.graph.flow_id,\\n            session_id=self.params.get(\\\"session_id\\\", \\\"\\\"),\\n        )\\n        self.params[INPUT_FIELD_NAME] = complete_message\\n        if isinstance(self.built_object, dict):\\n            for key, value in self.built_object.items():\\n                if hasattr(value, \\\"text_stream\\\") and (value.text_stream is not None or value.text == \\\"\\\"):\\n                    self.built_object[key] = message\\n        else:\\n            self.built_object = message\\n            self.artifacts_type = ArtifactType.MESSAGE\\n\\n        # Update artifacts with the message\\n        # and remove the stream_url\\n        self.finalize_build()\\n        await logger.adebug(f\\\"Streamed message: {complete_message}\\\")\\n        # Set the result in the vertex of origin\\n        edges = self.get_edge_with_target(self.id)\\n        for edge in edges:\\n            origin_vertex = self.graph.get_vertex(edge.source_id)\\n            for key, value in origin_vertex.results.items():\\n                if isinstance(value, AsyncIterator | Iterator):\\n                    origin_vertex.results[key] = complete_message\\n        if (\\n            self.custom_component\\n            and hasattr(self.custom_component, \\\"should_store_message\\\")\\n            and hasattr(self.custom_component, \\\"store_message\\\")\\n        ):\\n            await self.custom_component.store_message(message)\\n        await log_vertex_build(\\n            flow_id=self.graph.flow_id,\\n            vertex_id=self.id,\\n            valid=True,\\n            params=self.built_object_repr(),\\n            data=self.result,\\n            artifacts=self.artifacts,\\n        )\\n\\n        self._validate_built_object()\\n        self.built = True\\n\\n    async def consume_async_generator(self) -> None:\\n        async for _ in self.stream():\\n            pass\\n\\n    def _is_chat_input(self):\\n        return self.vertex_type == InterfaceComponentTypes.ChatInput and self.is_input\\n\\n\\nclass StateVertex(ComponentVertex):\\n    def __init__(self, data: NodeData, graph):\\n        \\\"\\\"\\\"Initializes a StateVertex with the provided node data and graph.\\n\\n        Sets up the build steps and marks the vertex as a state vertex.\\n        \\\"\\\"\\\"\\n        super().__init__(data, graph=graph)\\n        self.steps = [self._build]\\n        self.is_state = True\\n\\n    def built_object_repr(self):\\n        \\\"\\\"\\\"Returns a string representation of the built object from the artifacts if available.\\n\\n        If the artifacts dictionary contains a non-empty \\\"repr\\\" key, its value is returned.\\n        If the \\\"repr\\\" value is falsy, falls back to the superclass representation.\\n        Returns None if no representation is available.\\n        \\\"\\\"\\\"\\n        if self.artifacts and \\\"repr\\\" in self.artifacts:\\n            return self.artifacts[\\\"repr\\\"] or super().built_object_repr()\\n        return None\\n\\n\\ndef dict_to_codeblock(d: dict) -> str:\\n    serialized = {key: serialize(val) for key, val in d.items()}\\n    json_str = json.dumps(serialized, indent=4)\\n    return f\\\"```json\\\\n{json_str}\\\\n```\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/helpers/flow.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a25d51d3ef1429dff786d7da3b2489695e93ffba5a85459c53ddb7dd93471c5b\",\"content\":\"\\\"\\\"\\\"Flow helper functions for lfx package.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\nfrom uuid import UUID\\n\\nfrom pydantic import BaseModel, Field, create_model\\n\\nfrom lfx.log.logger import logger\\nfrom lfx.schema.schema import INPUT_FIELD_NAME\\n\\nif TYPE_CHECKING:\\n    from lfx.graph.graph.base import Graph\\n    from lfx.graph.schema import RunOutputs\\n    from lfx.graph.vertex.base import Vertex\\n    from lfx.schema.data import Data\\n\\n\\ndef get_flow_inputs(graph: Graph) -> list[Vertex]:\\n    \\\"\\\"\\\"Retrieves the flow inputs from the given graph.\\n\\n    Args:\\n        graph (Graph): The graph object representing the flow.\\n\\n    Returns:\\n        List[Vertex]: A list of input vertices.\\n    \\\"\\\"\\\"\\n    return [vertex for vertex in graph.vertices if vertex.is_input]\\n\\n\\ndef build_schema_from_inputs(name: str, inputs: list[Vertex]) -> type[BaseModel]:\\n    \\\"\\\"\\\"Builds a schema from the given inputs.\\n\\n    Args:\\n        name (str): The name of the schema.\\n        inputs (List[Vertex]): A list of Vertex objects representing the inputs.\\n\\n    Returns:\\n        BaseModel: The schema model.\\n    \\\"\\\"\\\"\\n    fields = {}\\n    for input_ in inputs:\\n        field_name = input_.display_name.lower().replace(\\\" \\\", \\\"_\\\")\\n        description = input_.description\\n        fields[field_name] = (str, Field(default=\\\"\\\", description=description))\\n    return create_model(name, **fields)\\n\\n\\ndef get_arg_names(inputs: list[Vertex]) -> list[dict[str, str]]:\\n    \\\"\\\"\\\"Returns a list of dictionaries containing the component name and its corresponding argument name.\\n\\n    Args:\\n        inputs (List[Vertex]): A list of Vertex objects representing the inputs.\\n\\n    Returns:\\n        List[dict[str, str]]: A list of dictionaries, where each dictionary contains the component name and its\\n            argument name.\\n    \\\"\\\"\\\"\\n    return [\\n        {\\\"component_name\\\": input_.display_name, \\\"arg_name\\\": input_.display_name.lower().replace(\\\" \\\", \\\"_\\\")}\\n        for input_ in inputs\\n    ]\\n\\n\\nasync def list_flows(*, user_id: str | None = None) -> list[Data]:\\n    \\\"\\\"\\\"List flows for a user.\\n\\n    In lfx, this is a stub that returns an empty list since we don't have\\n    a database backend by default.\\n\\n    Args:\\n        user_id: The user ID to list flows for.\\n\\n    Returns:\\n        List of flow data objects.\\n    \\\"\\\"\\\"\\n    if not user_id:\\n        msg = \\\"Session is invalid\\\"\\n        raise ValueError(msg)\\n\\n    # In lfx, we don't have a database backend by default\\n    # This is a stub implementation\\n    logger.warning(\\\"list_flows called but lfx doesn't have database backend by default\\\")\\n    return []\\n\\n\\nasync def list_flows_by_flow_folder(\\n    *,\\n    user_id: str | None = None,\\n    flow_id: str | None = None,\\n    order_params: dict | None = {\\\"column\\\": \\\"updated_at\\\", \\\"direction\\\": \\\"desc\\\"},  # noqa: B006, ARG001\\n) -> list[Data]:\\n    \\\"\\\"\\\"Lists flows for the given user and in the same folder as the specified flow.\\n\\n    Retrieves all flows belonging to the given user and identified by user_id\\n    that belong to the same folder as the flow identified by flow_id if the flow belongs to the user.\\n\\n    Optionally accepts a dictionary of order parameters\\n    to order the flows by the specified column and direction.\\n    Default order column is \\\"updated_at\\\" and default order direction is \\\"desc\\\".\\n\\n    In lfx, this is a stub that returns an empty list since we don't have\\n    a database backend by default.\\n\\n    Args:\\n        user_id (str | None, optional): The user ID to list flows for. Defaults to None.\\n        flow_id (str | None, optional): The flow ID to list flows in the same folder as. Defaults to None.\\n        order_params (dict | None, optional): Parameters for ordering the flows.\\n        Defaults to {\\\"column\\\": \\\"updated_at\\\", \\\"direction\\\": \\\"desc\\\"}.\\n            - column: The column to order by. Defaults to \\\"updated_at\\\".\\n            - direction: The direction to order by. Defaults to \\\"desc\\\".\\n\\n    Returns:\\n        list[Data]: List of flows in the same folder as the flow identified by flow_id.\\n\\n    Raises:\\n        ValueError: If user_id is not provided.\\n        ValueError: If Flow ID is not provided.\\n    \\\"\\\"\\\"\\n    return await _list_flows_in_flow_folder(user_id=user_id, flow_id=flow_id, a2a_only=False)\\n\\n\\nasync def _list_flows_in_flow_folder(*, user_id: str | None, flow_id: str | None, a2a_only: bool) -> list[Data]:\\n    \\\"\\\"\\\"Stub mirror of ``langflow.helpers.flow._list_flows_in_flow_folder``.\\n\\n    Validates its arguments the same way the real implementation does, then no-ops: in lfx\\n    we don't have a database backend by default, so there are no flows to list.\\n    \\\"\\\"\\\"\\n    if not user_id:\\n        msg = \\\"Session is invalid\\\"\\n        raise ValueError(msg)\\n    if not flow_id:\\n        msg = \\\"Flow ID is required\\\"\\n        raise ValueError(msg)\\n\\n    caller = \\\"list_a2a_agents_by_flow_folder\\\" if a2a_only else \\\"list_flows_by_flow_folder\\\"\\n    msg = f\\\"{caller} called but lfx doesn't have database backend by default\\\"\\n    logger.warning(msg)\\n    return []\\n\\n\\nasync def list_a2a_agents_by_flow_folder(\\n    *,\\n    user_id: str | None = None,\\n    flow_id: str | None = None,\\n    order_params: dict | None = {\\\"column\\\": \\\"updated_at\\\", \\\"direction\\\": \\\"desc\\\"},  # noqa: B006, ARG001\\n) -> list[Data]:\\n    \\\"\\\"\\\"Stub: lfx has no database backend, so there are no A2A agents to list.\\n\\n    The real implementation lives in ``langflow.helpers.flow`` and filters flows on\\n    ``a2a_enabled``. See :func:`list_flows_by_flow_folder` for the same lfx/langflow split.\\n    \\\"\\\"\\\"\\n    return await _list_flows_in_flow_folder(user_id=user_id, flow_id=flow_id, a2a_only=True)\\n\\n\\nasync def list_flows_by_folder_id(\\n    *,\\n    user_id: str | None = None,\\n    folder_id: str | None = None,\\n) -> list[Data]:\\n    \\\"\\\"\\\"Lists flows for the given user and in the same folder as the specified folder.\\n\\n    Retrieves all flows belonging to the user identified by user_id\\n    that belong to the same folder as the folder identified by folder_id\\n    if the folder belongs to the user.\\n\\n    In lfx, this is a stub that returns an empty list since we don't have\\n    a database backend by default.\\n\\n    Args:\\n        user_id (str | None, optional): The user ID to list flows for. Defaults to None.\\n        folder_id (str | None, optional): The folder ID to list flows in the same folder as. Defaults to None.\\n\\n    Returns:\\n        list[Data]: List of flows in the same folder as the folder identified by folder_id.\\n\\n    Raises:\\n        ValueError: If user_id is not provided.\\n        ValueError: If Folder ID is not provided.\\n    \\\"\\\"\\\"\\n    if not user_id:\\n        msg = \\\"Session is invalid\\\"\\n        raise ValueError(msg)\\n    if not folder_id:\\n        msg = \\\"Folder ID is required\\\"\\n        raise ValueError(msg)\\n\\n    # In lfx, we don't have a database backend by default\\n    # This is a stub implementation\\n    logger.warning(\\\"list_flows_by_folder_id called but lfx doesn't have database backend by default\\\")\\n    return []\\n\\n\\nasync def get_flow_by_id_or_name(\\n    user_id: str,\\n    flow_id: str | None = None,\\n    flow_name: str | None = None,\\n) -> Data | None:\\n    \\\"\\\"\\\"Get a flow by ID or name.\\n\\n    Retrieves a flow by ID or name. If both are provided, flow_id is used.\\n\\n    In lfx, this is a stub that returns None since we don't have\\n    a database backend by default.\\n\\n    Args:\\n        user_id (str): The user ID to get the flow for.\\n        flow_id (str | None, optional): The flow ID. Defaults to None.\\n        flow_name (str | None, optional): The flow name. Defaults to None.\\n\\n    Returns:\\n        Data | None: The flow data or None if not found.\\n    \\\"\\\"\\\"\\n    if not user_id:\\n        msg = \\\"Session is invalid\\\"\\n        raise ValueError(msg)\\n    if not (flow_id or flow_name):\\n        msg = \\\"Flow ID or Flow Name is required\\\"\\n        raise ValueError(msg)\\n\\n    # In lfx, we don't have a database backend by default\\n    # This is a stub implementation\\n    logger.warning(\\\"get_flow_by_id_or_name called but lfx doesn't have database backend by default\\\")\\n    return None\\n\\n\\nasync def load_flow(\\n    user_id: str,  # noqa: ARG001\\n    flow_id: str | None = None,\\n    flow_name: str | None = None,\\n    tweaks: dict | None = None,  # noqa: ARG001\\n) -> Graph:\\n    \\\"\\\"\\\"Load a flow by ID or name.\\n\\n    In lfx, this is a stub that raises an error since we don't have\\n    a database backend by default.\\n\\n    Args:\\n        user_id: The user ID.\\n        flow_id: The flow ID to load.\\n        flow_name: The flow name to load.\\n        tweaks: Optional tweaks to apply to the flow.\\n\\n    Returns:\\n        The loaded flow graph.\\n    \\\"\\\"\\\"\\n    if not flow_id and not flow_name:\\n        msg = \\\"Flow ID or Flow Name is required\\\"\\n        raise ValueError(msg)\\n\\n    # In lfx, we don't have a database backend by default\\n    # This is a stub implementation\\n    msg = f\\\"load_flow not implemented in lfx - cannot load flow {flow_id or flow_name}\\\"\\n    raise NotImplementedError(msg)\\n\\n\\nasync def run_flow(\\n    inputs: dict | list[dict] | None = None,\\n    tweaks: dict | None = None,  # noqa: ARG001\\n    flow_id: str | None = None,  # noqa: ARG001\\n    flow_name: str | None = None,  # noqa: ARG001\\n    output_type: str | None = \\\"chat\\\",\\n    user_id: str | None = None,\\n    run_id: str | None = None,\\n    session_id: str | None = None,\\n    graph: Graph | None = None,\\n) -> list[RunOutputs]:\\n    \\\"\\\"\\\"Run a flow with given inputs.\\n\\n    Args:\\n        inputs: Input values for the flow.\\n        tweaks: Optional tweaks to apply.\\n        flow_id: The flow ID to run.\\n        flow_name: The flow name to run.\\n        output_type: The type of output to return.\\n        user_id: The user ID.\\n        run_id: Optional run ID.\\n        session_id: Optional session ID.\\n        graph: Optional pre-loaded graph.\\n\\n    Returns:\\n        List of run outputs.\\n    \\\"\\\"\\\"\\n    if user_id is None:\\n        msg = \\\"Session is invalid\\\"\\n        raise ValueError(msg)\\n\\n    if graph is None:\\n        # In lfx, we can't load flows from database\\n        msg = \\\"run_flow requires a graph parameter in lfx\\\"\\n        raise ValueError(msg)\\n\\n    if run_id:\\n        graph.set_run_id(UUID(run_id))\\n    if session_id:\\n        graph.session_id = session_id\\n    if user_id:\\n        graph.user_id = user_id\\n\\n    if inputs is None:\\n        inputs = []\\n    if isinstance(inputs, dict):\\n        inputs = [inputs]\\n\\n    inputs_list = []\\n    inputs_components = []\\n    types = []\\n\\n    for input_dict in inputs:\\n        inputs_list.append({INPUT_FIELD_NAME: input_dict.get(\\\"input_value\\\", \\\"\\\")})\\n        inputs_components.append(input_dict.get(\\\"components\\\", []))\\n        types.append(input_dict.get(\\\"type\\\", \\\"chat\\\"))\\n\\n    outputs = [\\n        vertex.id\\n        for vertex in graph.vertices\\n        if output_type == \\\"debug\\\"\\n        or (vertex.is_output and (output_type == \\\"any\\\" or (output_type and output_type in str(vertex.id).lower())))\\n    ]\\n\\n    # In lfx, we don't have settings service, so use False as default\\n    fallback_to_env_vars = False\\n\\n    from lfx.run.hitl import raise_if_nested_hitl_unsupported\\n\\n    # A nested run cannot pause: a Human Input in here would silently not pause. Fail loud instead.\\n    raise_if_nested_hitl_unsupported(graph)\\n\\n    return await graph.arun(\\n        inputs_list,\\n        outputs=outputs,\\n        inputs_components=inputs_components,\\n        types=types,\\n        fallback_to_env_vars=fallback_to_env_vars,\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/mcp/flow_builder_tools/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"65ad7e5f543ba5cab2fd543038e0d68596fabdcd45e239b1dc5dc92656d153ee\",\"content\":\"\\\"\\\"\\\"Tools for searching components and building flows on the user's canvas.\\n\\nThese components expose flow_builder capabilities as Agent tools.\\nEach mutating tool pushes a flow_update event to a per-request queue\\nso the assistant service can send real-time SSE updates to the frontend.\\n\\nThis module is a thin re-export surface: the implementation lives in\\nresponsibility-scoped submodules.\\n\\n  - ``_state``      \u2014 per-request working-flow + emit + drain + lifecycle\\n                       (plus the tiny ``_find_node`` / ``_readable_preview``\\n                       node-shape utilities every tool layer needs)\\n  - ``read_tools``  \u2014 Search / Describe / GetFieldValue / DescribeFlowIO\\n                       (pure reads, no events)\\n  - ``edit_tools``  \u2014 ProposeFieldEdit (validated, user-reviewable)\\n  - ``mutate_tools``\u2014 Add / Remove / Connect / Configure (push events)\\n  - ``run_tools``   \u2014 Propose / Build / Run / Generate\\n                       (orchestration + run helpers)\\n  - ``template_tools`` \u2014 ListTemplates / UseTemplate (starter projects,\\n                       proposed via the same ``set_flow`` gate)\\n\\nImporting from ``lfx.mcp.flow_builder_tools`` keeps the original public\\nsurface \u2014 every prior caller's ``from lfx.mcp.flow_builder_tools import X``\\ncontinues to resolve unchanged.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\n# Per-request state + small shared utilities. Re-exported so the public\\n# surface of ``lfx.mcp.flow_builder_tools`` is unchanged.\\nfrom ._state import _emit as _emit\\nfrom ._state import _ensure_working_flow as _ensure_working_flow\\nfrom ._state import _find_node as _find_node\\nfrom ._state import _load_registry_user_aware as _load_registry_user_aware\\nfrom ._state import _readable_preview as _readable_preview\\nfrom ._state import (\\n    drain_flow_events,\\n    emit_tool_start,\\n    get_working_flow,\\n    init_working_flow,\\n    isolate_flow_run_context,\\n    node_existed_at_start,\\n    reset_working_flow,\\n    set_apply_edits_live,\\n    set_propose_existing_edits,\\n    set_tool_start_listener,\\n    should_apply_edits_live,\\n    should_propose_existing_edits,\\n)\\nfrom .edit_tools import ProposeFieldEdit\\nfrom .mutate_tools import (\\n    AddComponent,\\n    ConfigureComponent,\\n    ConnectComponents,\\n    RemoveComponent,\\n)\\nfrom .read_tools import (\\n    DescribeComponentType,\\n    DescribeFlowIO,\\n    GetFieldValue,\\n    SearchComponentTypes,\\n)\\nfrom .run_tools import (\\n    BuildFlowFromSpec,\\n    GenerateComponent,\\n    ProposePlan,\\n    RunFlow,\\n)\\nfrom .template_tools import ListTemplates, UseTemplate\\n\\n__all__ = [\\n    \\\"AddComponent\\\",\\n    \\\"BuildFlowFromSpec\\\",\\n    \\\"ConfigureComponent\\\",\\n    \\\"ConnectComponents\\\",\\n    \\\"DescribeComponentType\\\",\\n    \\\"DescribeFlowIO\\\",\\n    \\\"GenerateComponent\\\",\\n    \\\"GetFieldValue\\\",\\n    \\\"ListTemplates\\\",\\n    \\\"ProposeFieldEdit\\\",\\n    \\\"ProposePlan\\\",\\n    \\\"RemoveComponent\\\",\\n    \\\"RunFlow\\\",\\n    \\\"SearchComponentTypes\\\",\\n    \\\"UseTemplate\\\",\\n    \\\"drain_flow_events\\\",\\n    \\\"emit_tool_start\\\",\\n    \\\"get_working_flow\\\",\\n    \\\"init_working_flow\\\",\\n    \\\"isolate_flow_run_context\\\",\\n    \\\"node_existed_at_start\\\",\\n    \\\"reset_working_flow\\\",\\n    \\\"set_apply_edits_live\\\",\\n    \\\"set_propose_existing_edits\\\",\\n    \\\"set_tool_start_listener\\\",\\n    \\\"should_apply_edits_live\\\",\\n    \\\"should_propose_existing_edits\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/mcp/flow_builder_tools/_state.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cacfda528d7f6f6fd3d9c20f94032df0fafcb9c5edf8710f20230fc5356c73df\",\"content\":\"\\\"\\\"\\\"Per-request state for the flow-builder tool surface.\\n\\nOwns the asyncio-task-local working flow + flow id + event queue, plus the\\n``_emit`` push that mutating tools use to surface ``flow_update`` events to\\nthe assistant service. Each async request gets its own values via\\n``ContextVar`` \u2014 safe under concurrency.\\n\\nAlso exposes the small node-shape utilities ``_find_node`` and\\n``_readable_preview`` that every tool layer needs; co-located here so no\\n\\\"generic helpers\\\" file is required.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom collections import deque\\nfrom contextvars import ContextVar\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom lfx.graph.flow_builder.builder import load_local_registry\\nfrom lfx.graph.flow_builder.flow import empty_flow\\nfrom lfx.log.logger import logger\\nfrom lfx.services.deps import get_catalog_policy_service\\nfrom lfx.utils.component_aliases import build_component_identity_index\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Callable\\n\\n\\ndef _filter_registry_by_catalog_policy(registry: dict[str, dict]) -> dict[str, dict]:\\n    \\\"\\\"\\\"Return a request-local registry without catalog-blocked components.\\\"\\\"\\\"\\n    blocked_component_keys = get_catalog_policy_service().snapshot.blocked_component_keys\\n    if not blocked_component_keys:\\n        return registry\\n\\n    identity_index = build_component_identity_index({\\\"components\\\": registry})\\n    blocked_identities = identity_index.resolve_many(blocked_component_keys)\\n    return {\\n        component_type: entry\\n        for component_type, entry in registry.items()\\n        if identity_index.resolve(component_type).isdisjoint(blocked_identities)\\n    }\\n\\n\\ndef _load_registry_user_aware() -> dict[str, dict]:\\n    \\\"\\\"\\\"Return the base registry merged with the calling user's overlay.\\n\\n    Tries the langflow-side overlay (which reads the current_user_id\\n    ContextVar and walks ``<sandbox>/.components/*.py`` for that user).\\n    Falls back to the bare base registry when:\\n        - the langflow package isn't installed alongside lfx (e.g., the\\n          MCP server is running standalone),\\n        - no user is bound to the context.\\n\\n    Keeps the lfx package free of a hard dependency on the langflow\\n    code path while letting the agent's tools see user-registered\\n    Components when both packages are co-installed.\\n    \\\"\\\"\\\"\\n    try:\\n        from langflow.agentic.services.user_components_overlay import (\\n            load_registry_for_current_user,\\n        )\\n    except ImportError:\\n        registry = load_local_registry()\\n    else:\\n        registry = load_registry_for_current_user()\\n    return _filter_registry_by_catalog_policy(registry)\\n\\n\\n_flow_events_var: ContextVar[deque[dict[str, Any]]] = ContextVar(\\\"_flow_events_var\\\")\\n_working_flow_var: ContextVar[dict | None] = ContextVar(\\\"_working_flow_var\\\", default=None)\\n_current_flow_id_var: ContextVar[str | None] = ContextVar(\\\"_current_flow_id_var\\\", default=None)\\n# Canvas component IDs at the START of the turn (set by init_working_flow) so a\\n# pre-existing component (EDIT target) is distinguishable from one added this turn.\\n_initial_node_ids_var: ContextVar[frozenset[str]] = ContextVar(\\\"_initial_node_ids_var\\\", default=frozenset())\\n# When True, configure_component on a PRE-EXISTING component becomes a reviewable\\n# edit_field proposal (pure-edit turns); default False keeps every other path live.\\n_propose_existing_edits_var: ContextVar[bool] = ContextVar(\\\"_propose_existing_edits_var\\\", default=False)\\n# Headless MCP has no UI to apply a reviewable proposal, so the propose tools\\n# apply live and narrate it as done. Default False keeps UI review cards.\\n_apply_edits_live_var: ContextVar[bool] = ContextVar(\\\"_apply_edits_live_var\\\", default=False)\\n# Live \\\"tool started\\\" callback installed by the streaming executor; None means\\n# no consumer (headless MCP, nested runs) and emits are silent no-ops.\\n_tool_start_listener_var: ContextVar[Callable[[dict[str, Any]], None] | None] = ContextVar(\\n    \\\"_tool_start_listener_var\\\", default=None\\n)\\n\\n\\ndef _collect_node_ids(flow_data: dict | None) -> frozenset[str]:\\n    \\\"\\\"\\\"Return the set of component IDs in a flow dict (data.id or top-level id).\\\"\\\"\\\"\\n    nodes = ((flow_data or {}).get(\\\"data\\\") or {}).get(\\\"nodes\\\") or []\\n    ids: set[str] = set()\\n    for node in nodes:\\n        if not isinstance(node, dict):\\n            continue\\n        nid = (node.get(\\\"data\\\") or {}).get(\\\"id\\\") or node.get(\\\"id\\\")\\n        if isinstance(nid, str) and nid:\\n            ids.add(nid)\\n    return frozenset(ids)\\n\\n\\ndef node_existed_at_start(component_id: str) -> bool:\\n    \\\"\\\"\\\"True if the component was already on the canvas when the turn began.\\\"\\\"\\\"\\n    return component_id in _initial_node_ids_var.get(frozenset())\\n\\n\\ndef set_propose_existing_edits(*, enabled: bool) -> None:\\n    \\\"\\\"\\\"Enable/disable converting configure\u2192propose for pre-existing components.\\\"\\\"\\\"\\n    _propose_existing_edits_var.set(enabled)\\n\\n\\ndef should_propose_existing_edits() -> bool:\\n    \\\"\\\"\\\"Whether edits to pre-existing components should surface as review cards.\\\"\\\"\\\"\\n    return _propose_existing_edits_var.get(False)\\n\\n\\ndef set_apply_edits_live(*, enabled: bool) -> None:\\n    \\\"\\\"\\\"Enable/disable applying proposed edits live (headless callers with no review UI).\\\"\\\"\\\"\\n    _apply_edits_live_var.set(enabled)\\n\\n\\ndef should_apply_edits_live() -> bool:\\n    \\\"\\\"\\\"Whether proposed edits should be applied live instead of surfaced for review.\\\"\\\"\\\"\\n    return _apply_edits_live_var.get(False)\\n\\n\\ndef _get_flow_events() -> deque[dict[str, Any]]:\\n    \\\"\\\"\\\"Get the per-request event queue, creating one if needed.\\\"\\\"\\\"\\n    try:\\n        return _flow_events_var.get()\\n    except LookupError:\\n        q: deque[dict[str, Any]] = deque()\\n        _flow_events_var.set(q)\\n        return q\\n\\n\\ndef drain_flow_events() -> list[dict[str, Any]]:\\n    \\\"\\\"\\\"Return and clear all pending flow update events.\\\"\\\"\\\"\\n    q = _get_flow_events()\\n    events = list(q)\\n    q.clear()\\n    return events\\n\\n\\ndef get_working_flow() -> dict | None:\\n    \\\"\\\"\\\"Return the current working flow (for the assistant service).\\\"\\\"\\\"\\n    return _working_flow_var.get(None)\\n\\n\\ndef init_working_flow(flow_data: dict, flow_id: str | None = None) -> None:\\n    \\\"\\\"\\\"Initialize working flow from actual canvas data.\\\"\\\"\\\"\\n    _working_flow_var.set(flow_data)\\n    _current_flow_id_var.set(flow_id)\\n    # Snapshot which components already existed so edits to them can later be\\n    # told apart from components added during this turn.\\n    _initial_node_ids_var.set(_collect_node_ids(flow_data))\\n    _get_flow_events().clear()\\n\\n\\ndef reset_working_flow() -> None:\\n    \\\"\\\"\\\"Reset the working flow state between requests.\\\"\\\"\\\"\\n    _working_flow_var.set(None)\\n    _current_flow_id_var.set(None)\\n    _initial_node_ids_var.set(frozenset())\\n    _propose_existing_edits_var.set(False)\\n    _apply_edits_live_var.set(False)\\n    _get_flow_events().clear()\\n\\n\\ndef isolate_flow_run_context() -> None:\\n    \\\"\\\"\\\"Rebind the per-run flow ContextVars to FRESH values.\\n\\n    For a NESTED pipeline run (``GenerateComponent`` re-entering\\n    ``execute_flow_with_validation`` mid agent-loop), the parent loop's\\n    canvas/events must be invisible and untouchable. Unlike\\n    ``reset_working_flow()`` \u2014 which ``.clear()``s the event deque that a\\n    child context inherited *by reference* from the parent \u2014 this installs\\n    a brand-new deque, so the nested run can neither drain the parent's\\n    queued events nor wipe the parent's working flow.\\n    \\\"\\\"\\\"\\n    _flow_events_var.set(deque())\\n    _working_flow_var.set(None)\\n    _current_flow_id_var.set(None)\\n    # A nested pipeline run must not inherit the parent turn's edit-review mode\\n    # nor its initial-node snapshot \u2014 those belong to the parent canvas only.\\n    _initial_node_ids_var.set(frozenset())\\n    _propose_existing_edits_var.set(False)\\n    _apply_edits_live_var.set(False)\\n    _tool_start_listener_var.set(None)\\n\\n\\ndef _emit(action: str, **data: Any) -> None:\\n    \\\"\\\"\\\"Push a flow_update event.\\\"\\\"\\\"\\n    _get_flow_events().append({\\\"action\\\": action, **data})\\n\\n\\ndef set_tool_start_listener(listener: Callable[[dict[str, Any]], None] | None) -> None:\\n    \\\"\\\"\\\"Install (or clear) the per-context live tool-start callback.\\n\\n    The streaming executor installs a listener that forwards payloads onto its\\n    event queue so the SSE consumer sees \\\"tool started\\\" WHILE the tool runs \u2014\\n    unlike ``_emit``, whose deque is only drained between LLM tokens.\\n    \\\"\\\"\\\"\\n    _tool_start_listener_var.set(listener)\\n\\n\\ndef emit_tool_start(tool: str, **data: Any) -> None:\\n    \\\"\\\"\\\"Announce that a canvas-mutating tool began executing.\\n\\n    Silent no-op when no listener is installed (headless MCP, nested runs).\\n    Listener failures are swallowed: a UI indicator must never break the tool.\\n    \\\"\\\"\\\"\\n    listener = _tool_start_listener_var.get()\\n    if listener is None:\\n        return\\n    try:\\n        listener({\\\"tool\\\": tool, **data})\\n    except Exception:  # noqa: BLE001\\n        logger.debug(\\\"tool_start listener failed for tool=%s\\\", tool)\\n\\n\\ndef _ensure_working_flow() -> dict:\\n    \\\"\\\"\\\"Get or create the working flow.\\\"\\\"\\\"\\n    flow = _working_flow_var.get(None)\\n    if flow is None:\\n        flow = empty_flow()\\n        _working_flow_var.set(flow)\\n    return flow\\n\\n\\ndef _find_node(flow: dict, component_id: str) -> dict | None:\\n    \\\"\\\"\\\"Find a node in the flow by component ID.\\\"\\\"\\\"\\n    for node in flow.get(\\\"data\\\", {}).get(\\\"nodes\\\", []):\\n        nid = node.get(\\\"data\\\", {}).get(\\\"id\\\", node.get(\\\"id\\\", \\\"\\\"))\\n        if nid == component_id:\\n            return node\\n    return None\\n\\n\\ndef _readable_preview(value: Any, limit: int = 120) -> str:\\n    r\\\"\\\"\\\"One-line, human-readable rendering of a field value for a summary.\\n\\n    The full value is carried separately (``new_value``/the patch) for the\\n    diff body \u2014 this is only the short headline. Uses ``repr()``-free\\n    formatting (no surrounding quotes, no escaped ``\\\\n``) and collapses all\\n    whitespace so a multi-line system prompt doesn't blow up the card.\\n    \\\"\\\"\\\"\\n    text = value if isinstance(value, str) else str(value)\\n    # Collapse real control chars AND their two-char escape sequences (\\\"\\\\\\\\n\\\" etc.)\\n    # \u2014 LLMs emit either, and the card must never show a literal backslash-n.\\n    for esc in (\\\"\\\\\\\\n\\\", \\\"\\\\\\\\r\\\", \\\"\\\\\\\\t\\\"):\\n        text = text.replace(esc, \\\" \\\")\\n    text = \\\" \\\".join(text.split())\\n    if len(text) > limit:\\n        text = text[: limit - 1].rstrip() + \\\"\u2026\\\"\\n    return text\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/mcp/flow_builder_tools/edit_tools.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"75a0125dbd2801687aad29fa5dc29c9f80e83265b001aa46c52f38addd73c5ba\",\"content\":\"\\\"\\\"\\\"User-reviewable edit proposals (JSON-Patch-validated, no auto-apply).\\n\\n``ProposeFieldEdit`` is the only tool here today: it validates a field-value\\nchange against the working flow with a JSON-Patch dry run and emits an\\n``edit_field`` event so the frontend can render a Continue/Dismiss card.\\nNothing is applied to the canvas until the user accepts.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport copy\\nimport uuid\\n\\nimport jsonpatch\\n\\nfrom lfx.custom import Component\\nfrom lfx.io import MessageTextInput, Output\\nfrom lfx.schema import Data\\nfrom lfx.services.model_provider_policy import ModelProviderPolicyError\\n\\nfrom ._state import (\\n    _emit,\\n    _find_node,\\n    _readable_preview,\\n    emit_tool_start,\\n    get_working_flow,\\n    should_apply_edits_live,\\n)\\n\\n\\ndef emit_field_edit_proposal(flow: dict, component_id: str, field_name: str, new_value: object) -> bool:\\n    \\\"\\\"\\\"Emit a reviewable ``edit_field`` event for one field \u2014 the configure\u2192propose bridge.\\n\\n    Produces the SAME ``edit_field`` payload shape as ``ProposeFieldEdit`` (id,\\n    component_id, component_type, field, old_value, new_value, description, JSON\\n    Patch) so the frontend carousel renders it identically. Returns True when a\\n    proposal was emitted; False when the node/field could not be resolved, so\\n    the caller can fall back to a direct apply.\\n    \\\"\\\"\\\"\\n    node = _find_node(flow, component_id)\\n    if node is None:\\n        return False\\n    template = node.get(\\\"data\\\", {}).get(\\\"node\\\", {}).get(\\\"template\\\", {})\\n    if field_name not in template or not isinstance(template.get(field_name), dict):\\n        return False\\n    old_value = template[field_name].get(\\\"value\\\")\\n\\n    node_idx = None\\n    for i, n in enumerate(flow.get(\\\"data\\\", {}).get(\\\"nodes\\\", [])):\\n        nid = n.get(\\\"data\\\", {}).get(\\\"id\\\", n.get(\\\"id\\\", \\\"\\\"))\\n        if nid == component_id:\\n            node_idx = i\\n            break\\n    if node_idx is None:\\n        return False\\n\\n    path = f\\\"/data/nodes/{node_idx}/data/node/template/{field_name}/value\\\"\\n    patch_ops = [{\\\"op\\\": \\\"replace\\\", \\\"path\\\": path, \\\"value\\\": new_value}]\\n    component_type = node.get(\\\"data\\\", {}).get(\\\"type\\\", \\\"?\\\")\\n    _emit(\\n        \\\"edit_field\\\",\\n        id=str(uuid.uuid4())[:8],\\n        component_id=component_id,\\n        component_type=component_type,\\n        field=field_name,\\n        old_value=old_value,\\n        new_value=new_value,\\n        description=f'Set {field_name} to \\\"{_readable_preview(new_value)}\\\" on {component_type}',\\n        patch=patch_ops,\\n    )\\n    return True\\n\\n\\nclass ProposeFieldEdit(Component):\\n    display_name = \\\"Propose Field Edit\\\"\\n    description = \\\"Propose a field value change on a component. Validates and generates a reviewable patch.\\\"\\n    icon = \\\"Pencil\\\"\\n    name = \\\"ProposeFieldEdit\\\"\\n\\n    inputs = [\\n        MessageTextInput(\\n            name=\\\"component_id\\\",\\n            display_name=\\\"Component ID\\\",\\n            info=\\\"Full component ID (e.g. 'OpenAIModel-x3Y4z').\\\",\\n            required=True,\\n            tool_mode=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"field_name\\\",\\n            display_name=\\\"Field Name\\\",\\n            info=\\\"The field to change (e.g. 'model_name', 'temperature').\\\",\\n            required=True,\\n            tool_mode=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"new_value\\\",\\n            display_name=\\\"New Value\\\",\\n            info=\\\"The new value to set.\\\",\\n            required=True,\\n            tool_mode=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(name=\\\"result\\\", display_name=\\\"Result\\\", method=\\\"propose_field_edit\\\"),\\n    ]\\n\\n    def propose_field_edit(self) -> Data:\\n        emit_tool_start(\\\"propose_field_edit\\\", component_id=self.component_id, field=self.field_name)\\n        flow = get_working_flow()\\n        if flow is None:\\n            return Data(data={\\\"error\\\": \\\"No flow loaded. Cannot propose edits on an empty canvas.\\\"})\\n\\n        # 1. Find the node\\n        node = _find_node(flow, self.component_id)\\n        if node is None:\\n            available = [n.get(\\\"data\\\", {}).get(\\\"id\\\", \\\"\\\") for n in flow.get(\\\"data\\\", {}).get(\\\"nodes\\\", [])]\\n            return Data(\\n                data={\\n                    \\\"error\\\": f\\\"Component '{self.component_id}' not found. Available: {available}\\\",\\n                }\\n            )\\n\\n        # 2. Validate field exists\\n        template = node.get(\\\"data\\\", {}).get(\\\"node\\\", {}).get(\\\"template\\\", {})\\n        if self.field_name not in template or not isinstance(template.get(self.field_name), dict):\\n            available = [k for k, v in template.items() if isinstance(v, dict) and k not in (\\\"code\\\", \\\"_type\\\")]\\n            return Data(\\n                data={\\n                    \\\"error\\\": f\\\"Field '{self.field_name}' not found on '{self.component_id}'. Available: {available}\\\",\\n                }\\n            )\\n\\n        # This tool is an alternate configuration path: the UI may apply its\\n        # emitted patch after approval, while headless callers apply it below.\\n        # Gate the prospective value before either mutation can escape.\\n        from .mutate_tools import _model_providers_in_params, _require_allowed_model_providers\\n\\n        try:\\n            _require_allowed_model_providers(\\n                _model_providers_in_params(flow, self.component_id, {self.field_name: self.new_value})\\n            )\\n        except ModelProviderPolicyError as exc:\\n            return Data(data={\\\"error\\\": str(exc)})\\n\\n        # 3. Read old value\\n        old_value = template[self.field_name].get(\\\"value\\\")\\n\\n        # 4. Resolve node index\\n        node_idx = None\\n        for i, n in enumerate(flow.get(\\\"data\\\", {}).get(\\\"nodes\\\", [])):\\n            nid = n.get(\\\"data\\\", {}).get(\\\"id\\\", n.get(\\\"id\\\", \\\"\\\"))\\n            if nid == self.component_id:\\n                node_idx = i\\n                break\\n\\n        if node_idx is None:\\n            return Data(data={\\\"error\\\": f\\\"Could not resolve index for '{self.component_id}'\\\"})\\n\\n        # 5. Build JSON Patch\\n        path = f\\\"/data/nodes/{node_idx}/data/node/template/{self.field_name}/value\\\"\\n        patch_ops = [{\\\"op\\\": \\\"replace\\\", \\\"path\\\": path, \\\"value\\\": self.new_value}]\\n\\n        # 6. Dry run -- apply to a copy\\n        try:\\n            patch = jsonpatch.JsonPatch(patch_ops)\\n            patched = patch.apply(copy.deepcopy(flow))\\n            # Verify the value actually changed\\n            patched_node = patched[\\\"data\\\"][\\\"nodes\\\"][node_idx]\\n            patched_val = patched_node[\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][self.field_name][\\\"value\\\"]\\n            if patched_val != self.new_value:\\n                return Data(data={\\\"error\\\": \\\"Patch dry run: value did not change as expected\\\"})\\n        except (jsonpatch.JsonPatchException, KeyError, IndexError) as e:\\n            return Data(data={\\\"error\\\": f\\\"Patch validation failed: {e}\\\"})\\n\\n        # 7. Emit flow_action event\\n        component_type = node.get(\\\"data\\\", {}).get(\\\"type\\\", \\\"?\\\")\\n        action_id = str(uuid.uuid4())[:8]\\n        _emit(\\n            \\\"edit_field\\\",\\n            id=action_id,\\n            component_id=self.component_id,\\n            component_type=component_type,\\n            field=self.field_name,\\n            old_value=old_value,\\n            new_value=self.new_value,\\n            description=f'Set {self.field_name} to \\\"{_readable_preview(self.new_value)}\\\" on {component_type}',\\n            patch=patch_ops,\\n        )\\n\\n        preview = _readable_preview(self.new_value)\\n        # Headless callers have no review UI; apply live and narrate as done so the\\n        # assistant never claims a pending-approval step that cannot happen (#13641).\\n        if should_apply_edits_live():\\n            template[self.field_name][\\\"value\\\"] = self.new_value\\n            return Data(data={\\\"text\\\": f'Set {self.field_name} = \\\"{preview}\\\" on {component_type}'})\\n\\n        text = f'Proposed: set {self.field_name} = \\\"{preview}\\\" on {component_type} (pending user approval)'\\n        return Data(data={\\\"text\\\": text})\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/mcp/flow_builder_tools/mutate_tools.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9baa91c70dc9e477d45cff92e3b8baa3d047b95a59af44dd8e4d3bdfbe730aa1\",\"content\":\"\\\"\\\"\\\"Graph-mutation tools (add/remove/connect/configure components).\\n\\nEvery mutation pushes a ``flow_update`` event via ``_emit`` so the\\nassistant service can stream it back to the canvas. Tools here are the\\nones whose effects the user sees on the canvas immediately.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom types import SimpleNamespace\\n\\nfrom lfx.base.models.provider_registry import get_registry_snapshot, model_component_provider_id, resolve_provider_id\\nfrom lfx.custom import Component\\nfrom lfx.graph.flow_builder.component import (\\n    CUSTOM_COMPONENT_CANVAS_TYPE,\\n    FLOW_BUILDER_REGISTRY_TYPE_KEY,\\n    FLOW_BUILDER_UNTRUSTED_CUSTOM_KEY,\\n)\\nfrom lfx.graph.flow_builder.component import (\\n    _coerce_model_value as fb_coerce_model_value,\\n)\\nfrom lfx.graph.flow_builder.component import (\\n    add_component as fb_add_component,\\n)\\nfrom lfx.graph.flow_builder.component import (\\n    configure_component as fb_configure,\\n)\\nfrom lfx.graph.flow_builder.component import (\\n    remove_component as fb_remove_component,\\n)\\nfrom lfx.graph.flow_builder.connect import add_connection as fb_add_connection\\nfrom lfx.graph.flow_builder.layout import layout_flow\\nfrom lfx.io import MessageTextInput, Output\\nfrom lfx.log.logger import logger\\nfrom lfx.schema import Data\\nfrom lfx.services.model_provider_policy import (\\n    ModelProviderPolicyError,\\n    ModelProviderPolicyPurpose,\\n    resolve_model_provider_policy,\\n)\\n\\nfrom ._state import (\\n    _emit,\\n    _ensure_working_flow,\\n    _find_node,\\n    _load_registry_user_aware,\\n    emit_tool_start,\\n    node_existed_at_start,\\n    should_apply_edits_live,\\n    should_propose_existing_edits,\\n)\\nfrom .edit_tools import emit_field_edit_proposal\\n\\n\\nclass AddComponent(Component):\\n    display_name = \\\"Add Component\\\"\\n    description = \\\"Add a component to the user's flow canvas. Returns the component's id.\\\"\\n    icon = \\\"Plus\\\"\\n    name = \\\"AddComponent\\\"\\n\\n    inputs = [\\n        MessageTextInput(\\n            name=\\\"component_type\\\",\\n            display_name=\\\"Component Type\\\",\\n            info=\\\"Component type name (e.g. 'ChatInput', 'OpenAIModel'). Use search_components to find types.\\\",\\n            required=True,\\n            tool_mode=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(name=\\\"result\\\", display_name=\\\"Result\\\", method=\\\"add_component\\\"),\\n    ]\\n\\n    def add_component(self) -> Data:\\n        emit_tool_start(\\\"add_component\\\", component_type=self.component_type)\\n        registry = _load_registry_user_aware()\\n        flow = _ensure_working_flow()\\n        try:\\n            provider_id = _registry_component_provider_id(registry, self.component_type)\\n            _require_allowed_model_providers({provider_id} if provider_id else set())\\n            result = fb_add_component(flow, self.component_type, registry)\\n            layout_flow(flow)\\n            _emit(\\\"add_component\\\", node=flow[\\\"data\\\"][\\\"nodes\\\"][-1])\\n            text = f\\\"Added {self.component_type} ({result['id']})\\\"\\n            return Data(data={\\\"id\\\": result[\\\"id\\\"], \\\"type\\\": self.component_type, \\\"text\\\": text})\\n        except ModelProviderPolicyError as e:\\n            logger.warning(\\\"add_component blocked by model-provider policy: %s\\\", e)\\n            return Data(data={\\\"error\\\": str(e)})\\n        except (ValueError, KeyError) as e:\\n            logger.warning(\\\"add_component failed: %s\\\", e)\\n            return Data(data={\\\"error\\\": str(e)})\\n\\n\\nclass RemoveComponent(Component):\\n    display_name = \\\"Remove Component\\\"\\n    description = \\\"Remove a component and its connections from the flow.\\\"\\n    icon = \\\"Trash2\\\"\\n    name = \\\"RemoveComponent\\\"\\n\\n    inputs = [\\n        MessageTextInput(\\n            name=\\\"component_id\\\",\\n            display_name=\\\"Component ID\\\",\\n            info=\\\"The component ID to remove (e.g. 'ChatInput-a1B2c').\\\",\\n            required=True,\\n            tool_mode=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(name=\\\"result\\\", display_name=\\\"Result\\\", method=\\\"remove_component\\\"),\\n    ]\\n\\n    def remove_component(self) -> Data:\\n        emit_tool_start(\\\"remove_component\\\", component_id=self.component_id)\\n        flow = _ensure_working_flow()\\n        try:\\n            fb_remove_component(flow, self.component_id)\\n            layout_flow(flow)\\n            _emit(\\\"remove_component\\\", component_id=self.component_id)\\n            return Data(data={\\\"removed\\\": self.component_id, \\\"text\\\": f\\\"Removed {self.component_id}\\\"})\\n        except (ValueError, KeyError) as e:\\n            logger.warning(\\\"remove_component failed: %s\\\", e)\\n            return Data(data={\\\"error\\\": str(e)})\\n\\n\\ndef _sync_model_input_connection_mode(flow: dict, target_id: str, target_input: str) -> None:\\n    \\\"\\\"\\\"Flip ``_connectionMode`` on a model-input target so the canvas renders the edge.\\n\\n    Why: ModelInput targets (``type='model'``) render an inline dropdown by default.\\n    The \\\"Connect other models\\\" UX switches the field to connection mode by setting\\n    ``_connectionMode=true`` on the node \u2014 only THEN does the left handle accept\\n    an external model edge visibly. Mirror that flag at connect time, otherwise\\n    the edge exists in state but the dropdown still hides it.\\n    \\\"\\\"\\\"\\n    target_node = _find_node(flow, target_id)\\n    if target_node is None:\\n        return\\n    target_template = target_node.get(\\\"data\\\", {}).get(\\\"node\\\", {}).get(\\\"template\\\", {})\\n    target_field = target_template.get(target_input) or {}\\n    if not (isinstance(target_field, dict) and target_field.get(\\\"type\\\") == \\\"model\\\"):\\n        return\\n    target_node[\\\"data\\\"][\\\"_connectionMode\\\"] = True\\n    _emit(\\\"set_connection_mode\\\", component_id=target_id, enabled=True)\\n\\n\\ndef _emit_source_tool_mode_if_flipped(flow: dict, source_id: str, source_output: str) -> None:\\n    \\\"\\\"\\\"Tell the canvas the source node was flipped to tool mode on connect.\\n\\n    When connecting ``X.component_as_tool -> Agent.tools``, ``add_connection``\\n    flips X into tool mode IN THE WORKING FLOW: its outputs collapse to the\\n    single synthesized ``component_as_tool`` (Toolset) output. The ``connect``\\n    event only carries the EDGE \u2014 it never surfaces X's new outputs. Without\\n    this, the canvas keeps rendering X's OLD output, the edge's\\n    ``component_as_tool`` source handle has no matching handle on the node, and\\n    the edge silently fails to render \u2014 the \\\"says it connected but didn't\\\" bug.\\n    Emit the flipped node's outputs so the frontend re-renders X in tool mode\\n    and the edge can attach.\\n    \\\"\\\"\\\"\\n    if source_output != \\\"component_as_tool\\\":\\n        return\\n    node = _find_node(flow, source_id)\\n    if node is None:\\n        return\\n    inner = node.get(\\\"data\\\", {}).get(\\\"node\\\", {})\\n    if not inner.get(\\\"tool_mode\\\"):\\n        return\\n    _emit(\\\"enable_tool_mode\\\", component_id=source_id, outputs=inner.get(\\\"outputs\\\", []))\\n\\n\\ndef _reconcile_source_selected_output(flow: dict, source_id: str, source_output: str) -> None:\\n    \\\"\\\"\\\"Mirror the connected output as the source node's ``selected_output``.\\n\\n    Why: the frontend reads ``data.selected_output`` (top-level on the ReactFlow\\n    node) to decide which output handle is rendered for components with multiple\\n    outputs. Without this the edge exists but the node label stays on the\\n    default output, looking unconnected. For a single/zero-output source, also\\n    reconcile a stale ``selected_output`` left by a prior wiring.\\n    \\\"\\\"\\\"\\n    source_node = _find_node(flow, source_id)\\n    if source_node is None:\\n        return\\n    outputs = source_node.get(\\\"data\\\", {}).get(\\\"node\\\", {}).get(\\\"outputs\\\", [])\\n    if len(outputs) > 1:\\n        source_node[\\\"data\\\"][\\\"selected_output\\\"] = source_output\\n        _emit(\\\"select_output\\\", component_id=source_id, output_name=source_output)\\n        return\\n    # Single/zero output (e.g. tool-mode collapsed them): a leftover\\n    # selected_output from a prior wiring would point at a removed output.\\n    output_names = {o.get(\\\"name\\\") for o in outputs if isinstance(o, dict)}\\n    stale = source_node[\\\"data\\\"].get(\\\"selected_output\\\")\\n    if stale is None or stale in output_names:\\n        return\\n    source_node[\\\"data\\\"].pop(\\\"selected_output\\\", None)\\n    if outputs:\\n        _emit(\\\"select_output\\\", component_id=source_id, output_name=outputs[0].get(\\\"name\\\", \\\"\\\"))\\n\\n\\ndef _current_policy_user_id() -> str | None:\\n    \\\"\\\"\\\"Return the request user when lfx is hosted by Langflow.\\\"\\\"\\\"\\n    try:\\n        from langflow.agentic.services.user_components_context import current_user_id\\n    except ImportError:\\n        return None\\n    return current_user_id()\\n\\n\\ndef _model_providers_in_template(template: dict, params: dict | None = None) -> set[str]:\\n    \\\"\\\"\\\"Extract providers from model selections and their scalar provider override.\\\"\\\"\\\"\\n    providers: set[str] = set()\\n    has_model_field = False\\n    for field_name, field in template.items():\\n        if not isinstance(field, dict) or field.get(\\\"type\\\") != \\\"model\\\":\\n            continue\\n        has_model_field = True\\n        value = params.get(field_name, field.get(\\\"value\\\")) if params is not None else field.get(\\\"value\\\")\\n        normalized = fb_coerce_model_value(value)\\n        if not isinstance(normalized, list):\\n            continue\\n        for entry in normalized:\\n            if not isinstance(entry, dict):\\n                continue\\n            provider = entry.get(\\\"provider\\\")\\n            if isinstance(provider, str) and provider.strip():\\n                providers.add(provider.strip())\\n\\n    # Unified LanguageModel/EmbeddingModel wrappers can replace the provider\\n    # selected in their ModelInput at runtime through a scalar `provider`\\n    # field. Treat that override as part of the model configuration too.\\n    provider_field = template.get(\\\"provider\\\")\\n    if has_model_field and isinstance(provider_field, dict):\\n        provider = (\\n            params.get(\\\"provider\\\", provider_field.get(\\\"value\\\")) if params is not None else provider_field.get(\\\"value\\\")\\n        )\\n        if isinstance(provider, str) and provider.strip():\\n            providers.add(provider.strip())\\n    return providers\\n\\n\\ndef _model_providers_in_params(flow: dict, component_id: str, params: dict) -> set[str]:\\n    \\\"\\\"\\\"Extract provider names from model configuration without mutating the flow.\\\"\\\"\\\"\\n    node = _find_node(flow, component_id)\\n    if node is None:\\n        return set()\\n    node_data = node.get(\\\"data\\\", {})\\n    component = node_data.get(\\\"node\\\", {})\\n    template = component.get(\\\"template\\\", {}) if isinstance(component, dict) else {}\\n    providers = _model_providers_in_template(template, params) if isinstance(template, dict) else set()\\n    if provider_id := _stored_component_provider_id(node_data, _load_registry_user_aware()):\\n        providers.add(provider_id)\\n    return providers\\n\\n\\ndef _stored_component_provider_id(node_data: dict, registry: dict[str, dict] | None = None) -> str | None:\\n    \\\"\\\"\\\"Return a stored node's standalone provider identity without losing custom provenance.\\\"\\\"\\\"\\n    component = node_data.get(\\\"node\\\")\\n    component_type = node_data.get(\\\"type\\\")\\n    if not isinstance(component, dict) or not isinstance(component_type, str):\\n        return None\\n\\n    is_untrusted_custom = (\\n        component_type == CUSTOM_COMPONENT_CANVAS_TYPE or node_data.get(FLOW_BUILDER_UNTRUSTED_CUSTOM_KEY) is True\\n    )\\n    if is_untrusted_custom:\\n        registry_type = node_data.get(FLOW_BUILDER_REGISTRY_TYPE_KEY)\\n        if not isinstance(registry_type, str) or not registry_type:\\n            # Older stored CustomComponent nodes lack flow-builder provenance.\\n            # Keep them in a denied-by-default custom namespace rather than\\n            # trusting provider metadata serialized with the flow.\\n            registry_type = CUSTOM_COMPONENT_CANVAS_TYPE\\n        return _registry_component_provider_id(\\n            {registry_type: {**component, \\\"custom\\\": True}},\\n            registry_type,\\n        )\\n\\n    if registry is not None and isinstance(registry.get(component_type), dict):\\n        # Stored node metadata is editable flow data. When the type still\\n        # exists, classify it from the current trusted registry entry.\\n        return _registry_component_provider_id(registry, component_type)\\n\\n    # Registry-miss compatibility for older saved nodes: keep the stored\\n    # component shape needed to derive its legacy identity, but never accept a\\n    # serialized exemption or structural ModelInput delegation. The explicit\\n    # standalone mode makes this path fail closed under a restrictive policy.\\n    legacy_component = {**component, \\\"model_provider_policy_mode\\\": \\\"standalone\\\"}\\n    legacy_component.pop(\\\"custom\\\", None)\\n    metadata = legacy_component.get(\\\"metadata\\\")\\n    if isinstance(metadata, dict):\\n        legacy_component[\\\"metadata\\\"] = {\\n            key: value for key, value in metadata.items() if key != \\\"model_provider_policy_mode\\\"\\n        }\\n    return _registry_component_provider_id({component_type: legacy_component}, component_type)\\n\\n\\ndef _registry_component_provider_id(registry: dict[str, dict], component_type: str) -> str | None:\\n    \\\"\\\"\\\"Return the provider ID for a standalone model component registry entry.\\\"\\\"\\\"\\n    entry = registry.get(component_type)\\n    if not isinstance(entry, dict):\\n        return None\\n    template = entry.get(\\\"template\\\")\\n    metadata = entry.get(\\\"metadata\\\")\\n    metadata = metadata if isinstance(metadata, dict) else {}\\n    is_user_overlay = entry.get(\\\"custom\\\") is True\\n    if \\\"model_provider_policy_mode\\\" in entry:\\n        policy_mode = entry[\\\"model_provider_policy_mode\\\"]\\n        has_explicit_policy_mode = True\\n    elif \\\"model_provider_policy_mode\\\" in metadata:\\n        policy_mode = metadata[\\\"model_provider_policy_mode\\\"]\\n        has_explicit_policy_mode = True\\n    else:\\n        policy_mode = None\\n        has_explicit_policy_mode = False\\n\\n    # Only static, platform-built entries may delegate or opt out. User\\n    # overlays carry source and metadata authored by the user, so neither may\\n    # create an authorization exemption.\\n    if not is_user_overlay and policy_mode in {\\\"delegate\\\", \\\"none\\\"}:\\n        return None\\n\\n    has_model_field = isinstance(template, dict) and any(\\n        isinstance(field, dict) and field.get(\\\"type\\\") == \\\"model\\\" for field in template.values()\\n    )\\n    if not is_user_overlay and not has_explicit_policy_mode and has_model_field:\\n        # Compatibility for legacy platform-built unified selectors that\\n        # predate explicit policy-mode metadata. An explicit unknown mode\\n        # fails closed to standalone instead of taking this structural path.\\n        return None\\n    base_classes = entry.get(\\\"base_classes\\\")\\n    if not isinstance(base_classes, list) or not {\\\"LanguageModel\\\", \\\"Embeddings\\\"}.intersection(base_classes):\\n        return None\\n    if is_user_overlay:\\n        # Overlay metadata and class attributes are user-authored, including\\n        # model_provider_id/display_name. Bind policy to the trusted registry\\n        # key under a separate namespace instead of accepting a claimed core\\n        # provider identity.\\n        return f\\\"custom-{resolve_provider_id(component_type)}\\\"\\n    component = SimpleNamespace(\\n        display_name=entry.get(\\\"display_name\\\"),\\n        model_provider_id=entry.get(\\\"model_provider_id\\\") or metadata.get(\\\"model_provider_id\\\"),\\n    )\\n    return model_component_provider_id(component, module_name=entry.get(\\\"module\\\") or metadata.get(\\\"module\\\"))\\n\\n\\ndef _model_providers_in_flow_spec(spec: str, registry: dict[str, dict]) -> set[str]:\\n    \\\"\\\"\\\"Extract every provider a full-flow spec would configure, without building it.\\\"\\\"\\\"\\n    from lfx.graph.flow_builder.spec import parse_flow_spec\\n\\n    parsed = parse_flow_spec(spec)\\n    node_types = {node[\\\"id\\\"]: node[\\\"type\\\"] for node in parsed[\\\"nodes\\\"]}\\n    providers = {\\n        provider_id\\n        for component_type in node_types.values()\\n        if (provider_id := _registry_component_provider_id(registry, component_type))\\n    }\\n    for node_id, params in parsed.get(\\\"config\\\", {}).items():\\n        entry = registry.get(node_types.get(node_id, \\\"\\\"))\\n        template = entry.get(\\\"template\\\") if isinstance(entry, dict) else None\\n        if not isinstance(template, dict):\\n            continue\\n        providers.update(_model_providers_in_template(template, params))\\n    return providers\\n\\n\\ndef _model_providers_in_flow(flow: dict, registry: dict[str, dict]) -> set[str]:\\n    \\\"\\\"\\\"Extract configured providers from a built flow before it is persisted.\\\"\\\"\\\"\\n    providers: set[str] = set()\\n    for node in flow.get(\\\"data\\\", {}).get(\\\"nodes\\\", []):\\n        node_data = node.get(\\\"data\\\", {})\\n        if provider_id := _stored_component_provider_id(node_data, registry):\\n            providers.add(provider_id)\\n        template = node_data.get(\\\"node\\\", {}).get(\\\"template\\\", {})\\n        if not isinstance(template, dict):\\n            continue\\n        providers.update(_model_providers_in_template(template))\\n    return providers\\n\\n\\ndef _filter_registry_by_model_provider_policy(registry: dict[str, dict]) -> dict[str, dict]:\\n    \\\"\\\"\\\"Hide standalone provider components denied for configuration.\\\"\\\"\\\"\\n    providers_by_type = {\\n        component_type: provider_id\\n        for component_type in registry\\n        if (provider_id := _registry_component_provider_id(registry, component_type))\\n    }\\n    if not providers_by_type:\\n        return registry\\n    policy = resolve_model_provider_policy(\\n        user_id=_current_policy_user_id(),\\n        providers=[*get_registry_snapshot().provider_ids, *providers_by_type.values()],\\n        purpose=ModelProviderPolicyPurpose.CONFIGURE,\\n    )\\n    return {\\n        component_type: entry\\n        for component_type, entry in registry.items()\\n        if (provider_id := providers_by_type.get(component_type)) is None or policy.allows(provider_id)\\n    }\\n\\n\\ndef _require_allowed_model_providers(providers: set[str]) -> None:\\n    \\\"\\\"\\\"Require CONFIGURE policy before model values reach configuration or catalogs.\\\"\\\"\\\"\\n    if not providers:\\n        return\\n    policy = resolve_model_provider_policy(\\n        user_id=_current_policy_user_id(),\\n        providers=[*get_registry_snapshot().provider_ids, *providers],\\n        purpose=ModelProviderPolicyPurpose.CONFIGURE,\\n    )\\n    for provider in providers:\\n        policy.require(provider)\\n\\n\\nclass ConnectComponents(Component):\\n    display_name = \\\"Connect Components\\\"\\n    description = \\\"Connect an output of one component to an input of another.\\\"\\n    icon = \\\"Link\\\"\\n    name = \\\"ConnectComponents\\\"\\n\\n    inputs = [\\n        MessageTextInput(name=\\\"source_id\\\", display_name=\\\"Source ID\\\", required=True, tool_mode=True),\\n        MessageTextInput(name=\\\"source_output\\\", display_name=\\\"Source Output\\\", required=True, tool_mode=True),\\n        MessageTextInput(name=\\\"target_id\\\", display_name=\\\"Target ID\\\", required=True, tool_mode=True),\\n        MessageTextInput(name=\\\"target_input\\\", display_name=\\\"Target Input\\\", required=True, tool_mode=True),\\n    ]\\n\\n    outputs = [\\n        Output(name=\\\"result\\\", display_name=\\\"Result\\\", method=\\\"connect_components\\\"),\\n    ]\\n\\n    def connect_components(self) -> Data:\\n        # B3: model-input mirroring + selected-output reconciliation live in\\n        # module-private helpers above so this orchestrator stays flat (CC \u2264 3).\\n        emit_tool_start(\\\"connect_components\\\", source_id=self.source_id, target_id=self.target_id)\\n        flow = _ensure_working_flow()\\n        # Only the tool-mode capability check reads the registry, and loading it\\n        # walks the user's component overlay \u2014 keep ordinary edges off that path.\\n        registry = _load_registry_user_aware() if self.source_output == \\\"component_as_tool\\\" else None\\n        try:\\n            fb_add_connection(\\n                flow,\\n                self.source_id,\\n                self.source_output,\\n                self.target_id,\\n                self.target_input,\\n                registry=registry,\\n            )\\n            layout_flow(flow)\\n            _sync_model_input_connection_mode(flow, self.target_id, self.target_input)\\n            # Flip tool-mode BEFORE emitting the edge, else the source node has\\n            # no `component_as_tool` handle yet and the edge never attaches.\\n            _emit_source_tool_mode_if_flipped(flow, self.source_id, self.source_output)\\n            edge = flow[\\\"data\\\"][\\\"edges\\\"][-1]\\n            _emit(\\\"connect\\\", edge=edge)\\n            _reconcile_source_selected_output(flow, self.source_id, self.source_output)\\n            return Data(\\n                data={\\n                    \\\"text\\\": f\\\"Connected {self.source_id}.{self.source_output} -> {self.target_id}.{self.target_input}\\\",\\n                }\\n            )\\n        except (ValueError, KeyError) as e:\\n            logger.warning(\\\"connect_components failed: %s\\\", e)\\n            return Data(data={\\\"error\\\": str(e)})\\n\\n\\nclass ConfigureComponent(Component):\\n    display_name = \\\"Configure Component\\\"\\n    description = \\\"Set one or more parameters on a component. Pass a JSON dict for multiple params at once.\\\"\\n    icon = \\\"Settings\\\"\\n    name = \\\"ConfigureComponent\\\"\\n\\n    inputs = [\\n        MessageTextInput(name=\\\"component_id\\\", display_name=\\\"Component ID\\\", required=True, tool_mode=True),\\n        MessageTextInput(\\n            name=\\\"params\\\",\\n            display_name=\\\"Parameters\\\",\\n            info='JSON dict of params to set, e.g. \\\\'{\\\"model_name\\\": \\\"gpt-4o\\\", \\\"temperature\\\": 0.7}\\\\'',\\n            required=True,\\n            tool_mode=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(name=\\\"result\\\", display_name=\\\"Result\\\", method=\\\"configure_component\\\"),\\n    ]\\n\\n    def configure_component(self) -> Data:\\n        emit_tool_start(\\\"configure_component\\\", component_id=self.component_id)\\n        flow = _ensure_working_flow()\\n\\n        # Accept params as dict (from tool framework) or JSON string\\n        raw = self.params\\n        if isinstance(raw, dict):\\n            params = raw\\n        else:\\n            raw = (raw or \\\"\\\").strip()\\n            try:\\n                params = json.loads(raw)\\n                if not isinstance(params, dict):\\n                    return Data(data={\\\"error\\\": f\\\"params must be a JSON object, got {type(params).__name__}\\\"})\\n            except json.JSONDecodeError:\\n                return Data(data={\\\"error\\\": f'Invalid JSON in params: {raw!r}. Use format: {{\\\"key\\\": \\\"value\\\"}}'})\\n\\n        try:\\n            _require_allowed_model_providers(_model_providers_in_params(flow, self.component_id, params))\\n        except ModelProviderPolicyError as e:\\n            logger.warning(\\\"configure_component blocked by model-provider policy: %s\\\", e)\\n            return Data(data={\\\"error\\\": str(e)})\\n\\n        # Deterministic review gate (Bug B): editing a TEXT field on a pre-existing\\n        # component is surfaced as a reviewable diff; model/number/bool still apply live.\\n        if (\\n            should_propose_existing_edits()\\n            and node_existed_at_start(self.component_id)\\n            and not should_apply_edits_live()\\n        ):\\n            text_params = {k: v for k, v in params.items() if isinstance(v, str) and k != \\\"model\\\"}\\n            if text_params:\\n                proposed: list[str] = [\\n                    k for k, v in text_params.items() if emit_field_edit_proposal(flow, self.component_id, k, v)\\n                ]\\n                remaining = {k: v for k, v in params.items() if k not in proposed}\\n                if remaining:\\n                    try:\\n                        fb_configure(flow, self.component_id, remaining)\\n                        _fill_missing_model_names(flow, self.component_id, remaining)\\n                        _mirror_model_value_into_options(flow, self.component_id, remaining)\\n                        _emit(\\\"configure\\\", component_id=self.component_id, params=remaining)\\n                    except (ValueError, KeyError) as e:\\n                        logger.warning(\\\"configure_component (non-text remainder) failed: %s\\\", e)\\n                        return Data(data={\\\"error\\\": str(e)})\\n                if proposed:\\n                    fields = \\\", \\\".join(proposed)\\n                    return Data(\\n                        data={\\n                            \\\"text\\\": f\\\"Proposed changes to {fields} on {self.component_id} (pending user approval)\\\",\\n                            \\\"proposed\\\": proposed,\\n                        }\\n                    )\\n\\n        try:\\n            # fb_configure normalizes the model spec (JSON/YAML/dict/list) in place;\\n            # the fill + mirror steps below then read the canonical list[dict].\\n            fb_configure(flow, self.component_id, params)\\n            # Provider-only selections get the catalog default name, then mirror\\n            # into `options` so the dropdown matches instead of its own fallback.\\n            _fill_missing_model_names(flow, self.component_id, params)\\n            _mirror_model_value_into_options(flow, self.component_id, params)\\n            _emit(\\\"configure\\\", component_id=self.component_id, params=params)\\n            summary = \\\", \\\".join(f\\\"{k}={v!r}\\\" for k, v in params.items())\\n            return Data(data={\\\"text\\\": f\\\"Set {summary} on {self.component_id}\\\", \\\"configured\\\": list(params.keys())})\\n        except (ValueError, KeyError) as e:\\n            logger.warning(\\\"configure_component failed: %s\\\", e)\\n            return Data(data={\\\"error\\\": str(e)})\\n\\n\\ndef _mirror_model_value_into_options(flow: dict, component_id: str, params: dict) -> None:\\n    \\\"\\\"\\\"Mirror the new ModelInput selection into the field's `options` array.\\n\\n    For each ModelInput field touched in `params`, ensure the new selection\\n    is present in the field's `options` array. No-op for non-model fields.\\n    Idempotent: existing entries with the same name+provider are not\\n    duplicated.\\n    \\\"\\\"\\\"\\n    node = _find_node(flow, component_id)\\n    if node is None:\\n        return\\n    template = node.get(\\\"data\\\", {}).get(\\\"node\\\", {}).get(\\\"template\\\", {})\\n    for field_name, value in params.items():\\n        field = template.get(field_name)\\n        if not isinstance(field, dict) or field.get(\\\"type\\\") != \\\"model\\\":\\n            continue\\n        if not isinstance(value, list) or not value:\\n            continue\\n        first = value[0]\\n        if not isinstance(first, dict):\\n            continue\\n        new_name = first.get(\\\"name\\\")\\n        new_provider = first.get(\\\"provider\\\")\\n        if not new_name:\\n            continue\\n        options = field.get(\\\"options\\\") or []\\n        if any(\\n            isinstance(o, dict) and o.get(\\\"name\\\") == new_name and o.get(\\\"provider\\\") == new_provider for o in options\\n        ):\\n            continue\\n        options.append({\\\"name\\\": new_name, \\\"provider\\\": new_provider})\\n        field[\\\"options\\\"] = options\\n\\n\\ndef _resolve_default_model_name(provider: str) -> str | None:\\n    \\\"\\\"\\\"Return the provider's catalog default model name, or None if unknown.\\\"\\\"\\\"\\n    _require_allowed_model_providers({provider})\\n\\n    from lfx.base.models.unified_models import get_unified_models_detailed\\n\\n    detailed = get_unified_models_detailed(\\n        providers=[provider],\\n        only_defaults=True,\\n        include_unsupported=False,\\n        include_deprecated=False,\\n    )\\n    for entry in detailed:\\n        for model in entry.get(\\\"models\\\", []):\\n            name = model.get(\\\"model_name\\\")\\n            if name:\\n                return name\\n    return None\\n\\n\\ndef _fill_missing_model_names(flow: dict, component_id: str, params: dict) -> None:\\n    \\\"\\\"\\\"Fill a provider-only model selection with the provider's default model.\\n\\n    A bare ``[{\\\"provider\\\": X}]`` (no name) otherwise leaves the canvas dropdown\\n    to silently pick the provider's newest model, diverging from what the\\n    assistant reported. Resolving the default keeps value, options and the\\n    result text on the same concrete model. ``params`` shares the value object\\n    set by ``fb_configure``, so mutating it updates the node template too.\\n    \\\"\\\"\\\"\\n    node = _find_node(flow, component_id)\\n    if node is None:\\n        return\\n    template = node.get(\\\"data\\\", {}).get(\\\"node\\\", {}).get(\\\"template\\\", {})\\n    for field_name, value in params.items():\\n        field = template.get(field_name)\\n        if not isinstance(field, dict) or field.get(\\\"type\\\") != \\\"model\\\":\\n            continue\\n        if not isinstance(value, list) or not value or not isinstance(value[0], dict):\\n            continue\\n        entry = value[0]\\n        if entry.get(\\\"name\\\") or not entry.get(\\\"provider\\\"):\\n            continue\\n        default_name = _resolve_default_model_name(entry[\\\"provider\\\"])\\n        if default_name:\\n            entry[\\\"name\\\"] = default_name\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/mcp/flow_builder_tools/read_tools.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"665d5f8e1b53c7fbb6f9ad1dc8fb0fbf23f35e26dc2751c8c7455dee9da16462\",\"content\":\"\\\"\\\"\\\"Read-only inspection tools for the flow-builder assistant.\\n\\nThese tools never mutate the working flow or emit events: they answer the\\nagent's \\\"what components exist / what does this look like / what is the\\nflow shaped like\\\" questions, so the agent can plan before editing.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom lfx.custom import Component\\nfrom lfx.io import MessageTextInput, Output\\nfrom lfx.log.logger import logger\\nfrom lfx.mcp.redact import is_sensitive_field\\nfrom lfx.mcp.registry import describe_component, search_registry\\nfrom lfx.schema import Data\\n\\nfrom ._state import _ensure_working_flow, _find_node, _load_registry_user_aware\\n\\n\\nclass SearchComponentTypes(Component):\\n    display_name = \\\"Search Components\\\"\\n    description = \\\"Search available Langflow component types by name, category, or output type.\\\"\\n    icon = \\\"Search\\\"\\n    name = \\\"SearchComponentTypes\\\"\\n\\n    inputs = [\\n        MessageTextInput(\\n            name=\\\"query\\\",\\n            display_name=\\\"Query\\\",\\n            info=\\\"Search term to filter by name or category (case-insensitive).\\\",\\n            tool_mode=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(name=\\\"results\\\", display_name=\\\"Results\\\", method=\\\"search_components\\\"),\\n    ]\\n\\n    def search_components(self) -> Data:\\n        # Pure read against the local registry \u2014 memoize per request so\\n        # repeated planning turns don't re-walk the registry.\\n        from lfx.mcp.tool_cache import cached_tool_call\\n\\n        def producer() -> Data:\\n            registry = _load_registry_user_aware()\\n            from .mutate_tools import _filter_registry_by_model_provider_policy\\n\\n            registry = _filter_registry_by_model_provider_policy(registry)\\n            results = search_registry(registry, query=self.query or None)\\n            return Data(data={\\\"results\\\": results, \\\"count\\\": len(results)})\\n\\n        return cached_tool_call(\\n            \\\"search_components\\\",\\n            {\\\"query\\\": self.query or None},\\n            producer,\\n        )\\n\\n\\nclass DescribeComponentType(Component):\\n    display_name = \\\"Describe Component\\\"\\n    description = \\\"Get a component type's inputs, outputs, and fields. Use to learn what a component accepts.\\\"\\n    icon = \\\"Info\\\"\\n    name = \\\"DescribeComponentType\\\"\\n\\n    inputs = [\\n        MessageTextInput(\\n            name=\\\"component_type\\\",\\n            display_name=\\\"Component Type\\\",\\n            info=\\\"The component type name (e.g. 'ChatInput', 'OpenAIModel').\\\",\\n            required=True,\\n            tool_mode=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(name=\\\"description\\\", display_name=\\\"Description\\\", method=\\\"describe_component\\\"),\\n    ]\\n\\n    def describe_component(self) -> Data:\\n        # Pure read \u2014 describing a registry type is deterministic per\\n        # request. Cached so repeated configure/connect flows reuse it.\\n        from lfx.mcp.tool_cache import cached_tool_call\\n\\n        component_type = self.component_type\\n\\n        def producer() -> Data:\\n            registry = _load_registry_user_aware()\\n            from .mutate_tools import _filter_registry_by_model_provider_policy\\n\\n            registry = _filter_registry_by_model_provider_policy(registry)\\n            try:\\n                result = describe_component(registry, component_type)\\n            except ValueError as e:\\n                logger.warning(\\\"describe_component failed: %s\\\", e)\\n                return Data(data={\\\"error\\\": str(e)})\\n            return Data(data=result)\\n\\n        return cached_tool_call(\\n            \\\"describe_component\\\",\\n            {\\\"component_type\\\": component_type},\\n            producer,\\n        )\\n\\n\\nclass GetFieldValue(Component):\\n    display_name = \\\"Get Field Value\\\"\\n    description = \\\"Read field values from a component on the canvas. Use the component ID from the flow summary.\\\"\\n    icon = \\\"Eye\\\"\\n    name = \\\"GetFieldValue\\\"\\n\\n    inputs = [\\n        MessageTextInput(\\n            name=\\\"component_id\\\",\\n            display_name=\\\"Component ID\\\",\\n            info=\\\"Full component ID from the flow summary (e.g. 'ChatInput-a1B2c').\\\",\\n            required=True,\\n            tool_mode=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"field_name\\\",\\n            display_name=\\\"Field Name\\\",\\n            info=\\\"Field to read (e.g. 'input_value', 'model_name'). Leave empty to list all fields.\\\",\\n            tool_mode=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(name=\\\"result\\\", display_name=\\\"Result\\\", method=\\\"get_field_value\\\"),\\n    ]\\n\\n    def get_field_value(self) -> Data:\\n        flow = _ensure_working_flow()\\n        node = _find_node(flow, self.component_id)\\n        if node is None:\\n            available = [n.get(\\\"data\\\", {}).get(\\\"id\\\", \\\"\\\") for n in flow.get(\\\"data\\\", {}).get(\\\"nodes\\\", [])]\\n            return Data(data={\\\"error\\\": f\\\"Component '{self.component_id}' not found. Available: {available}\\\"})\\n\\n        template = node.get(\\\"data\\\", {}).get(\\\"node\\\", {}).get(\\\"template\\\", {})\\n\\n        if not self.field_name:\\n            # List all fields with their values\\n            fields = {}\\n            for fname, fdata in template.items():\\n                if not isinstance(fdata, dict) or fname in (\\\"code\\\", \\\"_type\\\"):\\n                    continue\\n                value = fdata.get(\\\"value\\\")\\n                if is_sensitive_field(fname) and value:\\n                    fields[fname] = \\\"***REDACTED***\\\"\\n                else:\\n                    fields[fname] = value\\n            return Data(data={\\\"component_id\\\": self.component_id, \\\"fields\\\": fields})\\n\\n        # Get specific field\\n        if self.field_name not in template:\\n            available = [k for k, v in template.items() if isinstance(v, dict) and k not in (\\\"code\\\", \\\"_type\\\")]\\n            return Data(data={\\\"error\\\": f\\\"Field '{self.field_name}' not found. Available: {available}\\\"})\\n\\n        fdata = template[self.field_name]\\n        value = fdata.get(\\\"value\\\") if isinstance(fdata, dict) else fdata\\n        if is_sensitive_field(self.field_name) and value:\\n            value = \\\"***REDACTED***\\\"\\n        return Data(data={\\\"component_id\\\": self.component_id, \\\"field\\\": self.field_name, \\\"value\\\": value})\\n\\n\\nclass DescribeFlowIO(Component):\\n    \\\"\\\"\\\"Deterministically resolve the flow's input/output/tool components.\\n\\n    Computed from the graph wiring \u2014 O(1) for the agent and exact at ANY\\n    flow size, so the agent never has to scan `connections` by eye (which\\n    mis-targets on large flows: e.g. editing a tool component instead of\\n    the ChatInput). Call this to find which component \\\"the input\\\" means\\n    BEFORE editing it.\\n\\n    Classification (by role in the edges, never by name):\\n      - tool: a source whose every outgoing edge feeds a `tools` handle\\n        (the `component_as_tool` wiring) \u2014 NOT the flow input.\\n      - input: a node with NO incoming edges that is not a tool \u2014 its\\n        `value_field` is the field to set (\\\"input_value\\\"/\\\"input_text\\\"/...).\\n      - output: a sink (no outgoing edges), typically ChatOutput.\\n    \\\"\\\"\\\"\\n\\n    display_name = \\\"Describe Flow IO\\\"\\n    description = (\\n        \\\"Return the flow's input components (and which field carries the run input), output \\\"\\n        \\\"components, and tool components, computed from the canvas wiring. Use this to find \\\"\\n        \\\"which component 'the input' / 'o input' refers to before editing it \u2014 never guess \\\"\\n        \\\"from names. If there is more than one input, ask the user which one.\\\"\\n    )\\n    icon = \\\"ArrowRightLeft\\\"\\n    name = \\\"DescribeFlowIO\\\"\\n\\n    inputs = [\\n        MessageTextInput(\\n            name=\\\"reason\\\",\\n            display_name=\\\"Reason\\\",\\n            info=\\\"Optional short note on why you are inspecting the flow IO (does not change anything).\\\",\\n            required=False,\\n            tool_mode=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(name=\\\"result\\\", display_name=\\\"Flow IO\\\", method=\\\"describe_flow_io\\\"),\\n    ]\\n\\n    _VALUE_FIELDS = (\\\"input_value\\\", \\\"input_text\\\", \\\"text\\\")\\n\\n    def describe_flow_io(self) -> Data:\\n        flow = _ensure_working_flow()\\n        data = flow.get(\\\"data\\\") or {}\\n        nodes = data.get(\\\"nodes\\\") or []\\n        edges = data.get(\\\"edges\\\") or []\\n\\n        def _nid(node: dict) -> str:\\n            nd = node.get(\\\"data\\\", {}) or {}\\n            return nd.get(\\\"id\\\", node.get(\\\"id\\\", \\\"\\\"))\\n\\n        def _ntype(node: dict) -> str:\\n            return (node.get(\\\"data\\\", {}) or {}).get(\\\"type\\\", \\\"?\\\")\\n\\n        def _template(node: dict) -> dict:\\n            return (node.get(\\\"data\\\", {}) or {}).get(\\\"node\\\", {}).get(\\\"template\\\", {}) or {}\\n\\n        incoming: dict[str, int] = {}\\n        out_target_fields: dict[str, list] = {}\\n        for edge in edges:\\n            src = edge.get(\\\"source\\\", \\\"\\\")\\n            tgt = edge.get(\\\"target\\\", \\\"\\\")\\n            tgt_handle = (edge.get(\\\"data\\\", {}) or {}).get(\\\"targetHandle\\\", {})\\n            field = tgt_handle.get(\\\"fieldName\\\") if isinstance(tgt_handle, dict) else None\\n            if tgt:\\n                incoming[tgt] = incoming.get(tgt, 0) + 1\\n            if src:\\n                out_target_fields.setdefault(src, []).append(field)\\n\\n        inputs: list[dict] = []\\n        outputs: list[dict] = []\\n        tools: list[dict] = []\\n        for node in nodes:\\n            nid = _nid(node)\\n            ntype = _ntype(node)\\n            outs = out_target_fields.get(nid, [])\\n            # A tool provider's every outgoing edge targets a `tools` input.\\n            if outs and all(f == \\\"tools\\\" for f in outs):\\n                tools.append({\\\"id\\\": nid, \\\"type\\\": ntype})\\n                continue\\n            if not outs:\\n                outputs.append({\\\"id\\\": nid, \\\"type\\\": ntype})\\n            if incoming.get(nid, 0) == 0:\\n                tmpl = _template(node)\\n                value_field = next((f for f in self._VALUE_FIELDS if isinstance(tmpl.get(f), dict)), None)\\n                inputs.append({\\\"id\\\": nid, \\\"type\\\": ntype, \\\"value_field\\\": value_field})\\n\\n        def _fmt(items: list, *, with_field: bool = False) -> str:\\n            if not items:\\n                return \\\"(none)\\\"\\n            parts = []\\n            for it in items:\\n                if with_field and it.get(\\\"value_field\\\"):\\n                    parts.append(f\\\"{it['id']} ({it['type']}, set {it['value_field']})\\\")\\n                else:\\n                    parts.append(f\\\"{it['id']} ({it['type']})\\\")\\n            return \\\", \\\".join(parts)\\n\\n        text = f\\\"inputs: {_fmt(inputs, with_field=True)}\\\\noutputs: {_fmt(outputs)}\\\\ntools: {_fmt(tools)}\\\"\\n        return Data(data={\\\"inputs\\\": inputs, \\\"outputs\\\": outputs, \\\"tools\\\": tools, \\\"text\\\": text})\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/mcp/flow_builder_tools/run_tools.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"511a536907d52cc433957c17ffceb28aac88f4415cc5eb2c60e0a2c8de373a06\",\"content\":\"\\\"\\\"\\\"Plan / build / run / generate orchestration tools.\\n\\nThe \\\"do the bigger thing\\\" tools \u2014 propose a plan to the user, build a whole\\nflow from a spec, execute the canvas flow, generate a brand-new component.\\nEach is decoupled from ``langflow`` via late imports (``lfx`` ships without\\nthe backend), and the run/generate tools coordinate with the per-request\\nstate in ``_state`` so the canvas the user sees is the canvas that runs.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nfrom uuid import uuid4\\n\\nfrom lfx.custom import Component\\nfrom lfx.graph.flow_builder.builder import build_flow_from_spec\\nfrom lfx.io import MessageTextInput, Output\\nfrom lfx.log.logger import logger\\nfrom lfx.schema import Data\\nfrom lfx.services.model_provider_policy import ModelProviderPolicyError\\n\\nfrom ._state import (\\n    _current_flow_id_var,\\n    _emit,\\n    _ensure_working_flow,\\n    _load_registry_user_aware,\\n    emit_tool_start,\\n    get_working_flow,\\n    isolate_flow_run_context,\\n)\\n\\n\\nclass ProposePlan(Component):\\n    \\\"\\\"\\\"Propose a build plan to the user and pause until they approve or dismiss.\\n\\n    Emitted as a `propose_plan` event with the markdown body; the assistant\\n    service forwards it to the frontend, which renders a Continue/Dismiss card\\n    in the chat. The agent MUST stop after this tool call \u2014 the user's reply\\n    arrives as a new user turn (Continue \u21d2 \\\"User approved the plan. Proceed.\\\",\\n    Dismiss \u21d2 free-form refinement feedback).\\n    \\\"\\\"\\\"\\n\\n    display_name = \\\"Propose Plan\\\"\\n    description = (\\n        \\\"Propose a high-level build plan to the user as markdown. The user sees a \\\"\\n        \\\"Continue/Dismiss card and the agent must wait for the next user turn before \\\"\\n        \\\"calling any other tools.\\\"\\n    )\\n    icon = \\\"ClipboardList\\\"\\n    name = \\\"ProposePlan\\\"\\n\\n    inputs = [\\n        MessageTextInput(\\n            name=\\\"plan\\\",\\n            display_name=\\\"Plan (Markdown)\\\",\\n            info=(\\n                \\\"Markdown text describing what the agent will build. Should cover the \\\"\\n                \\\"components to add, the model/persona, and any non-obvious configuration. \\\"\\n                \\\"Keep it readable for the user \u2014 they will Continue or Dismiss it.\\\"\\n            ),\\n            required=True,\\n            tool_mode=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(name=\\\"plan_result\\\", display_name=\\\"Plan Result\\\", method=\\\"propose_plan\\\"),\\n    ]\\n\\n    def propose_plan(self) -> Data:\\n        plan = (self.plan or \\\"\\\").strip()\\n        if not plan:\\n            error_msg = (\\n                \\\"Plan is empty. Provide a non-empty markdown description of what you intend to build, \\\"\\n                \\\"then call propose_plan again.\\\"\\n            )\\n            return Data(data={\\\"error\\\": error_msg, \\\"text\\\": error_msg})\\n\\n        _emit(\\\"propose_plan\\\", markdown=self.plan)\\n        marker = (\\n            \\\"Plan emitted to the user. STOP \u2014 do NOT call any other tools. \\\"\\n            \\\"The user's Continue/Dismiss reply arrives as the next user turn. \\\"\\n            \\\"On Continue, proceed with search_components / describe_component / build_flow. \\\"\\n            \\\"On Dismiss, the user will send refinement feedback \u2014 replan with propose_plan.\\\"\\n        )\\n        return Data(data={\\\"text\\\": marker, \\\"status\\\": \\\"awaiting_user_approval\\\"})\\n\\n\\nclass BuildFlowFromSpec(Component):\\n    display_name = \\\"Build Flow\\\"\\n    description = (\\n        \\\"Build a complete flow from a text spec. Use for building entire flows at once. \\\"\\n        \\\"For incremental changes, use add_component/connect_components instead.\\\"\\n    )\\n    icon = \\\"Workflow\\\"\\n    name = \\\"BuildFlowFromSpec\\\"\\n\\n    inputs = [\\n        MessageTextInput(\\n            name=\\\"spec\\\",\\n            display_name=\\\"Flow Spec\\\",\\n            info=(\\n                \\\"Text spec defining the flow. Format:\\\\n\\\"\\n                \\\"  name: My Flow\\\\n\\\"\\n                \\\"  nodes:\\\\n\\\"\\n                \\\"    A: ChatInput\\\\n\\\"\\n                \\\"    B: ChatOutput\\\\n\\\"\\n                \\\"  edges:\\\\n\\\"\\n                \\\"    A.message -> B.input_value\\\\n\\\"\\n                \\\"  config:\\\\n\\\"\\n                \\\"    A.input_value: hello\\\"\\n            ),\\n            required=True,\\n            tool_mode=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(name=\\\"flow_result\\\", display_name=\\\"Flow Result\\\", method=\\\"build_flow\\\"),\\n    ]\\n\\n    def build_flow(self) -> Data:\\n        emit_tool_start(\\\"build_flow\\\")\\n        existing = get_working_flow()\\n        if existing and existing.get(\\\"data\\\", {}).get(\\\"nodes\\\"):\\n            node_count = len(existing[\\\"data\\\"][\\\"nodes\\\"])\\n            logger.warning(\\\"build_flow called on non-empty canvas (%d nodes) -- replacing\\\", node_count)\\n\\n        # Pass the user-aware registry so user-registered Components\\n        # (created via Layer-2 validated generation) are addressable in\\n        # the spec by their class name.\\n        registry = _load_registry_user_aware()\\n        from .mutate_tools import (\\n            _model_providers_in_flow,\\n            _model_providers_in_flow_spec,\\n            _require_allowed_model_providers,\\n        )\\n\\n        try:\\n            from lfx.graph.flow_builder.spec import parse_flow_spec\\n\\n            parse_flow_spec(self.spec)\\n        except ValueError:\\n            # Preserve the builder's established invalid-spec error contract.\\n            configured_providers = set()\\n        else:\\n            configured_providers = _model_providers_in_flow_spec(self.spec, registry)\\n        try:\\n            _require_allowed_model_providers(configured_providers)\\n        except ModelProviderPolicyError as exc:\\n            logger.warning(\\\"build_flow blocked by model-provider policy: %s\\\", exc)\\n            return Data(data={\\\"error\\\": str(exc), \\\"text\\\": str(exc)})\\n\\n        result = build_flow_from_spec(self.spec, registry=registry)\\n        if \\\"error\\\" in result:\\n            error_msg = f\\\"Flow build failed: {result['error']}\\\"\\n            if \\\"details\\\" in result:\\n                error_msg += f\\\"\\\\nDetails: {result['details']}\\\"\\n            # Anti-churn: without this the agent restarts discovery after a\\n            # failed build and exhausts its recursion budget (loop_flow eval).\\n            error_msg += (\\n                \\\"\\\\nCorrect the spec using the error above and call build_flow again NOW \u2014 \\\"\\n                \\\"do NOT re-run search_components or describe_component for components \\\"\\n                \\\"you already inspected this turn.\\\"\\n            )\\n            logger.warning(\\\"build_flow_from_spec failed: %s\\\", result[\\\"error\\\"])\\n            result[\\\"text\\\"] = error_msg\\n        elif \\\"flow\\\" in result:\\n            try:\\n                _require_allowed_model_providers(_model_providers_in_flow(result[\\\"flow\\\"], registry))\\n            except ModelProviderPolicyError as exc:\\n                logger.warning(\\\"built flow blocked by model-provider policy: %s\\\", exc)\\n                return Data(data={\\\"error\\\": str(exc), \\\"text\\\": str(exc)})\\n            orphan_ids = _find_orphan_nodes(result[\\\"flow\\\"])\\n            # A single-component flow is a valid standalone build (no edges by\\n            # definition) \u2014 only reject when 2+ nodes exist but wiring is missing.\\n            if orphan_ids and result.get(\\\"node_count\\\", len(orphan_ids)) > 1:\\n                # Safety net for the prompt-level orphan ban: reject so the LLM\\n                # retries instead of rendering an unconnected component.\\n                error_msg = (\\n                    f\\\"Flow build rejected: orphan components with no edges: {orphan_ids}. \\\"\\n                    \\\"Either wire each component into the flow or remove it from the spec, \\\"\\n                    \\\"then call build_flow again.\\\"\\n                )\\n                logger.warning(\\\"build_flow_from_spec produced orphans: %s\\\", orphan_ids)\\n                return Data(data={\\\"error\\\": error_msg, \\\"text\\\": error_msg, \\\"orphans\\\": orphan_ids})\\n            result[\\\"text\\\"] = (\\n                f\\\"Flow '{result['name']}' built successfully \\\"\\n                f\\\"({result['node_count']} nodes, {result['edge_count']} edges).\\\"\\n            )\\n            # Mutate the working-flow dict in place: a ContextVar `.set()` rebind is\\n            # invisible to sibling tool contexts (run_flow would see the old flow).\\n            working = _ensure_working_flow()\\n            working.clear()\\n            working.update(result[\\\"flow\\\"])\\n            _emit(\\\"set_flow\\\", flow=result[\\\"flow\\\"])\\n        return Data(data=result)\\n\\n\\ndef _find_orphan_nodes(flow: dict) -> list[str]:\\n    \\\"\\\"\\\"Return the IDs of nodes that have no edges (incoming or outgoing).\\n\\n    A 1-node flow is treated as all-orphans by definition: a flow with no edges\\n    has no execution path. Callers can distinguish 1-node specs by inspecting\\n    the result's node_count if needed.\\n    \\\"\\\"\\\"\\n    data = flow.get(\\\"data\\\") or {}\\n    nodes = data.get(\\\"nodes\\\") or []\\n    edges = data.get(\\\"edges\\\") or []\\n\\n    connected: set[str] = set()\\n    for edge in edges:\\n        src = edge.get(\\\"source\\\")\\n        tgt = edge.get(\\\"target\\\")\\n        if src:\\n            connected.add(src)\\n        if tgt:\\n            connected.add(tgt)\\n\\n    orphans: list[str] = []\\n    for node in nodes:\\n        node_id = node.get(\\\"id\\\") or node.get(\\\"data\\\", {}).get(\\\"id\\\")\\n        if node_id and node_id not in connected:\\n            orphans.append(node_id)\\n    return orphans\\n\\n\\ndef _format_run_metrics(metrics: dict) -> str:\\n    \\\"\\\"\\\"Render run metrics as one human line the agent can repeat verbatim.\\n\\n    Always reports wall time; appends token usage only when an LLM was\\n    actually involved (total > 0), so non-LLM flows don't read \\\"0 tokens\\\".\\n    \\\"\\\"\\\"\\n    if not metrics:\\n        return \\\"\\\"\\n    duration = metrics.get(\\\"duration_seconds\\\") or 0\\n    parts = [f\\\"Ran in {duration:g}s\\\"]\\n    total = metrics.get(\\\"total_tokens\\\") or 0\\n    if total:\\n        in_tok = metrics.get(\\\"input_tokens\\\") or 0\\n        out_tok = metrics.get(\\\"output_tokens\\\") or 0\\n        parts.append(f\\\"used {total} tokens ({in_tok} in / {out_tok} out)\\\")\\n    return f\\\"({' \u00b7 '.join(parts)})\\\"\\n\\n\\nclass RunFlow(Component):\\n    \\\"\\\"\\\"Run the user's current canvas flow and return its result.\\n\\n    Executes the working flow exactly as it is on the canvas (honoring any\\n    unsaved assistant edits) with the components' currently-configured\\n    values \u2014 no input is invented. Vertex-build events are forwarded so the\\n    canvas animates like a normal Run, and the result text is returned to\\n    the agent so it can answer follow-up questions about it.\\n\\n    Decoupled from ``langflow`` via a late import (same pattern as\\n    ``_load_registry_user_aware``): ``lfx`` may run without the backend.\\n    \\\"\\\"\\\"\\n\\n    display_name = \\\"Run Flow\\\"\\n    description = (\\n        \\\"Execute the user's current flow on the canvas (with its configured values) and \\\"\\n        \\\"return the result. Use when the user asks to run/test/execute the flow or asks \\\"\\n        \\\"about what it produces. The canvas animates while it runs; the result comes back \\\"\\n        \\\"so you can discuss it. Do not invent inputs; run it as configured.\\\"\\n    )\\n    icon = \\\"Play\\\"\\n    name = \\\"RunFlow\\\"\\n\\n    inputs = [\\n        MessageTextInput(\\n            name=\\\"reason\\\",\\n            display_name=\\\"Reason\\\",\\n            info=\\\"Optional short note on why you are running the flow (does not change the run).\\\",\\n            required=False,\\n            tool_mode=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(name=\\\"run_result\\\", display_name=\\\"Run Result\\\", method=\\\"run_flow\\\"),\\n    ]\\n\\n    async def run_flow(self) -> Data:\\n        flow = _ensure_working_flow()\\n        nodes = (flow.get(\\\"data\\\") or {}).get(\\\"nodes\\\") or []\\n        if not nodes:\\n            msg = \\\"There is no flow on the canvas to run. Build or add components first.\\\"\\n            return Data(data={\\\"error\\\": msg, \\\"text\\\": msg})\\n\\n        try:\\n            from langflow.agentic.services.flow_run import run_working_flow\\n        except ImportError:\\n            msg = \\\"Flow execution is not available in this environment.\\\"\\n            return Data(data={\\\"error\\\": msg, \\\"text\\\": msg})\\n\\n        try:\\n            from langflow.agentic.services.user_components_context import current_user_id\\n\\n            user_id = current_user_id()\\n        except ImportError:\\n            user_id = None\\n\\n        # The run engine requires a valid UUID flow id (\\\"badly formed hexadecimal\\n        # UUID string\\\" otherwise); fall back to a fresh uuid4 when none persisted.\\n        flow_id = _current_flow_id_var.get() or str(uuid4())\\n\\n        # Model-less Agents get the assistant's verified credential, but a model the\\n        # user explicitly set must never be swapped (overwrite_existing_model=False).\\n        try:\\n            from langflow.agentic.services.agent_run_context import (\\n                current_agent_run_model,\\n                current_requested_agent_model,\\n            )\\n            from langflow.agentic.services.flow_preparation import inject_model_into_flow\\n\\n            requested = current_requested_agent_model() or {}\\n            req_provider = requested.get(\\\"provider\\\")\\n            req_model_name = requested.get(\\\"model_name\\\")\\n            run_model = current_agent_run_model() or {}\\n            run_provider = run_model.get(\\\"provider\\\")\\n            run_model_name = run_model.get(\\\"model_name\\\")\\n            if req_provider and req_model_name:\\n                # User explicitly named a model \u2014 enforce it on every Agent so the\\n                # canvas never shows the assistant's own runtime model instead.\\n                inject_model_into_flow(\\n                    flow,\\n                    req_provider,\\n                    req_model_name,\\n                    requested.get(\\\"api_key_var\\\"),\\n                    overwrite_existing_model=True,\\n                )\\n            elif run_provider and run_model_name and run_model.get(\\\"allow_configuration\\\", True):\\n                # No explicit request: only FILL an Agent that has no model with\\n                # the assistant's verified runtime model (preserve a set one).\\n                inject_model_into_flow(\\n                    flow,\\n                    run_provider,\\n                    run_model_name,\\n                    run_model.get(\\\"api_key_var\\\"),\\n                    overwrite_existing_model=False,\\n                )\\n        except (ImportError, ValueError) as exc:\\n            logger.warning(\\\"run_flow.verified_model_inject_skipped: %s\\\", exc)\\n\\n        result = await run_working_flow(flow_data=flow, flow_id=flow_id, user_id=user_id)\\n        if \\\"error\\\" in result:\\n            return Data(data={\\\"error\\\": result[\\\"error\\\"], \\\"text\\\": result[\\\"error\\\"]})\\n        # Deterministic \\\"flow actually ran\\\" signal the streaming generator uses to\\n        # force the built flow onto the canvas. Success-only: a failed run never claims it ran.\\n        _emit(\\\"flow_ran\\\", flow_id=flow_id)\\n        text = result.get(\\\"result\\\", \\\"\\\")\\n        metrics = result.get(\\\"metrics\\\") or {}\\n        summary = _format_run_metrics(metrics)\\n        # The LLM only reads `text`, so the performance summary must be inline;\\n        # `metrics` stays structured for programmatic use.\\n        text_with_metrics = f\\\"{text}\\\\n\\\\n{summary}\\\" if summary else text\\n        return Data(data={\\\"text\\\": text_with_metrics, \\\"result\\\": text, \\\"metrics\\\": metrics})\\n\\n\\nclass GenerateComponent(Component):\\n    \\\"\\\"\\\"Generate, validate and register a NEW custom Langflow component.\\n\\n    This is what lets ONE agent loop handle \\\"create a component that does X\\n    and use it in a flow\\\" without an intent router or phase orchestration:\\n    the agent calls this tool, then ``search_components`` finds the new\\n    component by class name and ``build_flow``/``add_component`` use it.\\n\\n    Wraps the full backend pipeline (LLM generation \u2192 security scan \u2192 code\\n    + runtime validation with retries \u2192 user-scoped registration). Lazily\\n    imports ``langflow`` (same decoupling as ``RunFlow``): ``lfx`` may run\\n    without the backend.\\n    \\\"\\\"\\\"\\n\\n    display_name = \\\"Generate Component\\\"\\n    description = (\\n        \\\"Create a brand-new custom Langflow component from a natural-language description. \\\"\\n        \\\"Use this when the user asks for a component/tool that does not exist yet. On success \\\"\\n        \\\"the component is validated and registered \u2014 then call search_components to find it by \\\"\\n        \\\"its class name and add it to the flow. Returns the generated component's class name.\\\"\\n    )\\n    icon = \\\"Wand2\\\"\\n    name = \\\"GenerateComponent\\\"\\n\\n    inputs = [\\n        MessageTextInput(\\n            name=\\\"spec\\\",\\n            display_name=\\\"Spec\\\",\\n            info=\\\"Natural-language spec of the component to create (what it takes and what it returns).\\\",\\n            required=True,\\n            tool_mode=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(name=\\\"result\\\", display_name=\\\"Result\\\", method=\\\"generate_component\\\"),\\n    ]\\n\\n    async def generate_component(self) -> Data:\\n        spec = (self.spec or \\\"\\\").strip()\\n        if not spec:\\n            msg = \\\"Describe the component to generate (what it takes as input and what it returns).\\\"\\n            return Data(data={\\\"error\\\": msg, \\\"text\\\": msg})\\n\\n        try:\\n            from langflow.agentic.services.assistant_service import execute_flow_with_validation\\n            from langflow.agentic.services.file_events import reset_file_events\\n            from langflow.agentic.services.flow_types import LANGFLOW_ASSISTANT_FLOW\\n        except ImportError:\\n            msg = \\\"Component generation is not available in this environment.\\\"\\n            return Data(data={\\\"error\\\": msg, \\\"text\\\": msg})\\n\\n        try:\\n            from langflow.agentic.services.agent_run_context import (\\n                current_agent_run_iterations,\\n                current_agent_run_model,\\n            )\\n            from langflow.agentic.services.user_components_context import current_user_id\\n\\n            user_id = current_user_id()\\n            model = current_agent_run_model() or {}\\n            iterations_limit = current_agent_run_iterations()\\n        except ImportError:\\n            user_id = None\\n            model = {}\\n            iterations_limit = None\\n\\n        # Ephemeral flow id keeps the sub-flow's tracing from logging\\n        # \\\"Invalid flow_id ... None\\\" and persisting under a sentinel.\\n        from lfx.mcp.tool_cache import reset_tool_cache\\n\\n        flow_id = str(uuid4())\\n\\n        # Without ITERATIONS_LIMIT the nested assistant keeps the default step\\n        # budget, defeating /iterations N for component_then_flow requests.\\n        nested_globals = {\\\"FLOW_ID\\\": flow_id}\\n        if iterations_limit is not None:\\n            nested_globals[\\\"ITERATIONS_LIMIT\\\"] = str(iterations_limit)\\n            logger.info(\\\"generate_component: nested subflow inherits step budget %s\\\", iterations_limit)\\n\\n        async def _isolated_generation() -> dict:\\n            # Fresh per-run state: the nested pipeline must neither steal the parent\\n            # loop's queued events nor wipe the canvas built this turn.\\n            isolate_flow_run_context()\\n            reset_tool_cache()\\n            reset_file_events()\\n            return await execute_flow_with_validation(\\n                flow_filename=LANGFLOW_ASSISTANT_FLOW,\\n                input_value=spec,\\n                global_variables=nested_globals,\\n                user_id=user_id,\\n                provider=model.get(\\\"provider\\\"),\\n                model_name=model.get(\\\"model_name\\\"),\\n                api_key_var=model.get(\\\"api_key_var\\\"),\\n                # The AGENT's prose, not a user turn: a guardrail component is specified\\n                # by naming the attacks it catches, which the injection regex rejected.\\n                trusted_source=True,\\n            )\\n\\n        # create_task copies the context: ContextVar writes inside it\\n        # (incl. isolate/reset above) never propagate back to the parent loop.\\n        result = await asyncio.create_task(_isolated_generation())\\n\\n        if result.get(\\\"validated\\\"):\\n            class_name = result.get(\\\"class_name\\\", \\\"\\\")\\n            text = (\\n                f\\\"Component '{class_name}' created, validated and registered. \\\"\\n                f\\\"Now call search_components to find '{class_name}' and add it to the flow.\\\"\\n            )\\n            return Data(data={\\\"text\\\": text, \\\"class_name\\\": class_name, \\\"component_code\\\": result.get(\\\"component_code\\\")})\\n\\n        err = result.get(\\\"validation_error\\\") or result.get(\\\"result\\\") or \\\"Component generation failed.\\\"\\n        # Structured failure signal (not prose the agent can bury): assistant_service\\n        # drains it into a validation_failed progress event for the user.\\n        try:\\n            from langflow.agentic.services.component_events import emit_component_generation_failed\\n\\n            emit_component_generation_failed(\\n                error=err,\\n                class_name=result.get(\\\"class_name\\\"),\\n                component_code=result.get(\\\"component_code\\\"),\\n            )\\n        except ImportError:\\n            pass\\n        return Data(data={\\\"error\\\": err, \\\"text\\\": err})\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/mcp/flow_builder_tools/template_tools.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5083442a2a695d564f6ea4ce3829eda97a575e363a4f9e5becc5ec4f6ff17a67\",\"content\":\"\\\"\\\"\\\"Starter-template tools for the flow-builder assistant.\\n\\nLet the agent instantiate a curated starter project in ONE tool call\\ninstead of a search \u2192 describe \u2192 build loop. The template's flow JSON is\\nloaded server-side and pushed through the same ``set_flow`` proposal gate\\nas ``build_flow`` \u2014 it never enters the LLM context; the tool returns only\\na compact summary (name, node count, node types).\\n\\nDecoupled from ``langflow`` via late imports (``lfx`` ships without the\\nbackend), the same pattern as ``RunFlow`` / ``GenerateComponent``.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport copy\\nfrom typing import Any\\n\\nfrom lfx.custom import Component\\nfrom lfx.io import MessageTextInput, Output\\nfrom lfx.log.logger import logger\\nfrom lfx.schema import Data\\n\\nfrom ._state import _emit, _ensure_working_flow, emit_tool_start\\n\\n_DESCRIPTION_PREVIEW_CHARS = 140\\n\\n_TEMPLATES_UNAVAILABLE = \\\"Starter templates are not available in this environment.\\\"\\n\\n\\ndef _load_starter_templates(fields: list[str]) -> list[dict[str, Any]] | None:\\n    \\\"\\\"\\\"Return the starter templates via langflow, or None when it isn't installed.\\\"\\\"\\\"\\n    try:\\n        from langflow.agentic.utils.template_search import list_templates as lf_list_templates\\n    except ImportError:\\n        return None\\n    return lf_list_templates(fields=fields)\\n\\n\\ndef _one_line_description(description: str | None) -> str:\\n    text = (description or \\\"\\\").strip().splitlines()[0] if (description or \\\"\\\").strip() else \\\"\\\"\\n    if len(text) > _DESCRIPTION_PREVIEW_CHARS:\\n        text = text[: _DESCRIPTION_PREVIEW_CHARS - 1].rstrip() + \\\"\u2026\\\"\\n    return text\\n\\n\\ndef _node_types(flow: dict[str, Any]) -> list[str]:\\n    \\\"\\\"\\\"Sorted unique component types in a flow dict.\\\"\\\"\\\"\\n    nodes = (flow.get(\\\"data\\\") or {}).get(\\\"nodes\\\") or []\\n    types = {(node.get(\\\"data\\\") or {}).get(\\\"type\\\", \\\"\\\") for node in nodes if isinstance(node, dict)}\\n    return sorted(t for t in types if t)\\n\\n\\nclass ListTemplates(Component):\\n    display_name = \\\"List Templates\\\"\\n    description = \\\"List the available starter templates (name + one-line description).\\\"\\n    icon = \\\"LayoutTemplate\\\"\\n    name = \\\"ListTemplates\\\"\\n\\n    inputs = [\\n        MessageTextInput(\\n            name=\\\"reason\\\",\\n            display_name=\\\"Reason\\\",\\n            info=\\\"Optional short note on why you are listing templates (does not change anything).\\\",\\n            required=False,\\n            tool_mode=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(name=\\\"result\\\", display_name=\\\"Templates\\\", method=\\\"list_templates\\\"),\\n    ]\\n\\n    def list_templates(self) -> Data:\\n        # Pure read of on-disk JSON metadata \u2014 cache per request like the\\n        # other read tools so repeated planning turns don't re-walk the dir.\\n        from lfx.mcp.tool_cache import cached_tool_call\\n\\n        def producer() -> Data:\\n            templates = _load_starter_templates(fields=[\\\"name\\\", \\\"description\\\"])\\n            if templates is None:\\n                return Data(data={\\\"error\\\": _TEMPLATES_UNAVAILABLE, \\\"text\\\": _TEMPLATES_UNAVAILABLE})\\n            entries = [\\n                {\\\"name\\\": t.get(\\\"name\\\", \\\"\\\"), \\\"description\\\": _one_line_description(t.get(\\\"description\\\"))}\\n                for t in templates\\n                if t.get(\\\"name\\\")\\n            ]\\n            entries.sort(key=lambda e: e[\\\"name\\\"])\\n            text = \\\"\\\\n\\\".join(f\\\"- {e['name']}: {e['description']}\\\" for e in entries)\\n            return Data(data={\\\"templates\\\": entries, \\\"count\\\": len(entries), \\\"text\\\": text})\\n\\n        return cached_tool_call(\\\"list_templates\\\", {}, producer)\\n\\n\\nclass UseTemplate(Component):\\n    display_name = \\\"Use Template\\\"\\n    description = (\\n        \\\"Instantiate a starter template by name as the proposed flow (same review gate as \\\"\\n        \\\"build_flow \u2014 the user approves before the canvas changes). Returns a compact \\\"\\n        \\\"summary, never the flow JSON. Use list_templates to see valid names.\\\"\\n    )\\n    icon = \\\"LayoutTemplate\\\"\\n    name = \\\"UseTemplate\\\"\\n\\n    inputs = [\\n        MessageTextInput(\\n            name=\\\"template_name\\\",\\n            display_name=\\\"Template Name\\\",\\n            info=\\\"Exact starter template name (case-insensitive), e.g. 'Memory Chatbot'.\\\",\\n            required=True,\\n            tool_mode=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(name=\\\"result\\\", display_name=\\\"Result\\\", method=\\\"use_template\\\"),\\n    ]\\n\\n    def use_template(self) -> Data:\\n        requested = (self.template_name or \\\"\\\").strip()\\n        emit_tool_start(\\\"use_template\\\", template_name=requested)\\n        if not requested:\\n            msg = \\\"template_name is required. Call list_templates to see the available names.\\\"\\n            return Data(data={\\\"error\\\": msg, \\\"text\\\": msg})\\n\\n        # Same per-request memoization as list_templates \u2014 retries and\\n        # multi-template turns must not re-walk every starter JSON.\\n        from lfx.mcp.tool_cache import cached_tool_call\\n\\n        templates = cached_tool_call(\\n            \\\"load_templates_full\\\",\\n            {},\\n            lambda: _load_starter_templates(fields=[\\\"name\\\", \\\"description\\\", \\\"data\\\"]),\\n        )\\n        if templates is None:\\n            return Data(data={\\\"error\\\": _TEMPLATES_UNAVAILABLE, \\\"text\\\": _TEMPLATES_UNAVAILABLE})\\n\\n        wanted = requested.casefold()\\n        template = next((t for t in templates if (t.get(\\\"name\\\") or \\\"\\\").strip().casefold() == wanted), None)\\n        if template is None:\\n            available = \\\", \\\".join(sorted(t.get(\\\"name\\\", \\\"\\\") for t in templates if t.get(\\\"name\\\")))\\n            msg = f\\\"Unknown template {requested!r}. Available templates: {available}\\\"\\n            logger.warning(\\\"use_template: unknown template %r\\\", requested)\\n            return Data(data={\\\"error\\\": msg, \\\"text\\\": msg})\\n\\n        # Deep copy so the cached template dict never aliases the working\\n        # flow, which later tools mutate in place.\\n        flow_data = copy.deepcopy(template.get(\\\"data\\\") or {})\\n        nodes = flow_data.get(\\\"nodes\\\") or []\\n        if not nodes:\\n            msg = f\\\"Template {template.get('name')!r} has no components and cannot be instantiated.\\\"\\n            logger.warning(\\\"use_template: empty template %r\\\", requested)\\n            return Data(data={\\\"error\\\": msg, \\\"text\\\": msg})\\n\\n        flow = {\\n            \\\"name\\\": template.get(\\\"name\\\", requested),\\n            \\\"description\\\": template.get(\\\"description\\\", \\\"\\\"),\\n            \\\"data\\\": flow_data,\\n        }\\n        # Same proposal gate as build_flow: mutate the working flow in place (a\\n        # ContextVar rebind is invisible to sibling tools), then emit set_flow.\\n        working = _ensure_working_flow()\\n        working.clear()\\n        working.update(flow)\\n        _emit(\\\"set_flow\\\", flow=flow)\\n\\n        node_types = _node_types(flow)\\n        edge_count = len(flow_data.get(\\\"edges\\\") or [])\\n        text = (\\n            f\\\"Template '{flow['name']}' instantiated as the proposed flow \\\"\\n            f\\\"({len(nodes)} nodes, {edge_count} edges; components: {', '.join(node_types)}). \\\"\\n            \\\"It is pending the user's review \u2014 do not rebuild it.\\\"\\n        )\\n        return Data(\\n            data={\\n                \\\"text\\\": text,\\n                \\\"template\\\": flow[\\\"name\\\"],\\n                \\\"node_count\\\": len(nodes),\\n                \\\"edge_count\\\": edge_count,\\n                \\\"node_types\\\": node_types,\\n            }\\n        )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/memory/flow_context.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8e27d2591fbf1a9a209da893b109391e3d7831ddbc54817cb12abffa1dcb3bfa\",\"content\":\"\\\"\\\"\\\"Ambient flow-scope for chat-memory retrieval (defense-in-depth for old saved flows).\\n\\nLangflow executes the *frozen* component ``code`` embedded in each saved flow, not the installed\\nlibrary version (see ``lfx.interface.initialize.loading.instantiate_class`` ->\\n``eval_custom_component_code``). A flow saved before PR #13087 therefore carries the old\\n``MemoryComponent.retrieve_messages`` that calls ``aget_messages`` WITHOUT ``flow_id`` and leaks\\nchat history across flows on a colliding ``session_id`` (issue #13059) \u2014 even on a patched server,\\nbecause the fix only updated the library default, not code already frozen into saved flows.\\n\\nThis ContextVar carries the executing graph's ``flow_id`` so ``aget_messages`` can default the\\nscope when a caller omits it. It is bound only for the duration of a component's execution\\n(``get_instance_results``) and reset afterward, so:\\n\\n* callers that pass ``flow_id`` explicitly are unaffected (the default applies only when ``None``),\\n* callers outside a graph run see an unset ContextVar and thus identical, legacy behavior.\\n\\nThis is not new semantics \u2014 it is the PR #13087 flow-scoping contract, applied at the platform\\nfunction the frozen code calls instead of inside the (unchangeable) frozen code.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport contextvars\\nfrom typing import Any\\nfrom uuid import NAMESPACE_DNS, UUID, uuid5\\n\\n# Fixed namespace for turning an opaque (non-UUID) serving-plane end-user id into a\\n# stable UUID for the UUID-typed ``message.user_id`` column. ``uuid5`` is a pure\\n# function of (namespace, name), so the same end-user string always maps to the same\\n# UUID \u2014 across processes and pods \u2014 which is what makes the derived owner id usable\\n# as a durable, cross-pod query key. Any consumer that queries ``message.user_id`` by\\n# a raw end-user id (e.g. the Monitor API filter) MUST derive it through\\n# :func:`derive_message_owner_uuid` so the query matches what the write stamped.\\n_END_USER_UUID_NAMESPACE = uuid5(NAMESPACE_DNS, \\\"end-user.serving.langflow.ai\\\")\\n\\n_current_flow_id: contextvars.ContextVar[str | UUID | None] = contextvars.ContextVar(\\n    \\\"lfx_current_flow_id\\\",\\n    default=None,\\n)\\n\\n\\ndef get_current_flow_id() -> str | UUID | None:\\n    \\\"\\\"\\\"Return the ``flow_id`` of the graph currently executing, or ``None`` outside a graph run.\\\"\\\"\\\"\\n    return _current_flow_id.get()\\n\\n\\ndef set_current_flow_id(flow_id: str | UUID | None) -> contextvars.Token[str | UUID | None]:\\n    \\\"\\\"\\\"Bind *flow_id* as the ambient flow scope for the current async task / thread.\\\"\\\"\\\"\\n    return _current_flow_id.set(flow_id)\\n\\n\\ndef reset_current_flow_id(token: contextvars.Token[str | UUID | None]) -> None:\\n    \\\"\\\"\\\"Restore the previous ambient flow scope.\\\"\\\"\\\"\\n    _current_flow_id.reset(token)\\n\\n\\n# Ambient \\\"may this run persist chat memory?\\\" flag. Bound per component execution\\n# (next to the flow-id scope) from ``graph.persist_messages`` so ``astore_message``\\n# can skip the DB write for anonymous serving requests, which must run ephemerally.\\n# Defaults True so every existing path \u2014 anything not opting out \u2014 persists exactly\\n# as before.\\n_messages_persist: contextvars.ContextVar[bool] = contextvars.ContextVar(\\n    \\\"lfx_messages_persist\\\",\\n    default=True,\\n)\\n\\n\\ndef should_persist_messages() -> bool:\\n    \\\"\\\"\\\"Return whether the current run may persist chat memory (True outside a run).\\\"\\\"\\\"\\n    return _messages_persist.get()\\n\\n\\ndef set_messages_persist(persist: bool) -> contextvars.Token[bool]:  # noqa: FBT001\\n    \\\"\\\"\\\"Bind the message-persistence flag for the current async task / thread.\\\"\\\"\\\"\\n    return _messages_persist.set(persist)\\n\\n\\ndef reset_messages_persist(token: contextvars.Token[bool]) -> None:\\n    \\\"\\\"\\\"Restore the previous message-persistence flag.\\\"\\\"\\\"\\n    _messages_persist.reset(token)\\n\\n\\ndef _clean_identity(value: Any) -> str | UUID | None:\\n    \\\"\\\"\\\"Return *value* unless it is missing or a placeholder (\\\"None\\\"/\\\"null\\\"/empty).\\n\\n    ``PlaceholderGraph`` stringifies a missing user as ``\\\"None\\\"``, so a missing owner\\n    must read as *no owner*, not as a user literally named \\\"None\\\" (which would either\\n    over-filter retrieval to zero rows or mint a spurious namespace).\\n    \\\"\\\"\\\"\\n    if value is None:\\n        return None\\n    cleaned = str(value).strip()\\n    if not cleaned or cleaned.lower() in {\\\"none\\\", \\\"null\\\"}:\\n        return None\\n    return value\\n\\n\\ndef _identity_candidates(graph: Any) -> list[str | UUID]:\\n    \\\"\\\"\\\"The graph's user ids in preference order: end user first, then executing user.\\n\\n    ``graph.end_user_id`` is the serving-plane end-user identity (present only when a\\n    serving entry point set it); ``graph.user_id`` is the executing user \u2014 the service\\n    account on the serving plane, the human on the editor plane. Placeholder/empty\\n    values are dropped. Values are returned with their original type.\\n    \\\"\\\"\\\"\\n    candidates: list[str | UUID] = []\\n    for attr in (\\\"end_user_id\\\", \\\"user_id\\\"):\\n        value = _clean_identity(getattr(graph, attr, None))\\n        if value is not None:\\n            candidates.append(value)\\n    return candidates\\n\\n\\ndef resolve_effective_user_id(graph: Any) -> str | UUID | None:\\n    \\\"\\\"\\\"The user id this run scopes non-DB per-user state to (e.g. agent file writes).\\n\\n    Prefers the serving-plane end-user id, else the executing user id. Returns the raw\\n    value (an opaque header string need not be a UUID), or ``None`` when neither is a\\n    real id. Use :func:`resolve_message_owner_id` instead for the UUID-typed\\n    ``message.user_id`` column.\\n    \\\"\\\"\\\"\\n    candidates = _identity_candidates(graph)\\n    return candidates[0] if candidates else None\\n\\n\\ndef derive_message_owner_uuid(end_user_id: str | UUID) -> UUID:\\n    \\\"\\\"\\\"The UUID a serving-plane end-user id maps to in ``message.user_id``.\\n\\n    A UUID-shaped id is used directly (the gateway contract says the id is a UUID); an\\n    opaque non-UUID id is turned into a *stable* UUID via ``uuid5`` so per-user rows\\n    stay separated in the UUID-typed column even when a gateway sends a non-UUID id.\\n    The mapping is deterministic across processes and pods, so any consumer querying\\n    ``message.user_id`` by a raw end-user id (e.g. the Monitor API filter) must resolve\\n    it through this same function for the predicate to match the stored owner.\\n    \\\"\\\"\\\"\\n    coerced = coerce_flow_id(end_user_id)\\n    return coerced if coerced is not None else uuid5(_END_USER_UUID_NAMESPACE, str(end_user_id))\\n\\n\\ndef resolve_message_owner_id(graph: Any) -> UUID | None:\\n    \\\"\\\"\\\"The UUID to stamp on / query ``message.user_id`` for this run (write == read).\\n\\n    ``message.user_id`` is UUID-typed. The serving-plane end-user id wins when present:\\n    it is mapped to a stable UUID via :func:`derive_message_owner_uuid` (direct when\\n    UUID-shaped, deterministically derived otherwise) so per-user separation survives a\\n    non-UUID gateway id and never crashes the write or raises on retrieval. With no end\\n    user, the executing (service-account / human) user id is used \u2014 it is already a\\n    UUID, so it is coerced only, never derived (a non-UUID there means no real owner and\\n    yields ``None`` \u2192 unscoped, as before). Both the write path\\n    (``Component._store_message``) and the read path (``_safe_graph_user_id``) resolve\\n    through this one function so the stored owner and the retrieval predicate agree.\\n    \\\"\\\"\\\"\\n    end_user = _clean_identity(getattr(graph, \\\"end_user_id\\\", None))\\n    if end_user is not None:\\n        return derive_message_owner_uuid(end_user)\\n    executing = _clean_identity(getattr(graph, \\\"user_id\\\", None))\\n    if executing is not None:\\n        return coerce_flow_id(executing)\\n    return None\\n\\n\\ndef coerce_flow_id(flow_id: str | UUID | None) -> UUID | None:\\n    \\\"\\\"\\\"Coerce an ambient ``flow_id`` (usually ``graph.flow_id``, a ``str``) to ``UUID``.\\n\\n    Returns ``None`` when the value is missing or not a valid UUID (synthetic/test graph ids),\\n    so retrieval degrades to the previous unscoped behavior rather than crashing.\\n    \\\"\\\"\\\"\\n    if flow_id is None or flow_id == \\\"\\\":\\n        return None\\n    if isinstance(flow_id, UUID):\\n        return flow_id\\n    try:\\n        return UUID(str(flow_id))\\n    except (ValueError, TypeError, AttributeError):\\n        return None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/schema/graph.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9253c6b7f464ee02d1e02a7c1f8fd60d790ef4bc8bd3cde01efb1857aa648057\",\"content\":\"from typing import Any\\n\\nfrom pydantic import BaseModel, Field, RootModel\\n\\nfrom lfx.schema.schema import InputType\\n\\n\\nclass InputValue(BaseModel):\\n    components: list[str] | None = []\\n    input_value: str | None = None\\n    type: InputType | None = Field(\\n        \\\"any\\\",\\n        description=\\\"Defines on which components the input value should be applied. \\\"\\n        \\\"'any' applies to all input components.\\\",\\n    )\\n\\n\\nclass Tweaks(RootModel):\\n    root: dict[str, bool | int | float | str | dict[str, Any]] = Field(\\n        description=\\\"A dictionary of tweaks to adjust the flow's execution. \\\"\\n        \\\"Allows customizing flow behavior dynamically. \\\"\\n        \\\"All tweaks are overridden by the input values.\\\",\\n    )\\n    model_config = {\\n        \\\"json_schema_extra\\\": {\\n            \\\"examples\\\": [\\n                {\\n                    \\\"parameter_name\\\": \\\"value\\\",\\n                    \\\"stream\\\": False,\\n                    \\\"temperature\\\": 0.7,\\n                    \\\"Component Name\\\": {\\\"parameter_name\\\": \\\"value\\\"},\\n                    \\\"component_id\\\": {\\\"parameter_name\\\": \\\"value\\\"},\\n                }\\n            ]\\n        }\\n    }\\n\\n    # This should behave like a dict\\n    def __getitem__(self, key):\\n        return self.root[key]\\n\\n    def __setitem__(self, key, value) -> None:\\n        self.root[key] = value\\n\\n    def __delitem__(self, key) -> None:\\n        del self.root[key]\\n\\n    def items(self):\\n        return self.root.items()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/schema/workflow.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3094110563be19d9510aead2838e7d6729d8c78c4fddce5f52948e998554335f\",\"content\":\"\\\"\\\"\\\"Workflow execution schemas for V2 API.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom datetime import datetime, timezone\\nfrom enum import Enum\\nfrom typing import Annotated, Any, Literal\\nfrom uuid import UUID\\n\\nfrom pydantic import BaseModel, BeforeValidator, ConfigDict, Field, StringConstraints, computed_field, model_validator\\n\\nfrom lfx.schema.validators import null_check_validator, uuid_validator\\n\\n# Length-only bounds on body-transported globals so one field can't bloat the request.\\nGLOBAL_KEY_MAX_LEN = 256\\nGLOBAL_VALUE_MAX_LEN = 64 * 1024\\n\\nGlobalVarKey = Annotated[str, StringConstraints(min_length=1, max_length=GLOBAL_KEY_MAX_LEN)]\\nGlobalVarValue = Annotated[str, StringConstraints(max_length=GLOBAL_VALUE_MAX_LEN)]\\n\\n# Bounds on the unauthenticated public-flow request, so an anonymous caller\\n# can't post arbitrarily large strings that are held in memory and persisted to\\n# MessageTable. input_value is a chat message (same 64 KB ceiling as a global\\n# variable value); session_id is namespaced under the visitor's virtual flow id,\\n# so a key-sized bound is ample.\\nPublicInputValue = Annotated[str, StringConstraints(max_length=GLOBAL_VALUE_MAX_LEN)]\\nPublicSessionId = Annotated[str, StringConstraints(max_length=GLOBAL_KEY_MAX_LEN)]\\n\\n\\nclass JobStatus(str, Enum):\\n    \\\"\\\"\\\"Job execution status.\\\"\\\"\\\"\\n\\n    QUEUED = \\\"queued\\\"\\n    IN_PROGRESS = \\\"in_progress\\\"\\n    COMPLETED = \\\"completed\\\"\\n    FAILED = \\\"failed\\\"\\n    CANCELLED = \\\"cancelled\\\"\\n    TIMED_OUT = \\\"timed_out\\\"\\n    SUSPENDED = \\\"suspended\\\"\\n\\n\\nJobId = Annotated[\\n    str | UUID,\\n    BeforeValidator(lambda v: null_check_validator(v, message=\\\"job_id is required\\\")),\\n    BeforeValidator(lambda v: uuid_validator(v, message=\\\"Invalid job_id, must be a UUID\\\")),\\n]\\n\\n\\nclass ErrorDetail(BaseModel):\\n    \\\"\\\"\\\"Error detail schema.\\\"\\\"\\\"\\n\\n    error: str\\n    code: str | None = None\\n    details: dict[str, Any] | None = None\\n\\n\\nclass ComponentOutput(BaseModel):\\n    \\\"\\\"\\\"Component output schema.\\\"\\\"\\\"\\n\\n    type: str = Field(..., description=\\\"Type of the component output (e.g., 'message', 'data', 'tool', 'text')\\\")\\n    status: JobStatus\\n    display_name: str | None = Field(\\n        default=None,\\n        description=\\\"Human-readable component name. The stable component id remains the ``outputs`` dict key.\\\",\\n    )\\n    content: Any | None = None\\n    metadata: dict[str, Any] | None = None\\n\\n\\nclass OutputEvent(ComponentOutput):\\n    \\\"\\\"\\\"A single component's output, as emitted on the ``langflow`` stream protocol.\\n\\n    The streaming counterpart of a sync ``outputs[id]`` entry: the same\\n    ``ComponentOutput`` payload plus ``component_id`` (which sync carries as the\\n    dict key). Subclassing keeps the shared fields from drifting, so one parser\\n    reads ``type``/``status``/``display_name``/``content``/``metadata`` off both the\\n    sync ``outputs`` map and the stream ``output`` events.\\n    \\\"\\\"\\\"\\n\\n    component_id: str = Field(..., description=\\\"Stable component id that produced this output.\\\")\\n\\n\\nclass OutputReason(str, Enum):\\n    \\\"\\\"\\\"Why ``WorkflowOutput.text`` resolved the way it did.\\n\\n    Mirrors the LLM-domain ``finish_reason`` / ``stop_reason`` convention: a\\n    machine-readable enum explaining the disposition of the answer, distinct from\\n    the lifecycle ``status``.\\n    \\\"\\\"\\\"\\n\\n    SINGLE = \\\"single\\\"  # exactly one text answer; ``text`` holds it\\n    MULTIPLE = \\\"multiple\\\"  # two or more text answers; read ``outputs`` and pick\\n    NONE = \\\"none\\\"  # no text channel at all (e.g. a data-only flow)\\n    NON_STRING = \\\"non_string\\\"  # a text channel exists but its content isn't a string\\n    FAILED = \\\"failed\\\"  # the run failed before producing an answer\\n\\n\\nclass WorkflowOutput(BaseModel):\\n    \\\"\\\"\\\"The run's primary text answer plus the reason it resolved that way.\\\"\\\"\\\"\\n\\n    reason: OutputReason = Field(\\n        description=(\\n            \\\"Why ``text`` is or isn't populated. ``single`` means ``text`` holds the answer; \\\"\\n            \\\"``multiple`` / ``none`` / ``non_string`` / ``failed`` mean ``text`` is null and name \\\"\\n            \\\"why, so callers never have to guess.\\\"\\n        )\\n    )\\n    text: str | None = Field(\\n        default=None,\\n        description=\\\"The run's text answer. Set only when ``reason`` is ``single``. Empty string is a valid answer.\\\",\\n    )\\n    source: str | None = Field(\\n        default=None,\\n        description=\\\"Component id that produced ``text``. Set only when ``reason`` is ``single``.\\\",\\n    )\\n\\n\\nclass WorkflowExecutionRequest(BaseModel):\\n    \\\"\\\"\\\"Request schema for workflow execution.\\\"\\\"\\\"\\n\\n    background: bool = False\\n    stream: bool = False\\n    flow_id: str\\n    inputs: dict[str, Any] | None = Field(\\n        None, description=\\\"Component-specific inputs in flat format: 'component_id.param_name': value\\\"\\n    )\\n    globals: dict[GlobalVarKey, GlobalVarValue] = Field(\\n        default_factory=dict,\\n        description=(\\n            \\\"Request-level global variables made available to workflow components. \\\"\\n            \\\"Keys may use any printable string up to \\\"\\n            f\\\"{GLOBAL_KEY_MAX_LEN} chars; values are capped at \\\"\\n            f\\\"{GLOBAL_VALUE_MAX_LEN} chars. Body globals always win over the \\\"\\n            \\\"legacy ``X-LANGFLOW-GLOBAL-VAR-*`` headers. Honored in sync mode; \\\"\\n            \\\"ignored for stream/background modes.\\\"\\n        ),\\n    )\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def validate_execution_mode(self) -> WorkflowExecutionRequest:\\n        if self.background and self.stream:\\n            err_msg = \\\"Both 'background' and 'stream' cannot be True\\\"\\n            raise ValueError(err_msg)\\n        return self\\n\\n    model_config = ConfigDict(\\n        json_schema_extra={\\n            \\\"examples\\\": [\\n                {\\n                    \\\"background\\\": False,\\n                    \\\"stream\\\": False,\\n                    \\\"flow_id\\\": \\\"flow_67ccd2be17f0819081ff3bb2cf6508e60bb6a6b452d3795b\\\",\\n                    \\\"inputs\\\": {\\n                        \\\"ChatInput-abc.input_value\\\": \\\"Hello, how can you help me today?\\\",\\n                        \\\"ChatInput-abc.session_id\\\": \\\"session-123\\\",\\n                        \\\"LLM-xyz.temperature\\\": 0.7,\\n                        \\\"LLM-xyz.max_tokens\\\": 100,\\n                        \\\"OpenSearch-def.opensearch_url\\\": \\\"https://opensearch:9200\\\",\\n                    },\\n                    \\\"globals\\\": {\\n                        \\\"FILENAME\\\": \\\"relatorio-final.pdf\\\",\\n                        \\\"OWNER_NAME\\\": \\\"Jose\\\",\\n                    },\\n                },\\n                {\\n                    \\\"background\\\": True,\\n                    \\\"stream\\\": False,\\n                    \\\"flow_id\\\": \\\"flow_67ccd2be17f0819081ff3bb2cf6508e60bb6a6b452d3795b\\\",\\n                    \\\"inputs\\\": {\\n                        \\\"ChatInput-abc.input_value\\\": \\\"Process this in the background\\\",\\n                    },\\n                },\\n                {\\n                    \\\"background\\\": False,\\n                    \\\"stream\\\": True,\\n                    \\\"flow_id\\\": \\\"flow_67ccd2be17f0819081ff3bb2cf6508e60bb6a6b452d3795b\\\",\\n                    \\\"inputs\\\": {\\n                        \\\"ChatInput-abc.input_value\\\": \\\"Stream this conversation\\\",\\n                    },\\n                },\\n            ]\\n        },\\n        extra=\\\"forbid\\\",\\n    )\\n\\n\\nclass WorkflowMode(str, Enum):\\n    \\\"\\\"\\\"Execution mode for a v2 workflow run.\\\"\\\"\\\"\\n\\n    SYNC = \\\"sync\\\"\\n    STREAM = \\\"stream\\\"\\n    BACKGROUND = \\\"background\\\"\\n\\n\\nclass WorkflowRunRequest(BaseModel):\\n    \\\"\\\"\\\"Request schema for ``POST /api/v2/workflows`` (v2 native body).\\n\\n    First-class fields for everything callers actually configure when running a\\n    flow. Streaming protocol is selected by ``stream_protocol``; the endpoint\\n    validates it against the live adapter registry and returns 422 with the\\n    available list when unknown.\\n    \\\"\\\"\\\"\\n\\n    flow_id: str = Field(..., description=\\\"UUID of the flow to run.\\\")\\n    input_value: str = Field(\\\"\\\", description=\\\"Chat-style input value.\\\")\\n    tweaks: dict[str, Any] = Field(\\n        default_factory=dict,\\n        description=\\\"Per-component parameter overrides keyed by component id.\\\",\\n    )\\n    session_id: str | None = Field(\\n        None,\\n        description=\\\"When set, message memory and chat history scope to this session.\\\",\\n    )\\n    mode: WorkflowMode = Field(\\n        WorkflowMode.SYNC,\\n        description=(\\n            \\\"Execution mode. ``sync`` runs inline and returns the aggregated \\\"\\n            \\\"response; ``stream`` returns SSE; ``background`` queues a job.\\\"\\n        ),\\n    )\\n    stream_protocol: str = Field(\\n        \\\"langflow\\\",\\n        description=(\\n            \\\"Wire protocol for streaming events. Defaults to ``langflow`` \\\"\\n            \\\"(raw EventManager payloads). ``agui`` emits AG-UI events. Unknown \\\"\\n            \\\"values return 422 with the available list. Ignored when mode=sync.\\\"\\n        ),\\n    )\\n    data: dict[str, Any] | None = Field(\\n        None,\\n        description=(\\n            \\\"Optional live-canvas override of the flow's nodes/edges; takes priority over the saved flow data.\\\"\\n        ),\\n    )\\n    files: list[str] | None = Field(\\n        None,\\n        description=\\\"Optional list of pre-uploaded file paths to attach to the run.\\\",\\n    )\\n    start_component_id: str | None = Field(None, description=\\\"Partial-run start component id.\\\")\\n    stop_component_id: str | None = Field(None, description=\\\"Partial-run stop component id.\\\")\\n    output_ids: list[str] | None = Field(\\n        None,\\n        description=(\\n            \\\"Component ids of the outputs you want as the answer (sync mode). When set, \\\"\\n            \\\"``output.text`` resolves among only these, so naming one text output makes \\\"\\n            \\\"``output.reason`` deterministic on multi-output flows. The full ``outputs`` \\\"\\n            \\\"map is still returned. Ids must be outputs of this flow or the request is \\\"\\n            \\\"rejected before the flow runs. Ignored for stream/background modes.\\\"\\n        ),\\n    )\\n    globals: dict[GlobalVarKey, GlobalVarValue] = Field(\\n        default_factory=dict,\\n        description=(\\n            \\\"Request-level global variables made available to workflow components. \\\"\\n            \\\"Keys may use any printable string up to \\\"\\n            f\\\"{GLOBAL_KEY_MAX_LEN} chars; values are capped at \\\"\\n            f\\\"{GLOBAL_VALUE_MAX_LEN} chars. Body globals always win over the \\\"\\n            \\\"legacy ``X-LANGFLOW-GLOBAL-VAR-*`` headers. Honored in sync mode; \\\"\\n            \\\"ignored for stream/background modes.\\\"\\n        ),\\n    )\\n    idempotency_key: str | None = Field(\\n        None,\\n        description=(\\n            \\\"Optional client-supplied key that dedupes background submits. Two \\\"\\n            \\\"background runs with the same key return the same job_id instead of \\\"\\n            \\\"queuing duplicate work. Ignored for sync/stream modes.\\\"\\n        ),\\n        max_length=255,\\n    )\\n\\n    model_config = ConfigDict(\\n        extra=\\\"forbid\\\",\\n        json_schema_extra={\\n            \\\"examples\\\": [\\n                {\\n                    \\\"flow_id\\\": \\\"67ccd2be-17f0-8190-81ff-3bb2cf6508e6\\\",\\n                    \\\"input_value\\\": \\\"Hello, how can you help me today?\\\",\\n                },\\n                {\\n                    \\\"flow_id\\\": \\\"67ccd2be-17f0-8190-81ff-3bb2cf6508e6\\\",\\n                    \\\"input_value\\\": \\\"Stream this conversation\\\",\\n                    \\\"mode\\\": \\\"stream\\\",\\n                },\\n                {\\n                    \\\"flow_id\\\": \\\"67ccd2be-17f0-8190-81ff-3bb2cf6508e6\\\",\\n                    \\\"input_value\\\": \\\"Drive the canvas\\\",\\n                    \\\"mode\\\": \\\"stream\\\",\\n                    \\\"stream_protocol\\\": \\\"agui\\\",\\n                    \\\"session_id\\\": \\\"session-123\\\",\\n                },\\n                {\\n                    \\\"flow_id\\\": \\\"67ccd2be-17f0-8190-81ff-3bb2cf6508e6\\\",\\n                    \\\"input_value\\\": \\\"Process in the background\\\",\\n                    \\\"mode\\\": \\\"background\\\",\\n                },\\n            ],\\n        },\\n    )\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def validate_flow_id(self) -> WorkflowRunRequest:\\n        \\\"\\\"\\\"Reject non-UUID ``flow_id`` early so the endpoint can trust it.\\\"\\\"\\\"\\n        uuid_validator(self.flow_id, message=\\\"Invalid flow_id, must be a UUID\\\")\\n        return self\\n\\n\\nclass PublicWorkflowRunRequest(BaseModel):\\n    \\\"\\\"\\\"Request schema for ``POST /api/v2/workflows/public``.\\n\\n    Narrower than ``WorkflowRunRequest`` so the public-flow surface stays\\n    locked down. Notably absent vs the regular body:\\n\\n    - ``data`` \u2014 visitors must never override the stored flow definition.\\n    - ``tweaks`` \u2014 visitors must never override component parameters.\\n\\n    The endpoint enforces the additional CVE mitigations that the regular\\n    endpoint does not need:\\n\\n    - Canonical PUBLIC-share or legacy ``access_type == PUBLIC`` direct-link\\n      grant (others are hidden as 404).\\n    - ``virtual_flow_id = uuid5(identifier, flow_id)`` so messages stay\\n      isolated per visitor.\\n    - Session string namespaced under the virtual flow id\\n      (CVE-2026-33017).\\n    - File-path validation (GHSA-rcjh-r59h-gq37).\\n    - Anonymous principal isolation: execution cannot inherit the flow owner's\\n      credentials, variables, files, or knowledge bases.\\n    \\\"\\\"\\\"\\n\\n    flow_id: str = Field(..., description=\\\"UUID of the public flow to run.\\\")\\n    input_value: PublicInputValue = Field(\\\"\\\", description=\\\"Chat-style input value.\\\")\\n    session_id: PublicSessionId | None = Field(\\n        None,\\n        description=(\\\"Optional caller session. Always namespaced under the visitor's virtual flow id by the endpoint.\\\"),\\n    )\\n    mode: Literal[WorkflowMode.STREAM] = Field(\\n        WorkflowMode.STREAM,\\n        description=(\\n            \\\"Always ``stream``. Sync/background modes would widen the public \\\"\\n            \\\"attack surface (job polling and anonymous work persists across \\\"\\n            \\\"queue boundaries) so the schema rejects them at the wire.\\\"\\n        ),\\n    )\\n    stream_protocol: str = Field(\\n        \\\"langflow\\\",\\n        description=(\\n            \\\"Wire protocol for streaming events. Defaults to ``langflow`` \\\"\\n            \\\"(raw EventManager payloads). ``agui`` emits AG-UI events. Unknown \\\"\\n            \\\"values return 422 with the available list.\\\"\\n        ),\\n    )\\n    files: list[str] | None = Field(\\n        None,\\n        description=(\\n            \\\"Optional list of pre-uploaded file paths. Each path must be \\\"\\n            \\\"scoped to this flow's own storage namespace; the endpoint \\\"\\n            \\\"rejects path traversal or cross-flow references.\\\"\\n        ),\\n    )\\n    start_component_id: str | None = Field(None, description=\\\"Partial-run start component id.\\\")\\n    stop_component_id: str | None = Field(None, description=\\\"Partial-run stop component id.\\\")\\n\\n    model_config = ConfigDict(\\n        extra=\\\"forbid\\\",\\n        json_schema_extra={\\n            \\\"examples\\\": [\\n                {\\n                    \\\"flow_id\\\": \\\"67ccd2be-17f0-8190-81ff-3bb2cf6508e6\\\",\\n                    \\\"input_value\\\": \\\"Hello from the shareable playground\\\",\\n                },\\n                {\\n                    \\\"flow_id\\\": \\\"67ccd2be-17f0-8190-81ff-3bb2cf6508e6\\\",\\n                    \\\"input_value\\\": \\\"Stream the response\\\",\\n                    \\\"stream_protocol\\\": \\\"agui\\\",\\n                    \\\"session_id\\\": \\\"thread-A\\\",\\n                },\\n            ],\\n        },\\n    )\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def validate_flow_id(self) -> PublicWorkflowRunRequest:\\n        \\\"\\\"\\\"Reject non-UUID ``flow_id`` early so the endpoint can trust it.\\\"\\\"\\\"\\n        uuid_validator(self.flow_id, message=\\\"Invalid flow_id, must be a UUID\\\")\\n        return self\\n\\n\\nclass WorkflowExecutionResponse(BaseModel):\\n    \\\"\\\"\\\"Synchronous workflow execution response.\\\"\\\"\\\"\\n\\n    flow_id: str\\n    session_id: str | None = Field(\\n        default=None,\\n        description=(\\n            \\\"The session the run executed under. Echoes the request ``session_id`` \\\"\\n            \\\"when provided, otherwise the server-generated one. Pass it back on the \\\"\\n            \\\"next call to continue the same chat history / memory thread.\\\"\\n        ),\\n    )\\n    job_id: JobId | None = None\\n    object: Literal[\\\"response\\\"] = Field(default=\\\"response\\\")\\n    created_timestamp: str = Field(default_factory=lambda: datetime.now(timezone.utc).isoformat())\\n    status: JobStatus\\n    output: WorkflowOutput = Field(\\n        default_factory=lambda: WorkflowOutput(reason=OutputReason.NONE),\\n        description=(\\n            \\\"The run's text answer plus why it resolved that way. Read ``output.text`` for the \\\"\\n            \\\"answer; when it's null, ``output.reason`` says why (``multiple`` / ``none`` / \\\"\\n            \\\"``non_string`` / ``failed``) so you know whether to read ``outputs``.\\\"\\n        ),\\n    )\\n    errors: list[ErrorDetail] = []\\n    warnings: list[str] = Field(\\n        default_factory=list,\\n        description=\\\"Non-fatal notices about this run, such as saved component code being replaced by server code.\\\",\\n    )\\n    inputs: dict[str, Any] = {}\\n    globals: dict[GlobalVarKey, GlobalVarValue] = Field(default_factory=dict)\\n    outputs: dict[str, ComponentOutput] = {}\\n    human_request: dict[str, Any] | None = Field(\\n        default=None,\\n        description=(\\n            \\\"Set when ``status`` is ``suspended``: the human-input request the run paused on \\\"\\n            \\\"(``prompt``, ``options``, ``allowed_decisions``, ``request_id``). Resume by running \\\"\\n            \\\"the same session/task again with the chosen decision.\\\"\\n        ),\\n    )\\n\\n    @computed_field\\n    @property\\n    def has_errors(self) -> bool:\\n        \\\"\\\"\\\"True when the run reported any error. Derived from ``errors`` so it can't drift.\\\"\\\"\\\"\\n        return len(self.errors) > 0\\n\\n\\nclass WorkflowJobResponse(BaseModel):\\n    \\\"\\\"\\\"Background job response.\\\"\\\"\\\"\\n\\n    job_id: JobId\\n    flow_id: str\\n    object: Literal[\\\"job\\\"] = Field(default=\\\"job\\\")\\n    created_timestamp: str = Field(default_factory=lambda: datetime.now(timezone.utc).isoformat())\\n    status: JobStatus\\n    links: dict[str, str] = Field(default_factory=dict)\\n    errors: list[ErrorDetail] = []\\n    globals: dict[GlobalVarKey, GlobalVarValue] = Field(default_factory=dict)\\n\\n    @model_validator(mode=\\\"after\\\")\\n    def build_links(self) -> WorkflowJobResponse:\\n        \\\"\\\"\\\"Automatically populate links for the client.\\\"\\\"\\\"\\n        if not self.links:\\n            self.links = {\\n                \\\"status\\\": f\\\"/api/v2/workflows?job_id={self.job_id!s}\\\",\\n                \\\"events\\\": f\\\"/api/v2/workflows/{self.job_id!s}/events\\\",\\n                \\\"stop\\\": \\\"/api/v2/workflows/stop\\\",\\n            }\\n        return self\\n\\n\\nclass WorkflowStreamEvent(BaseModel):\\n    \\\"\\\"\\\"Streaming event response.\\\"\\\"\\\"\\n\\n    type: str\\n    run_id: str\\n    timestamp: int\\n    raw_event: dict[str, Any]\\n\\n\\nclass WorkflowStopRequest(BaseModel):\\n    \\\"\\\"\\\"Request schema for stopping workflow.\\\"\\\"\\\"\\n\\n    job_id: JobId\\n\\n\\nclass WorkflowStopResponse(BaseModel):\\n    \\\"\\\"\\\"Response schema for stopping workflow.\\\"\\\"\\\"\\n\\n    job_id: JobId\\n    message: str | None = None\\n\\n\\nclass WorkflowResumeRequest(BaseModel):\\n    \\\"\\\"\\\"Request schema for resuming a suspended (human-in-the-loop) workflow.\\\"\\\"\\\"\\n\\n    request_id: str\\n    decision: dict | None = None\\n\\n\\nclass WorkflowResumeResponse(BaseModel):\\n    \\\"\\\"\\\"Response schema for resuming a workflow.\\\"\\\"\\\"\\n\\n    job_id: JobId\\n    status: str\\n    message: str | None = None\\n\\n\\n# OpenAPI response definitions\\nWORKFLOW_EXECUTION_RESPONSES = {\\n    200: {\\n        \\\"description\\\": \\\"Workflow execution response\\\",\\n        \\\"content\\\": {\\n            \\\"application/json\\\": {\\n                \\\"schema\\\": {\\n                    \\\"oneOf\\\": [\\n                        WorkflowExecutionResponse.model_json_schema(),\\n                        WorkflowJobResponse.model_json_schema(),\\n                    ],\\n                    \\\"discriminator\\\": {\\n                        \\\"propertyName\\\": \\\"object\\\",\\n                        \\\"mapping\\\": {\\n                            \\\"response\\\": \\\"#/components/schemas/WorkflowExecutionResponse\\\",\\n                            \\\"job\\\": \\\"#/components/schemas/WorkflowJobResponse\\\",\\n                        },\\n                    },\\n                }\\n            },\\n            \\\"text/event-stream\\\": {\\n                \\\"schema\\\": WorkflowStreamEvent.model_json_schema(),\\n                \\\"description\\\": \\\"Server-sent events for streaming execution\\\",\\n            },\\n        },\\n    }\\n}\\n\\nWORKFLOW_STATUS_RESPONSES = {\\n    200: {\\n        \\\"description\\\": \\\"Workflow status response\\\",\\n        \\\"content\\\": {\\n            \\\"application/json\\\": {\\\"schema\\\": WorkflowExecutionResponse.model_json_schema()},\\n            \\\"text/event-stream\\\": {\\n                \\\"schema\\\": WorkflowStreamEvent.model_json_schema(),\\n                \\\"description\\\": \\\"Server-sent events for streaming status\\\",\\n            },\\n        },\\n    }\\n}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/template/frontend_node/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"90fa9bed77eb701bc600b5267d829b1c881332527e50348b70ff3f247c12865c\",\"content\":\"from lfx.template.frontend_node import base, custom_components\\n\\n__all__ = [\\n    \\\"base\\\",\\n    \\\"custom_components\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/template/frontend_node/base.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9c7a129de33ad3efdb5e776e87b7f9766dd84eb2df1b1faad70cc7515a73dedc\",\"content\":\"from collections import defaultdict\\n\\nfrom pydantic import BaseModel, field_serializer, model_serializer\\n\\nfrom lfx.template.field.base import Output\\nfrom lfx.template.template.base import Template\\n\\n\\nclass FrontendNode(BaseModel):\\n    _format_template: bool = True\\n    template: Template\\n    \\\"\\\"\\\"Template for the frontend node.\\\"\\\"\\\"\\n    description: str | None = None\\n    \\\"\\\"\\\"Description of the frontend node.\\\"\\\"\\\"\\n    icon: str | None = None\\n    \\\"\\\"\\\"Icon of the frontend node.\\\"\\\"\\\"\\n    is_input: bool | None = None\\n    \\\"\\\"\\\"Whether the frontend node is used as an input when processing the Graph.\\n    If True, there should be a field named 'input_value'.\\\"\\\"\\\"\\n    is_output: bool | None = None\\n    \\\"\\\"\\\"Whether the frontend node is used as an output when processing the Graph.\\n    If True, there should be a field named 'input_value'.\\\"\\\"\\\"\\n    is_composition: bool | None = None\\n    \\\"\\\"\\\"Whether the frontend node is used for composition.\\\"\\\"\\\"\\n    base_classes: list[str]\\n    \\\"\\\"\\\"List of base classes for the frontend node.\\\"\\\"\\\"\\n    name: str = \\\"\\\"\\n    \\\"\\\"\\\"Name of the frontend node.\\\"\\\"\\\"\\n    display_name: str | None = \\\"\\\"\\n    \\\"\\\"\\\"Display name of the frontend node.\\\"\\\"\\\"\\n    priority: int | None = None\\n    \\\"\\\"\\\"Priority of the frontend node.\\\"\\\"\\\"\\n    documentation: str = \\\"\\\"\\n    \\\"\\\"\\\"Documentation of the frontend node.\\\"\\\"\\\"\\n    minimized: bool = False\\n    \\\"\\\"\\\"Whether the frontend node is minimized.\\\"\\\"\\\"\\n    custom_fields: dict | None = defaultdict(list)\\n    \\\"\\\"\\\"Custom fields of the frontend node.\\\"\\\"\\\"\\n    output_types: list[str] = []\\n    \\\"\\\"\\\"List of output types for the frontend node.\\\"\\\"\\\"\\n    full_path: str | None = None\\n    \\\"\\\"\\\"Full path of the frontend node.\\\"\\\"\\\"\\n    pinned: bool = False\\n    \\\"\\\"\\\"Whether the frontend node is pinned.\\\"\\\"\\\"\\n    conditional_paths: list[str] = []\\n    \\\"\\\"\\\"List of conditional paths for the frontend node.\\\"\\\"\\\"\\n    frozen: bool = False\\n    \\\"\\\"\\\"Whether the frontend node is frozen.\\\"\\\"\\\"\\n    outputs: list[Output] = []\\n    \\\"\\\"\\\"List of output fields for the frontend node.\\\"\\\"\\\"\\n\\n    field_order: list[str] = []\\n    \\\"\\\"\\\"Order of the fields in the frontend node.\\\"\\\"\\\"\\n    beta: bool = False\\n    \\\"\\\"\\\"Whether the frontend node is in beta.\\\"\\\"\\\"\\n    legacy: bool = False\\n    \\\"\\\"\\\"Whether the frontend node is legacy.\\\"\\\"\\\"\\n    replacement: list[str] | None = None\\n    \\\"\\\"\\\"Replacement for the frontend node when it is deprecated.\\\"\\\"\\\"\\n    error: str | None = None\\n    \\\"\\\"\\\"Error message for the frontend node.\\\"\\\"\\\"\\n    edited: bool = False\\n    \\\"\\\"\\\"Whether the frontend node has been edited.\\\"\\\"\\\"\\n    metadata: dict = {}\\n    \\\"\\\"\\\"Metadata for the component node.\\\"\\\"\\\"\\n    tool_mode: bool = False\\n    \\\"\\\"\\\"Whether the frontend node is in tool mode.\\\"\\\"\\\"\\n    add_tool_output: bool | None = None\\n    \\\"\\\"\\\"Whether the component synthesizes a toolset output without a tool_mode input.\\n\\n    The other half of ``Component._handle_tool_mode``. Serialized only when set\\n    (None is excluded from ``to_dict``), so consumers reading a template \u2014 the\\n    flow builder, the MCP registry \u2014 can state the runtime rule exactly instead\\n    of guessing from output-side ``tool_mode``.\\n    \\\"\\\"\\\"\\n\\n    def set_documentation(self, documentation: str) -> None:\\n        \\\"\\\"\\\"Sets the documentation of the frontend node.\\\"\\\"\\\"\\n        self.documentation = documentation\\n\\n    @field_serializer(\\\"base_classes\\\")\\n    def process_base_classes(self, base_classes: list[str]) -> list[str]:\\n        \\\"\\\"\\\"Removes unwanted base classes from the list of base classes.\\\"\\\"\\\"\\n        return sorted(set(base_classes), key=lambda x: x.lower())\\n\\n    @field_serializer(\\\"display_name\\\")\\n    def process_display_name(self, display_name: str) -> str:\\n        \\\"\\\"\\\"Sets the display name of the frontend node.\\\"\\\"\\\"\\n        return display_name or self.name\\n\\n    @model_serializer(mode=\\\"wrap\\\")\\n    def serialize_model(self, handler):\\n        result = handler(self)\\n        if hasattr(self, \\\"template\\\") and hasattr(self.template, \\\"to_dict\\\"):\\n            result[\\\"template\\\"] = self.template.to_dict()\\n        name = result.pop(\\\"name\\\")\\n\\n        # Migrate base classes to outputs\\n        if \\\"output_types\\\" in result and not result.get(\\\"outputs\\\"):\\n            for base_class in result[\\\"output_types\\\"]:\\n                output = Output(\\n                    display_name=base_class,\\n                    name=base_class.lower(),\\n                    types=[base_class],\\n                    selected=base_class,\\n                )\\n                result[\\\"outputs\\\"].append(output.model_dump())\\n\\n        return {name: result}\\n\\n    @classmethod\\n    def from_dict(cls, data: dict) -> \\\"FrontendNode\\\":\\n        if \\\"template\\\" in data:\\n            data[\\\"template\\\"] = Template.from_dict(data[\\\"template\\\"])\\n        return cls(**data)\\n\\n    # For backwards compatibility\\n    def to_dict(self, *, keep_name=True) -> dict:\\n        \\\"\\\"\\\"Returns a dict representation of the frontend node.\\\"\\\"\\\"\\n        dump = self.model_dump(by_alias=True, exclude_none=True)\\n        if not keep_name:\\n            return dump.pop(self.name)\\n        return dump\\n\\n    def add_extra_fields(self) -> None:\\n        pass\\n\\n    def add_extra_base_classes(self) -> None:\\n        pass\\n\\n    def set_base_classes_from_outputs(self) -> None:\\n        self.base_classes = [output_type for output in self.outputs for output_type in output.types]\\n\\n    def validate_component(self) -> None:\\n        self.validate_name_overlap()\\n        self.validate_attributes()\\n\\n    def validate_name_overlap(self) -> None:\\n        # Check if any of the output names overlap with the any of the inputs\\n        output_names = [output.name for output in self.outputs if not output.allows_loop]\\n        input_names = [input_.name for input_ in self.template.fields]\\n        overlap = set(output_names).intersection(input_names)\\n        if overlap:\\n            overlap_str = \\\", \\\".join(f\\\"'{x}'\\\" for x in overlap)\\n            msg = (\\n                \\\"There should be no overlap between input and output names. \\\"\\n                f\\\"Names {overlap_str} are duplicated in component {self.display_name}. \\\"\\n                f\\\"Inputs are {input_names} and outputs are {output_names}.\\\"\\n            )\\n            raise ValueError(msg)\\n\\n    def validate_attributes(self) -> None:\\n        # None of inputs, outputs, _artifacts, _results, logs, status, vertex, graph, display_name, description,\\n        # documentation, icon should be present in outputs or input names\\n        output_names = [output.name for output in self.outputs]\\n        input_names = [input_.name for input_ in self.template.fields]\\n        attributes = [\\n            \\\"inputs\\\",\\n            \\\"outputs\\\",\\n            \\\"_artifacts\\\",\\n            \\\"_results\\\",\\n            \\\"logs\\\",\\n            \\\"status\\\",\\n            \\\"vertex\\\",\\n            \\\"graph\\\",\\n            \\\"display_name\\\",\\n            \\\"description\\\",\\n            \\\"documentation\\\",\\n            \\\"icon\\\",\\n        ]\\n        output_overlap = set(output_names).intersection(attributes)\\n        input_overlap = set(input_names).intersection(attributes)\\n        error_message = \\\"\\\"\\n        if output_overlap:\\n            output_overlap_str = \\\", \\\".join(f\\\"'{x}'\\\" for x in output_overlap)\\n            error_message += f\\\"Output names {output_overlap_str} are reserved attributes.\\\\n\\\"\\n        if input_overlap:\\n            input_overlap_str = \\\", \\\".join(f\\\"'{x}'\\\" for x in input_overlap)\\n            error_message += f\\\"Input names {input_overlap_str} are reserved attributes.\\\"\\n\\n    def add_base_class(self, base_class: str | list[str]) -> None:\\n        \\\"\\\"\\\"Adds a base class to the frontend node.\\\"\\\"\\\"\\n        if isinstance(base_class, str):\\n            self.base_classes.append(base_class)\\n        elif isinstance(base_class, list):\\n            self.base_classes.extend(base_class)\\n\\n    def add_output_type(self, output_type: str | list[str]) -> None:\\n        \\\"\\\"\\\"Adds an output type to the frontend node.\\\"\\\"\\\"\\n        if isinstance(output_type, str):\\n            self.output_types.append(output_type)\\n        elif isinstance(output_type, list):\\n            self.output_types.extend(output_type)\\n\\n    @classmethod\\n    def from_inputs(cls, **kwargs):\\n        \\\"\\\"\\\"Create a frontend node from inputs.\\\"\\\"\\\"\\n        if \\\"inputs\\\" not in kwargs:\\n            msg = \\\"Missing 'inputs' argument.\\\"\\n            raise ValueError(msg)\\n        if \\\"_outputs_map\\\" in kwargs:\\n            kwargs[\\\"outputs\\\"] = kwargs.pop(\\\"_outputs_map\\\")\\n        inputs = kwargs.pop(\\\"inputs\\\")\\n        template = Template(type_name=\\\"Component\\\", fields=inputs)\\n        kwargs[\\\"template\\\"] = template\\n        return cls(**kwargs)\\n\\n    def set_field_value_in_template(self, field_name, value) -> None:\\n        for idx, field in enumerate(self.template.fields):\\n            if field.name == field_name:\\n                new_field = field.model_copy()\\n                new_field.value = value\\n                self.template.fields[idx] = new_field\\n                break\\n\\n    def set_field_load_from_db_in_template(self, field_name, value) -> None:\\n        for idx, field in enumerate(self.template.fields):\\n            if field.name == field_name and hasattr(field, \\\"load_from_db\\\"):\\n                new_field = field.model_copy()\\n                new_field.load_from_db = value\\n                self.template.fields[idx] = new_field\\n                break\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/template/frontend_node/constants.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"481c695ebf314a13eff3eb32dbace8c06f708e87b93acca19fd2d1f6819a3de6\",\"content\":\"FORCE_SHOW_FIELDS = [\\n    \\\"allowed_tools\\\",\\n    \\\"memory\\\",\\n    \\\"prefix\\\",\\n    \\\"examples\\\",\\n    \\\"temperature\\\",\\n    \\\"model_name\\\",\\n    \\\"headers\\\",\\n    \\\"max_value_length\\\",\\n    \\\"max_tokens\\\",\\n    \\\"google_cse_id\\\",\\n]\\n\\nDEFAULT_PROMPT = \\\"\\\"\\\"\\nI want you to act as a naming consultant for new companies.\\n\\nHere are some examples of good company names:\\n\\n- search engine, Google\\n- social media, Facebook\\n- video sharing, YouTube\\n\\nThe name should be short, catchy and easy to remember.\\n\\nWhat is a good name for a company that makes {product}?\\n\\\"\\\"\\\"\\n\\nSYSTEM_PROMPT = \\\"\\\"\\\"\\nYou are a helpful assistant that talks casually about life in general.\\nYou are a good listener and you can talk about anything.\\n\\\"\\\"\\\"\\n\\nHUMAN_PROMPT = \\\"{input}\\\"\\n\\nQA_CHAIN_TYPES = [\\\"stuff\\\", \\\"map_reduce\\\", \\\"map_rerank\\\", \\\"refine\\\"]\\n\\nCTRANSFORMERS_DEFAULT_CONFIG = {\\n    \\\"top_k\\\": 40,\\n    \\\"top_p\\\": 0.95,\\n    \\\"temperature\\\": 0.8,\\n    \\\"repetition_penalty\\\": 1.1,\\n    \\\"last_n_tokens\\\": 64,\\n    \\\"seed\\\": -1,\\n    \\\"max_new_tokens\\\": 256,\\n    \\\"stop\\\": None,\\n    \\\"stream\\\": False,\\n    \\\"reset\\\": True,\\n    \\\"batch_size\\\": 8,\\n    \\\"threads\\\": -1,\\n    \\\"context_length\\\": -1,\\n    \\\"gpu_layers\\\": 0,\\n}\\n\\n# This variable is used to tell the user\\n# that it can be changed to use other APIs\\n# like Prem and LocalAI\\nOPENAI_API_BASE_INFO = \\\"\\\"\\\"\\nThe base URL of the OpenAI API. Defaults to https://api.openai.com/v1.\\n\\nYou can change this to use other APIs like JinaChat, LocalAI and Prem.\\n\\\"\\\"\\\"\\n\\n\\nINPUT_KEY_INFO = \\\"\\\"\\\"The variable to be used as Chat Input when more than one variable is available.\\\"\\\"\\\"\\nOUTPUT_KEY_INFO = \\\"\\\"\\\"The variable to be used as Chat Output (e.g. answer in a ConversationalRetrievalChain)\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/template/frontend_node/custom_components.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1b69d2fafcaef0a0febf13c25b8c5fbdb80adfec6e4a8ad207ca489b73b51edc\",\"content\":\"from lfx.template.field.base import Input\\nfrom lfx.template.frontend_node.base import FrontendNode\\nfrom lfx.template.template.base import Template\\n\\nDEFAULT_CUSTOM_COMPONENT_CODE = \\\"\\\"\\\"from lfx.custom import CustomComponent\\n\\nfrom typing import Optional, List, Dict, Union\\nfrom lfx.field_typing import (\\n    Tool,\\n)\\nfrom lfx.schema.data import Data\\n\\n\\nclass Component(CustomComponent):\\n    display_name: str = \\\"Custom Component\\\"\\n    description: str = \\\"Create any custom component you want!\\\"\\n\\n    def build_config(self):\\n        return {\\\"param\\\": {\\\"display_name\\\": \\\"Parameter\\\"}}\\n\\n    def build(self, param: Data) -> Data:\\n        return param\\n\\n\\\"\\\"\\\"\\n\\n\\nclass CustomComponentFrontendNode(FrontendNode):\\n    _format_template: bool = False\\n    name: str = \\\"CustomComponent\\\"\\n    display_name: str | None = \\\"CustomComponent\\\"\\n    beta: bool = False\\n    legacy: bool = False\\n    minimized: bool = False\\n    template: Template = Template(\\n        type_name=\\\"CustomComponent\\\",\\n        fields=[\\n            Input(\\n                field_type=\\\"code\\\",\\n                required=True,\\n                placeholder=\\\"\\\",\\n                is_list=False,\\n                show=True,\\n                value=DEFAULT_CUSTOM_COMPONENT_CODE,\\n                name=\\\"code\\\",\\n                advanced=False,\\n      ";
